const m=[{schemaVersion:2,revision:2,id:"confidence-2",courseId:"confidence",locale:"en",title:"Still rehearsing? Give your idea a listener",goal:"Use a smaller version of your chosen sentence at one safe, real opening.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Still rehearsing a ready sentence? Give it one manageable opening.",reason:{id:"polishing-cost-at-safe-opening",label:"If you've polished instead of using a safe opening, what did waiting cost?",kind:"text",maxLength:160,optional:!0,suggestions:["Let someone hear my idea","Ask for needed information","Stop preparing without trying"]},why:{id:"why-smaller-opening",label:"Why does this opening serve your chosen direction?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Keep the sentence and direction from your first lesson. Change its audience or setting if the opening was too demanding. A smaller conversation can still use the skill. Rewriting a ready sentence alone is preparation, even when it feels easier.","Gradual practice starts with manageable situations. You can learn from the reply while still feeling afraid. Choose one safe listener or message channel. You can repeat the same step rather than advance. If you need information first, prepare it and date the real opening. Overwhelming anxiety calls for support, not a harder challenge."],example:{title:"Ben tries his ready question",text:"At Tuesday lunch, Ben rereads the question he prepared in lesson one. Instead of rewriting it again, he sends it to a trusted colleague: “Could we test this shorter checklist?” The colleague asks which shift he means. Ben answers. The idea remains undecided, but he has used his sentence with a real listener."}},move:{invitation:"Keep your sentence. Choose its next manageable, safe opening.",instructions:["Keep your saved sentence and minimum. Edit only the listener or channel if needed.","Name the actual check-in and place before saving; record what you say and hear."],prompts:[{id:"actual-smaller-opening",label:"Who can hear your saved sentence, and at which actual check-in?",kind:"text",maxLength:160,optional:!0,visible:!0}],suggestions:{action:["Ask: Could we test the shorter checklist?","Send my chosen idea to my colleague","Make my saved request privately"],minimum:["Use one prepared sentence","Send one useful sentence"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],cue:["At lunch with my trusted colleague","At today's 3 p.m. team check-in"],place:["At our usual lunch table","In our trusted colleague message thread"],minutes:[2,1,5],fallback:["Send the sentence after our lunch check-in","Use my note without rewriting the sentence"],observation:["Whether I used my sentence","The reply, including no reply"]},suggested:{action:"Ask: Could we test the shorter checklist?",minimum:"Use one prepared sentence",minutes:2,cueHint:"At lunch with my trusted colleague",placeHint:"At our usual lunch table",obstacleHint:"Our lunch check-in is canceled",fallbackHint:"Send the sentence after our lunch check-in",observationHint:"Whether I used my sentence"},stopRule:"Pause for danger or overwhelming distress. Seek support when anxiety disrupts daily life.",accessibleAlternative:"Type, sign, or use your usual communication aid. Preparation needs a dated real opening."},result:{question:"Did you use your sentence at the chosen opening?",observationPrompt:"What did you say or send, and what response followed?"},judgment:{primary:{id:"ready-question-smaller-opening",scenario:"Ben has rewritten his question three times. A trusted colleague offers a private check-in. The team presentation still feels overwhelming.",question:"Which experiment fits the available opening?",options:[{id:"private-ready-question",text:"Ask the ready question in the private check-in and record the actual response afterward.",feedback:"This uses the same skill in a manageable setting with a real listener. Ben can learn from the reply without needing to feel calm or commit to a presentation."},{id:"polish-first",text:"Use the check-in to request another script review, then decide when to ask the question.",feedback:"Another review is useful if information is missing. Here the question is ready. More polishing postpones using it, so choose the smaller real opening already available."},{id:"book-presentation",text:"Book a full team presentation next week so the experiment has a more ambitious target.",feedback:"A larger audience may matter later, but it misses the manageable opening available now. Ben can use the private question first, then choose whether to repeat or change the setting."}],bestOptionId:"private-ready-question"}},carry:{takeaway:"A smaller opening should let you use the skill, not keep you preparing indefinitely.",identityExample:"If you used your sentence: “I gave my idea a listener.”",followUp:{questionId:"smaller-opening-result",question:"Did the smaller opening let you use your sentence, or did it remain preparation?",observationPrompt:"What action and reply are in your record?",adjustmentPrompt:"Repeat, change the opening, or get support?"}},goDeeper:{sourceIds:["CF12","CF11","CF13"],sections:[{heading:"Gradual practice has more than one model",paragraphs:["NHS guidance suggests listing feared situations, rating their difficulty, and beginning with easier situations. It uses a fear-halving rule for progression. That is guidance, not a universal experimentally validated cutoff. The old ODA rules about starting at three or four out of ten, or advancing after two low ratings, were not established by this evidence. Optional ratings can describe your experience without deciding whether an attempt counts. [CF12]","A clinical review by Craske and colleagues emphasizes comparing a specific feared prediction with the result. Immediate fear reduction is not its necessary stopping criterion. These approaches differ. ODA borrows the manageable-step idea for ordinary, chosen situations, without reproducing exposure therapy. A ready sentence used with one safe listener is a real speaking attempt. Privately rehearsing it is preparation. Neither guarantees a confidence increase. [CF11, CF12]"]},{heading:"Keep choice and protection inside the experiment",paragraphs:["A smaller step is not automatically a safer step. A private message can still carry workplace, family, or cultural risks. Choose a setting where the act is safe for you. Preserve real protections and boundaries. The clinical learning review does not authorize removing safeguards, enduring abuse, or working through trauma triggers alone. You may stop or choose support without proving that fear has fallen first. [CF11]","NIMH advises seeking professional help when social fear interferes with daily activities. A provider assesses the situation; this course cannot diagnose its cause. Help can be appropriate before completing any lesson or trying repeatedly. If the difficulty is missing information, prepare that information and name a later opening. If it is danger or overwhelming distress, changing the setting or getting support can be the useful next act. Record the act you actually choose. [CF13]"]}]}},{schemaVersion:2,revision:2,id:"confidence-3",courseId:"confidence",locale:"en",title:"One awkward reply is not the whole story",goal:"Record your sentence and reply; compare a prediction only if you saved one beforehand.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"If the reply stung, what did it actually tell you to change?",reason:{id:"reason-for-factual-record",label:"What matters more here than looking flawless?",kind:"text",maxLength:160,optional:!0,suggestions:["Learn from actual feedback","Keep contributing useful questions","Protect myself when needed"]},why:{id:"why-record-speaking",label:"What will a factual record help you decide?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Return to your chosen speaking move. Before its next opening, save one specific prediction if you want to compare it later. An old prediction you reconstruct afterward is a memory, not a saved forecast. Use the sentence, then record your action and the actual reply.","Monitoring progress has helped goal pursuit across many studies, but this short record is an untested adaptation. Keep feelings alongside facts: “I asked; they said we covered it; I felt embarrassed.” The words do not establish their intent. Keep genuine criticism or mistreatment in view. Choose a revision, support, or boundary from what happened."],example:{title:"Lucas keeps the difficult reply",text:"Before Thursday’s check-in, Lucas saves: “My question will be dismissed.” He asks about the timeline. A colleague says, “We covered that yesterday.” In a quiet corner, Lucas records those words and his embarrassment. He checks yesterday’s notes before choosing his next question. He still dislikes the exchange; the record includes both his act and the criticism."}},move:{invitation:"Use your same speaking move. Keep the reply in the record.",instructions:["Keep your actual sentence; save an optional prediction before this opening.","After trying, record your action, reply, and any uncertainty."],prompts:[{id:"prediction-before-opening",label:"Before trying, what specific response do you predict?",help:"Skip prediction to record only your act and reply.",kind:"text",maxLength:300,optional:!0,planField:"prediction"}],suggestions:{action:["Ask: Could you clarify the deadline?","Share my saved idea and record response"],minimum:["Use one prepared sentence","Send one useful question"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],cue:["At today's 3 p.m. team check-in","After lunch in our colleague message thread"],place:["In our team room","In our trusted colleague message thread"],minutes:[2,1,5],fallback:["Send the sentence after our lunch check-in","Use my note without rewriting the sentence"],observation:["My action and the actual reply","What remains uncertain about the response"]},suggested:{action:"Ask: Could you clarify the deadline?",minimum:"Use one prepared sentence",minutes:2,cueHint:"At today's 3 p.m. team check-in",placeHint:"In our team room",obstacleHint:"Our check-in ends before questions",fallbackHint:"Send the sentence after our lunch check-in",observationHint:"My action and the actual reply"},stopRule:"Stop for danger or overwhelming distress. A factual record never requires tolerating mistreatment.",accessibleAlternative:"Use a safe message or communication aid. Keep the note privately if preferred."},result:{question:"Did you use your sentence?",observationPrompt:"What happened, what did you feel, and what remains uncertain?"},judgment:{primary:{id:"critical-reply-complete-record",scenario:"Lucas asks his question. A colleague says, “We covered that yesterday.” His voice shakes, and he feels embarrassed.",question:"Which record best guides the next attempt?",options:[{id:"postpone-feedback-review",text:"Record the question and nervousness today, then review his wording tomorrow before deciding whether feedback needs action.",feedback:"Tracking the act and tension is useful, but postponing the reply loses context for tomorrow. Keep the colleague’s words alongside the question now, then review both before choosing an adjustment."},{id:"private-only-route",text:"Record the reply and choose private messages for all future questions to avoid interrupting another meeting.",feedback:"A private route may be useful, especially if a harmful pattern emerges. This one reply does not establish intent. Record the words before deciding what boundary or adjustment fits."},{id:"keep-facts-feeling",text:"Record his question, the exact reply, and embarrassment; check the earlier notes before his next question.",feedback:"This preserves both the act and inconvenient feedback without inventing intent. Checking the notes addresses a possible information gap. He can still seek support if the treatment becomes harmful."}],bestOptionId:"keep-facts-feeling"}},carry:{takeaway:"Keep your action, the reply, and your feelings. Let uncertainty stay uncertain.",identityExample:"If you recorded the reply: “I kept the difficult feedback in view.”",followUp:{questionId:"prediction-and-reply-result",question:"What did the actual reply change about your next speaking move?",observationPrompt:"Compare the saved prediction, if any, with the reply.",adjustmentPrompt:"What information, support, or boundary fits next?"}},goDeeper:{sourceIds:["CF04","CF11","CF02"],sections:[{heading:"Monitoring helps goals, with a transfer limit",paragraphs:["Harkin and colleagues combined 138 randomized studies involving 19,951 people. Interventions that increased monitoring improved goal attainment on average, with a standardized effect of 0.40. Goals and methods varied. Physical recording and reporting were associated with larger effects in moderator analyses. Those comparisons do not make public sharing necessary, and they do not show that this particular two-minute record changes confidence. You can keep your notes private. [CF04]","The useful distinction here is between a plan, an act, and its external result. A saved sentence is a plan. Saying or sending it is an act. Agreement, refusal, criticism, or no reply is a separate result. Record only what you know. If you did not save a prediction before the opening, do not manufacture one for the comparison. Your next attempt can include a new prediction. The exact ODA record and schedule remain an adaptation. [CF04, CF11]"]},{heading:"Evidence can challenge both pessimism and a weak plan",paragraphs:["The learning-focused exposure review emphasizes a specific prediction and what actually occurs. It does not establish that every reflection method prevents rumination, nor does it require an attempt to end calmly. ODA applies the prediction-versus-result distinction to an ordinary safe speaking move. A record can show that you contributed while tense. It can also show that you needed more information, a different setting, or a protective boundary. Disappointing information still belongs in the record. [CF11]","A meta-analysis of repeated measurements found past performance more strongly related to later task confidence than the reverse after controlling linear trends. Its 38-study, 5,414-person count describes a separate comparison between people. These relationships do not settle causality or prove that a tiny act changes global self-belief. Use your records to choose the next attempt, leaving room for skill gaps and external constraints. [CF02]"]}]}},{schemaVersion:2,revision:2,id:"confidence-4",courseId:"confidence",locale:"en",title:"Calling yourself careless will not fix the mistake",goal:"Use your speaking record to make one repair you owe, or choose support when you do not.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"After the awkward moment, what is actually yours to repair?",reason:{id:"repair-versus-reassurance",label:"What is yours to repair, and are you fixing it or seeking reassurance?",kind:"text",maxLength:160,optional:!0,suggestions:["Correct my wrong information","Repair my missed commitment","Nothing mine to repair; choose support"]},why:{id:"why-speaking-repair",label:"What would a useful repair change here?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Check your speaking record. Did you give wrong information, miss a commitment, or simply receive an uncomfortable reply? Those call for different next moves. Do not apologize for someone else’s harmful behavior. Identify the part that is yours before choosing a repair.","Compassionate writing increased students’ motivation to make amends in an experiment; motivation was not completed repair. Use a fair sentence, then act: correct a detail, propose a replacement time, or ask for support. This brief adaptation is not treatment. Embarrassment can remain after the repair. Record what you actually changed."],example:{title:"Fatima corrects the date",text:"After sharing the trip date in Tuesday’s staff chat, Fatima sees that she gave the wrong day. She says privately, “The date was wrong; I can correct it.” She sends the correct date to the same group and adds a calendar check for next time. She remains embarrassed. Her record names the correction, not a verdict about her competence."}},move:{invitation:"Use your record. Repair your part, or choose appropriate support.",instructions:["Check responsibility, then select a matching repair or support example below.","Name the actual detail or support request; use a safe route."],prompts:[{id:"repair-or-support-choice",label:"Which applies: a repair I owe, or support without taking blame?",kind:"choice",options:[{id:"repair-owed",label:"Repair I owe"},{id:"support-without-blame",label:"Nothing mine to repair; choose support"}],optional:!0,visible:!0}],suggestions:{action:["Send checked trip date to staff chat","Offer next Tuesday lunch as replacement meeting","Ask a trusted person for specific support"],minimum:["Send the correct trip date","Send the replacement time offer","Send the support request"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],cue:["After checking the trip date at lunch","After lunch when my trusted friend is available"],place:["In the original safe message thread","In a private trusted conversation"],minutes:[2,1,5],fallback:["Use another safe route; pause unsafe contact","Ask a trusted person for support"],observation:["The date correction and any reply","The repair offered and response","My support request and any reply"],bundles:[{action:"Send checked trip date to staff chat",minimum:"Send the correct trip date",cue:"After checking the trip date at lunch",place:"In the original safe message thread",fallback:"Use another safe route; pause unsafe contact",observation:"The date correction and any reply",minutes:2,kind:"practice"},{action:"Offer next Tuesday lunch as replacement meeting",minimum:"Send the replacement time offer",cue:"After checking my calendar at lunch",place:"In the original safe message thread",fallback:"Use another safe route; pause unsafe contact",observation:"The repair offered and any reply",minutes:2,kind:"practice"},{action:"Ask a trusted person for specific support",minimum:"Send the support request",cue:"After lunch when my trusted friend is available",place:"In our private message thread",fallback:"Ask another trusted person; pause unsafe contact",observation:"My support request and any reply",minutes:2,kind:"support"}]},suggested:{requiresChoice:!0,action:"Send checked trip date to staff chat",minimum:"Send the correct trip date",minutes:2,cueHint:"After checking the trip date at lunch",placeHint:"In the original safe message thread",obstacleHint:"This safe contact route is unavailable",fallbackHint:"Use another safe route; pause unsafe contact",observationHint:"The date correction and any reply"},stopRule:"If a safe route is unavailable, use another. If contact is unsafe, pause and seek protection or support.",accessibleAlternative:"Type, sign, use assistance, or make a support request. A reply is not required."},result:{question:"Did you carry out your chosen repair or support step?",observationPrompt:"What did you correct, offer, or request, and what response followed?"},judgment:{primary:{id:"wrong-date-useful-repair",scenario:"Fatima gave the wrong date in a safe staff chat. A colleague points it out. She has checked the correct date.",question:"Which response addresses the actual problem?",options:[{id:"correct-and-check",text:"Send the correct date to the group and add a date check for her next update.",feedback:"This addresses the information people need and a possible recurrence. Fatima can speak fairly to herself while doing the repair. Feeling less embarrassed is not required."},{id:"explain-shame-first",text:"Message the colleague about how embarrassed she feels and ask whether people still trust her.",feedback:"Seeking support can be reasonable, but reassurance does not correct the group’s information. Send the checked date first through the safe thread, then choose support if wanted."},{id:"rewrite-next-update",text:"Privately improve her next update template and leave the current chat to avoid more disruption.",feedback:"A better template can help with future messages. It leaves the current wrong date in circulation. Correct that detail, then retain a check that fits the next update."}],bestOptionId:"correct-and-check"}},carry:{takeaway:"A fair response keeps responsibility specific and turns it into an act.",identityExample:"For your reported act: “I corrected the detail” or “I asked for support.”",followUp:{questionId:"repair-or-support-result",question:"What did your repair or support step change, and what still needs attention?",observationPrompt:"What act and response did you record?",adjustmentPrompt:"Keep the prevention cue, change it, or seek support?"}},goDeeper:{sourceIds:["CF08","CF07","CF13"],sections:[{heading:"Kindness and accountability can coexist",paragraphs:["Breines and Chen tested compassionate writing in four undergraduate experiments. In the wrongdoing experiment, 91 students were analyzed. They recalled a recent wrong they still felt guilt about, then wrote to themselves with kindness and understanding. The study measured increased motivation to make amends and avoid repeating the wrong. That was a motivation measure, not proof that participants completed repairs or became more reliable over time. [CF08]","ODA adds a practical choice: identify your responsibility, then correct something, make a repair offer, or request support. That action step and its two-minute size were not the tested protocol. A harsh sentence is not a repair, but neither is a reassuring sentence by itself. If the record shows that someone mistreated you, do not rewrite their conduct as your mistake. Keep the next step safe and voluntary, and record only what you actually do. [CF08, CF13]"]},{heading:"A short supportive sentence is not a full program",paragraphs:["Han and Kim’s review included 56 randomized trials of self-compassion interventions. It found small to medium immediate average effects on distress measures. Overall trial bias risk was high, and fewer studies used active comparisons or online delivery. The review was not preregistered. These were varied interventions, not a test of ODA’s single fair sentence, factual correction, or saved return. Do not borrow their average symptom effects as a promise about this lesson. [CF07]","You may feel embarrassed after doing the correct repair. You may receive no reply, or find that another step is needed. Those are observations for your return, rather than evidence that kindness failed. NIMH advises professional help when social fear disrupts daily life. Support is also available sooner if you want it. This course helps choose an ordinary act within its scope; it does not assess or treat persistent anxiety. [CF13]"]}]}},{schemaVersion:2,revision:2,id:"confidence-5",courseId:"confidence",locale:"en",title:"When hesitation returns, use what actually worked",goal:"Use your speaking records to keep one workable move and schedule its next opportunity this week.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"The course closes. Which opening will your sentence have this week?",reason:{id:"reason-to-continue-speaking",label:"Does this speaking experiment still serve the life you want?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep contributing at work","Ask for what I need","Protect time for a better opening"]},why:{id:"why-continue-speaking",label:"What makes this experiment worth continuing or changing?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Use your sentence and records instead of starting another routine. What was actually tried? Did the opening occur? Was information missing, or did the setting need changing? Keep the useful part and revise one condition. An absent record is unknown, not proof of failure.","Link the same sentence to an available cue: “At Saturday’s handover, I will use my question.” Such plans have helped goal pursuit across varied studies; this course’s combined routine is untested. Choose the next suitable opportunity this week, then review it. Repeat, seek support, rest, or stop if the experiment no longer fits."],example:{title:"Rosa changes the opening",text:"Rosa’s records show that her ready question went unused twice because the volunteer briefing ended early. On Saturday, she asks it during the safe handover at the returns desk instead. The answer is brief and leaves one detail unresolved. She records the exchange and keeps that opening for her next shift, with no larger speaking challenge added."}},move:{invitation:"Keep one useful sentence. Give it an opening your records support.",instructions:["Keep the saved act. Use a recorded opening, or edit one failed condition.","Date its next opening this week; name when and where the backup will happen."],prompts:[{id:"retained-speaking-condition",label:"What will you keep, and which condition needs changing?",help:"Keep the action; edit the cue or route from your actual record.",kind:"text",maxLength:160,optional:!0,visible:!0}],suggestions:{action:["Ask: Which shift uses the shorter checklist?","Repeat my saved useful request","Share my saved revised idea"],minimum:["Use one prepared sentence","Send one useful sentence"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"In three days",daysFromToday:3}],cue:["At Saturday's 10 a.m. shift handover","At today's 3 p.m. team check-in"],place:["At our returns desk","In our trusted team message thread"],minutes:[2,1,5],fallback:["Message the shift lead after the handover","Ask for support or pause"],observation:["Whether the cue and sentence happened","The reply and one next adjustment"]},suggested:{action:"Ask: Which shift uses the shorter checklist?",minimum:"Use one prepared sentence",minutes:2,cueHint:"At Saturday's 10 a.m. shift handover",placeHint:"At our returns desk",obstacleHint:"The shift handover is canceled",fallbackHint:"Message the shift lead after the handover",observationHint:"Whether the cue and sentence happened"},stopRule:"Keep real protections. Pause or get support for danger, overwhelming distress, or daily-life interference.",accessibleAlternative:"Use a safe written or assisted route. Rest and support can be chosen next acts."},result:{question:"Did you use your retained sentence at this opening?",observationPrompt:"Did the opening occur, what did you do, and what response followed?"},judgment:{primary:{id:"no-question-period-adjustment",scenario:"Rosa’s question is ready. Two briefings ended without questions. A safe handover and a trusted message channel are available this week.",question:"Which revision addresses her records?",options:[{id:"more-script-practice",text:"Keep the briefing plan and rehearse her question again before the next scheduled session.",feedback:"Rehearsal helps when wording or knowledge is missing. Rosa’s records identify an unavailable opening. More script practice leaves that condition unchanged; choose an available route instead."},{id:"available-route-cue",text:"Use the same question at the safe handover and keep the message channel as backup.",feedback:"This keeps the chosen behavior and changes the condition that blocked it. Rosa can date the opening, record the reply, and review whether the new cue occurred."},{id:"longer-team-update",text:"Prepare a longer team update so there is a dedicated slot for her contribution next month.",feedback:"A dedicated slot could be useful later. It adds preparation and postpones this ready question despite available routes this week. Try the handover, then assess any need for a larger format."}],bestOptionId:"available-route-cue"}},carry:{takeaway:"Keep what your records support. Give the same useful act its next workable opening.",identityExample:"If you used the retained sentence: “I used the opening I chose.”",followUp:{questionId:"retained-opening-result",question:"Did your revised opening solve the problem shown in earlier records?",observationPrompt:"What does this attempt add to the earlier record?",adjustmentPrompt:"Repeat, revise one condition, seek support, rest, or stop?"}},goDeeper:{sourceIds:["CF05","CF04","CF13"],sections:[{heading:"A cue is a situation you can recognize",paragraphs:["An implementation intention connects a critical situation with a goal-directed response: if that situation occurs, then do this behavior. Gollwitzer and Sheeran’s synthesis included 94 independent tests and 8,461 participants, mainly students alongside other samples. The broad average favored these plans, but tasks and methods varied. It is not an effect estimate for this confidence course or proof that a countdown works. The cue, chosen goal, and feasible response still matter. [CF05]","Use the records to decide which part needs changing. If the opening never occurred, find another available opening. If information was missing, prepare that information before the next attempt. If contact was unsafe, protect yourself and seek support. Keep a behavior that still serves your direction rather than escalating because the course is ending. The integrated name, shrink, try, record, and review routine is an ODA adaptation, not a tested clinical program. [CF04, CF05, CF13]"]},{heading:"Consolidation uses records rather than a confidence verdict",paragraphs:["The progress-monitoring review found average goal benefits across many randomized studies. It did not validate this particular receipt, next-day return, or weekly schedule. ODA uses those features to bring back the commitment and the factual record together. A quiz response or future plan is not evidence of speaking. A real sentence with an unanswered question can be a completed act with an unresolved external result. Keep those distinctions in your next review. [CF04]","Choose one next opportunity within your real week. The return can lead to repeating, shrinking, changing the cue, seeking support, resting, pausing, or stopping. None requires you to feel permanently confident. NIMH’s guidance places daily-life impairment within professional assessment and support, rather than a course-completion target. Help is available without first collecting repeated failed attempts. Continue the experiment only while it is safe, feasible, and useful for the life you want. [CF13]"]}]}}],T=[{id:"mcii",title:"Wang, Wang & Gai · 2021 · Mental contrasting with implementation intentions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"CF06: 21 articles, 24 independent effects, 15,907 participants. Mental contrasting plus if–then planning showed a small to medium average goal benefit (g = 0.336).",limitation:"Possible publication bias; sensitivity estimate g = 0.242. Goals and populations varied. This is not a confidence or ODA course effect."},{id:"self-compassion",title:"Han & Kim · 2023 · Self-compassion interventions",url:"https://pubmed.ncbi.nlm.nih.gov/37362192/",type:"research",finding:"CF07: Across 56 randomized trials, varied self-compassion interventions showed small to medium immediate average effects on distress.",limitation:"High overall bias risk; fewer active or online comparisons. Not preregistered. One supportive sentence and this course were not tested."},{id:"monitoring",title:"Harkin et al. · 2016 · Monitoring goal progress",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"CF04: Increasing progress monitoring improved goal attainment on average across 138 randomized studies, involving 19,951 people (d = 0.40).",limitation:"Goals and methods varied. This exact receipt and return were not tested. Moderator findings do not require public sharing."},{id:"CF02",title:"Sitzmann & Yeo · 2013 · Past performance and self-efficacy",url:"https://doi.org/10.1111/peps.12035",type:"research",finding:"The within-person meta-analysis found a stronger association from past performance to later task confidence than the reverse after controlling linear trends. The 38-study, 5,414-person count belongs to a separate between-person analysis.",limitation:"Mostly student studies; temporal correlations do not settle causality, make confidence useless, or prove tiny acts change global self-belief."},{id:"CF04",title:"Harkin et al. · 2016 · Monitoring goal progress",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"Increasing progress monitoring improved goal attainment on average across 138 randomized studies and 19,951 people (d = 0.40).",limitation:"Varied goals and methods. ODA’s exact record and return were not tested; public sharing is not required by moderator findings."},{id:"CF05",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"A synthesis of 94 independent tests and 8,461 participants found average goal benefits for plans linking a critical situation to a goal-directed response.",limitation:"Heterogeneous methods and samples, mainly students; experimental and correlational designs. No confidence-course or branded countdown effect follows from this estimate."},{id:"CF07",title:"Han & Kim · 2023 · Self-compassion interventions",url:"https://pubmed.ncbi.nlm.nih.gov/37362192/",type:"research",finding:"Across 56 randomized trials, varied self-compassion interventions showed small to medium immediate average effects on distress measures.",limitation:"High overall bias risk, fewer active or online comparisons, and no preregistration. This brief ODA exercise is not the tested intervention."},{id:"CF08",title:"Breines & Chen · 2012 · Self-compassion and improvement motivation",url:"https://self-compassion.org/wp-content/uploads/publications/selfimp.motivation.pdf",type:"research",finding:"In a randomized undergraduate wrongdoing experiment, compassionate writing increased reported motivation to make amends and avoid repeating the wrong; 91 students were analyzed.",limitation:"Reported motivation was not completed repair or lasting competence. Independent direct replication of this exact protocol was not verified in the dossier."},{id:"CF11",title:"Craske et al. · 2014 · Learning-focused exposure review",url:"https://doi.org/10.1016/j.brat.2014.04.006",type:"research",finding:"The clinical review emphasizes comparing a specific feared prediction with what happened, without making immediate fear reduction necessary for learning.",limitation:"Narrative review, not a pooled trial. It does not validate ODA’s brief exercise, universal technique superiority, unguided trauma exposure, or removing real safeguards."},{id:"CF12",title:"NHS · Facing your fears",url:"https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/facing-your-fears/",type:"guidance",finding:"Public guidance describes listing, rating, and ranking feared situations and practicing manageable ones without rushing.",limitation:"Guidance, not a trial. Its fear-halving progression rule differs from learning-focused models; ODA’s old numeric rung cutoffs were not validated."},{id:"CF13",title:"NIMH · Social anxiety disorder: what you need to know",url:"https://www.nimh.nih.gov/health/publications/social-anxiety-disorder-more-than-just-shyness",type:"guidance",finding:"Professional help is appropriate when social fear interferes with daily activities. A provider assesses symptoms and possible causes.",limitation:"Public clinical guidance, not an experiment. Do not diagnose from a lesson, delay help for a duration threshold, or substitute ODA for treatment."}],g={schemaVersion:2,revision:4,id:"confidence-1",courseId:"confidence",locale:"en",title:"Name the fear, not yourself",goal:"Describe one difficult situation fairly, then use one safe sentence that serves your life.",minutes:{learning:6,rehearsal:1,suggestedAction:2,review:2},direction:{hook:"What have you left unsaid this week? Pick one safe opening worth using.",reason:{id:"reason-to-speak",label:"What matters here, or what does staying quiet cost?",kind:"text",maxLength:160,optional:!0,suggestions:["Let my ideas be heard","Stop leaving useful points unsaid","Ask for what I need"]},why:{id:"why-speaking",label:"Why does speaking up matter in the life you want?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"cost-of-silence",label:"If you stayed quiet, what did it cost you?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["“I'm bad at speaking up” judges your whole self. “I get tense when I share an idea” names one situation. You can practice a next move there. You cannot practice a verdict about yourself.","Don't wait to sound confident. Name what's happening, then choose one useful sentence. Rewriting the thought is preparation. Using your sentence is the next real step. The response may disappoint you. Record it anyway.","Choose a safe opening. If speaking could put you at risk, protect yourself or ask for support. This is a move you choose, not a test of your worth."],example:{title:"Ana's suggestion",text:"Ana has stayed quiet twice this week. She wants her ideas heard, so she prepares one question for a safe check-in: “Could we test the shorter checklist for one shift?” She asks while nervous. Her supervisor says they can discuss it Monday. Ana records what she asked and the reply. Her idea is still undecided."}},move:{invitation:"Choose a sentence worth using. Keep it small enough for your next safe opening.",instructions:["Edit Action to your actual sentence; choose its real cue and place.","Use it safely. Rehearsal is preparation; keep private details off ODA if preferred."],prompts:[{id:"actual-sentence-and-opening",label:"What will you say, and at which actual opening?",help:"Edit the sentence in Action, or choose Keep my plan private.",kind:"text",maxLength:160,optional:!0,visible:!0}],suggestions:{action:["Ask: Could we test the shorter checklist?","Say: I suggest checking this step first.","Ask: Could you clarify the deadline?"],minimum:["Ask the shorter-checklist question","Use my chosen sentence","Send my chosen sentence"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],cue:["At today's 3 p.m. team check-in","At lunch with my trusted colleague"],place:["In our team room","In our trusted team message thread"],minutes:[2,1,5],fallback:["Read the sentence from my note","Send it in team chat after check-in","Ask someone I trust for support"],observation:["Whether I used my sentence","The reply, including no reply","What helped or got in the way"]},suggested:{action:"Ask: Could we test the shorter checklist?",minimum:"Ask the shorter-checklist question",minutes:2,cueHint:"At today's 3 p.m. team check-in",placeHint:"In our team room",obstacleHint:"I hesitate while the opening is available",fallbackHint:"Read the sentence from my note",observationHint:"Whether I used the sentence and what response I received"},stopRule:"If speaking could put you at risk, pause and choose protection or support.",accessibleAlternative:"Use your usual communication method, a safe written message, or a request for support."},result:{question:"Did you use your sentence?",observationPrompt:"What did you do, and what response did you actually get?"},judgment:{primary:{id:"prepared-safe-opening",scenario:"Ana has two points ready for a safe team discussion. The supervisor invites suggestions. Ana feels tense and thinks, “I'm bad at this.”",question:"Which next move best uses this lesson?",options:[{id:"extra-review",text:"Ask a colleague to review both points before deciding whether to contribute in the discussion.",feedback:"A review can help when information is missing. Ana already has her points ready and a safe opening. Another review delays the attempt. Name the situation and use one sentence now."},{id:"use-one-sentence",text:"Name this specific moment, then use one prepared sentence while the opening is available.",feedback:"This fits the moment. Ana has a safe opening and a prepared sentence. She can describe her tension fairly and still contribute. The useful test is what she does, not whether she feels confident."},{id:"wait-for-ease",text:"Rehearse both points once more and wait until the tension eases before choosing an opening.",feedback:"Rehearsal helps prepare a sentence. Ana has already prepared, and waiting for tension to ease could lose this opening. She can use one sentence while tense, then record what actually happens."}],bestOptionId:"use-one-sentence"}},carry:{takeaway:"A fair description gives you a next move. A label closes the door too soon.",identityExample:"If you used your sentence: “I spoke while nervous.”",followUp:{questionId:"opening-result",question:"What happened when the opening appeared?",observationPrompt:"What did you actually notice?",adjustmentPrompt:"What will make the next try fit your life?"}},goDeeper:{sections:[{heading:"A description you can work with",paragraphs:["A label such as “I'm bad at this” covers too much to guide the next move. A description names the situation, the feeling, and a possible action. That does not prove the label false, promise success, or remove a skill gap. It gives you a smaller question to answer through practice.","You may need more than a sentence. If you do not know the material, preparation matters. If the setting is unsafe, protection matters. If you are repeatedly overwhelmed, support matters. The quiz describes a prepared person with a safe opening. It does not say that speaking immediately is always the best choice.","This lesson's fair sentence is an ODA teaching exercise. Research on longer self-compassion programs does not establish that this single exercise treats anxiety or changes confidence. Use it as a practical way to choose your next move, and judge that move by what you observe. [CF07]"]},{heading:"What the research can support",paragraphs:["Han and Kim's 2023 review combined 56 randomized trials of self-compassion interventions. It found small to medium average effects on distress measures immediately after the interventions. The overall risk of bias was high. Evidence against active comparisons and for online delivery was more limited. This does not establish an effect for ODA's one-sentence exercise. [CF07]","Harkin and colleagues' 2016 review combined 138 randomized studies of progress monitoring. Monitoring interventions improved goal attainment on average across the studies. Goals and recording methods varied. ODA's particular receipt and next-day flow were not tested by that review. Here, the record is a way to compare a plan with an actual attempt, without requiring public sharing. [CF04]","You can report an unchanged feeling, an unanswered question, or a decision to pause. These are different observations. None warrants a verdict on your whole self. Your next choice should respond to the facts, your circumstances, and the life you want."]}],sourceIds:["CF07","CF04"]}};function u(e,t,a){const n=e.judgment.primary.options.find(i=>i.id===e.judgment.primary.bestOptionId),f=e.judgment.primary.options.filter(i=>i!==n).map(i=>i.text);return f.splice(t,0,n.text),{id:e.id,schemaVersion:2,v2:e,title:e.title,goal:e.goal,minutes:e.minutes.learning,reading:[e.idea.paragraphs[0],e.idea.paragraphs.slice(1).join(" ")],practice:[e.move.instructions[0],e.move.instructions.slice(1).join(" ")||"Use your chosen action at its safe opening.","Return here and record what actually happened."],reflection:e.direction.reason.label,question:e.judgment.primary.question,options:f,correct:t,feedback:n.feedback,takeaway:e.carry.takeaway,sources:[...e.goDeeper.sourceIds],deeper:e.goDeeper.sections,example:e.idea.example,photo:a}}const q={id:"confidence",title:"Your voice shakes. Your idea can still be heard.",subtitle:"Five lessons. Use one safe sentence, learn from the reply, and give it a next opening.",description:"Carry one chosen speaking experiment through a manageable opening, an honest record, a repair when needed, and next week’s plan.",scope:"Everyday courage and self-compassion practice. It is not exposure therapy for dangerous situations, trauma or intense anxiety; for those, please work with a trained professional.",outcome:"A speaking experiment, a factual record, and a next opening that fits your week.",photo:{id:"1756244834590-b1a32e94df40",alt:"Woman looking out over a mountain lake at sunrise"},lessons:[u(g,1,{id:"1579017308347-e53e0d2fc5e9",alt:"Person writing by hand in an open notebook"}),u(m[0],2,{id:"1635895752485-99ba511c07e1",alt:"Stepping stones across water at sunset"}),u(m[1],1,{id:"1572020487535-31e268b25e21",alt:"Man taking notes in a notebook"}),u(m[2],0,{id:"1573497491208-6b1acb260507",alt:"Two women sitting at a table talking"}),u(m[3],1,{id:"1748609422318-7301636fb625",alt:"Hand writing a plan in a notebook with checkboxes"})]},K=Object.freeze(Object.defineProperty({__proto__:null,CONFIDENCE_1_V2:g,COURSE:q,SOURCES:T},Symbol.toStringTag,{value:"Module"})),S=[{id:"S03",title:"Safren et al. · 2010 · Therapist-delivered CBT for adult ADHD",url:"https://jamanetwork.com/journals/jama/fullarticle/186469",type:"research",finding:"In 86 adults with residual ADHD symptoms despite medication, 12 individual CBT sessions outperformed relaxation with educational support. At least 30% symptom reduction occurred in 67% versus 33%.",limitation:"Whole therapist-delivered package, not isolated tools or ODA. Some comorbid conditions were excluded. The primary maintenance analysis selected CBT responders; 12 months was measured from baseline, approximately nine months after treatment."},{id:"S06",title:"NIMH · 2024 · ADHD in adults",url:"https://www.nimh.nih.gov/health/publications/adhd-what-you-need-to-know",type:"guidance",finding:"Adult assessment considers childhood history, persistent impairment across settings, and alternative explanations. Medication and psychotherapy are common treatments; coaching and workplace accommodations may also be considered.",limitation:"Public US guidance, not a tool trial. Services and accommodation rights vary. A quiz cannot diagnose ADHD. Support can begin now; medication changes belong with a prescriber."},{id:"S09",title:"Sprich et al. · Description and demonstration of CBT for adult ADHD",url:"https://ica.org.il/wp-content/uploads/2024/06/Description-and-Demonstration-of-CBT-for-ADHD-in-Adults-1.pdf",type:"guidance",finding:"Describes calendar and task-list review, manageable task steps, written distraction delay with later review, and realistic responses to negative or overly optimistic thoughts within a clinical program.",limitation:"Developer protocol description, not a component trial. The opened manuscript labels 2012 while journal references cite 2010; the date discrepancy remains unresolved. The revised 2017 workbook procedures were not independently verified."},{id:"S10",title:"Barkley · 2011 document · External support where action happens",url:"https://www.russellbarkley.org/factsheets/ADHD_EF_and_SR.pdf",type:"technique",finding:"A clinical model recommends bringing external information, near-term steps, and feedback to the place and moment where action is needed.",limitation:"Clinician advice covering children and adults, not a trial of each tip. Timing metaphors and the resource-pool account are not established universal biology. Free cues are personal experiments, not treatment."},{id:"S11",title:"Eagle et al. · 2024 · Body doubling survey",url:"https://leyabreanna.com/papers/body_double_taccess.pdf",type:"research",finding:"Of 220 self-selected survey respondents, 193 identified as neurodivergent and 139 identified ADHD. After a definition, 75% reported using body doubling and described help with starting or focusing.",limitation:"Descriptive self-report, not a controlled efficacy study or a 75% success rate. Diagnosed and suspected identities were not separated. A companion can feel stressful; consent, privacy, and stopping matter."},{id:"S12",title:"Harkin et al. · 2016 · Monitoring goal progress",url:"https://eprints.whiterose.ac.uk/91437/8/3_PDFsam_Does%20monitoring%20goal.pdf",type:"research",finding:"Across 138 randomized studies, monitoring interventions improved goal attainment on average, d = .40, 95% CI [.32, .48].",limitation:"Varied goals and methods, largely health domains. Indirect evidence for this ADHD course; no ideal check frequency or three-attempt rule. Reporting moderators do not establish that disclosure causes benefit."},{id:"S13",title:"Albulescu et al. · 2022 · Micro-breaks",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0272460",type:"research",finding:"Across 22 samples, brief breaks improved vigor and reduced fatigue on average. The overall performance estimate, d = .16, 95% CI [−.04, .37], did not show a clear improvement.",limitation:"Employee/student samples, not clinical ADHD research. No optimal work interval or guaranteed output benefit. Few samples had low overall bias risk."},{id:"S14",title:"Metcalfe et al. · 2024 · Time perception and ADHD",url:"https://pubmed.ncbi.nlm.nih.gov/38145491/",type:"research",finding:"A review reported group differences in laboratory time-perception tasks across the lifespan.",limitation:"Opened abstract only. Adult-only magnitude, participant total, and confidence interval were not verified. Laboratory timing is different from everyday task duration; no universal estimate adjustment or timer-treatment effect follows."}],o=[{schemaVersion:2,revision:2,id:"adhd-1",courseId:"adhd",locale:"en",title:"Another forgotten task? Give it a home",goal:"Record one important task and retrieve it at a dependable cue.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Your best plans keep disappearing. Put one commitment where you will actually find it.",reason:{id:"adhd-1-purpose-cost",label:"Which commitment deserves space before another reminder system?",kind:"text",maxLength:160,optional:!0,suggestions:["Protect an important appointment","Stop losing the same task","Make room for my next step"]},why:{id:"adhd-1-why",label:"Which commitment deserves space before another reminder system?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["An external record and a retrieval routine do different jobs. The record holds the commitment. The routine brings it back when you can act. A list you never meet is still a hidden list. Adult ADHD skills programs teach both capture and daily review, rather than asking you to remember harder.","Capture a task that matters this week. Keep timed commitments in their required calendars and other tasks in one reachable list. Capture and reminder placement are setup. Save tomorrow's actual list check as a separate retrieval opportunity with its own date, cue, and place."],example:{title:"Maya's morning check",text:"Maya needs to book an eye exam. She keeps her required work calendar and family calendar, then puts the call on her phone list. At the kitchen counter, she sets a breakfast reminder to check all three. Next morning she finds the call, but the clinic is closed. She records that and chooses lunch."}},move:{invitation:"Give one meaningful task a record and retrieval cue.",instructions:["Capture the task and place its reminder. Record this as setup.","Save a separate retrieval opportunity below; log its actual check separately."],prompts:[],suggestions:{action:["Record the eye-exam call and breakfast reminder","Capture my appointment and set its review reminder"],minimum:["Record the call and place its reminder","Record my timed commitment and reminder"],cue:["After lunch, with my phone available","After checking my required calendars"],place:["At my kitchen counter","At my accessible workspace"],minutes:[2,1,5],fallback:["Use an accessible reminder instead","Ask for help entering the reminder","Move the cue to my starting place"],observation:["Task recorded and reminder placed: setup only","Where my record and reminder now live"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Record the eye-exam call and breakfast reminder",minimum:"Record the call and place its reminder",minutes:2,cueHint:"After lunch, with my phone available",placeHint:"At my kitchen counter",obstacleHint:"My reminder is hidden or inaccessible.",fallbackHint:"Use an accessible reminder instead",observationHint:"Task recorded and reminder placed: setup only",kind:"preparation"},stopRule:"Keep required calendars and essential care or emergency access.",accessibleAlternative:"Dictate, use assistive reminders, or ask for help.",nextOpportunity:{action:"Open my list and identify the recorded task",minimum:"Open the list and identify the recorded task",cue:"After breakfast, before leaving",place:"At my kitchen counter",daysAfter:1,minutes:1,kind:"practice"}},result:{question:"Did you complete the selected setup or retrieval action?",observationPrompt:"Setup: what was placed? Retrieval: what was found, or what blocked the check?"},judgment:{primary:{id:"adhd-1-required-calendars-review",scenario:"Maya must keep work and family calendars. A clinic call sits on a loose note. Breakfast is her dependable review cue.",question:"Which setup best preserves her commitments?",options:[{id:"personal-dashboard",text:"Keep both required calendars and copy their commitments into a personal dashboard she checks after breakfast.",feedback:"A dashboard could fit other constraints, but it adds copying and duplicate upkeep here. Maya already has a dependable review cue. Keep the calendars and bring the loose call into that review."},{id:"separate-lists",text:"Keep a new priority list for each calendar so every area has its own reminders.",feedback:"Separate lists can suit distinct work rules, but they add retrieval points for this call. Maya can keep required calendars while capturing the loose task in one dependable list."},{id:"one-review",text:"Keep both calendars, put the call on one list, and review them together after breakfast.",feedback:"This fits the constraint. Maya keeps required calendars and gives the loose task a home. The next test is whether breakfast actually brings her back to that review."}],bestOptionId:"one-review"}},carry:{takeaway:"A task needs somewhere to live and a cue that brings you back.",followUp:{questionId:"adhd-1-separate-retrieval-return",question:"Did the separate retrieval cue occur, and did you find your recorded task?",observationPrompt:"What task did you find, or was the cue missed or record inaccessible?",adjustmentPrompt:"Keep the cue, move the record, or choose suitable support?"},identityExample:"After actual retrieval: “I found my task at breakfast.”"},goDeeper:{sections:[{heading:"Two jobs, one review routine",paragraphs:["The clinical protocol described by Sprich and colleagues consolidates appointments and deadlines in a calendar system and other tasks in an organized list. Both are reviewed and updated daily, with priorities chosen from the available tasks. These procedures are part of a therapist-delivered program, not a demonstration that one list independently treats ADHD. [S09]","ODA adapts that procedure to systems you must keep. A workplace calendar can remain alongside a family calendar. A combined view or short review order may fit better than moving everything. Today's capture and reminder placement are preparation; they do not prove the reminder worked. Save the next day's actual list check separately, with the recorded task and editable breakfast cue. ODA keeps setup and retrieval as distinct actions and occurrences. Log each only after attempting it. The retrieval record can name the task found, a missed cue, or an inaccessible list. Capturing an appointment does not mean attending it."]},{heading:"Support at the moment of action",paragraphs:["Barkley's clinical model recommends making information available where and when action is needed. A note near the relevant item or an accessible reminder is a candidate support. This is practitioner advice, not proof that reminders improve everyone's working memory or solve every barrier. Test whether the chosen support is reachable and noticeable in your actual setting. [S10]","The Safren trial tested 12 therapist sessions in 86 adults already taking medication. It supports that whole program under those conditions, not the independent efficacy of a breakfast cue or this app. Its primary maintenance analysis followed selected CBT responders; the 12-month point was from baseline. [S03] A record can compensate for one missed reminder while other difficulties remain. Seeking qualified support can proceed alongside everyday experiments. A missed check does not diagnose ADHD or make a judgment about effort."]}],sourceIds:["S09","S10","S03"]}},{schemaVersion:2,revision:2,id:"adhd-2",courseId:"adhd",locale:"en",title:"Stop circling the task. Enter it.",goal:"Do one useful unit of the task you captured.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Reorganizing the folder again? Use the materials you already have for one real task step.",reason:{id:"adhd-2-purpose-cost",label:"Which detour costs time your chosen task needs?",kind:"text",maxLength:160,optional:!0,suggestions:["Finish one useful piece","Stop reorganizing before starting","Use my task record"]},why:{id:"adhd-2-why",label:"Which detour costs time your chosen task needs?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Reuse the task you captured. “Work on it” leaves the first action undecided. “Enter the appointment request” names something you can actually do. Adult ADHD skills programs break overwhelming tasks into manageable steps, but a complete breakdown is not a prerequisite for the first available step.","Choose a verb and an object that produce useful work. Finding a file may be necessary preparation; entering one needed answer is task practice. Use the materials you have. If access is missing, request help. A small start does not promise you will finish everything."],example:{title:"Maya enters the request",text:"Maya finds the clinic's online form after checking her list. She wants to reorganize her health folder first, but the form needs only her contact details. At lunch, she enters those details and saves the request. Available appointment times are still unclear. She records the submitted request and leaves the reply as unknown."}},move:{invitation:"Use your captured task for one useful unit.",instructions:["Keep the task you captured; name its useful unit in Action.","Leave available materials as they are. Complete that unit before reorganizing."],prompts:[],suggestions:{action:["Enter contact details in the clinic request","Write one usable sentence","Send one practical request"],minimum:["Enter the clinic request contact details","Write one sentence that serves the task"],cue:["After lunch when I open my task list","When my needed materials are available"],place:["At my desk with the request form","At my accessible task workspace"],minutes:[2,1,5],fallback:["Leave the folder and complete my needed field","Dictate one useful task unit","Ask for access if it is actually missing"],observation:["The useful output I produced","Whether missing access blocked the step"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Enter contact details in the clinic request",minimum:"Enter the clinic request contact details",minutes:2,cueHint:"After lunch when I open my task list",placeHint:"At my desk with the request form",obstacleHint:"I start organizing around the task.",fallbackHint:"Leave the folder and complete my needed field",observationHint:"The useful output I produced"},stopRule:"Pause for unsafe conditions or urgent care needs.",accessibleAlternative:"Speak, type, use assistance, or request missing access."},result:{question:"Did you do the useful task unit you chose?",observationPrompt:"What useful work happened, and what remains?"},judgment:{primary:{id:"adhd-2-decision",scenario:"A report's figures are ready. Luis has fifteen minutes and keeps renaming files. The draft needs a rough opening sentence.",question:"Which next move enters the actual task?",options:[{id:"rename-files",text:"Rename the source files now so they will be easier to find during drafting.",feedback:"Renaming could help if files were missing. The figures are already available, and drafting is the blocked task. Use one figure in a rough sentence before revisiting organization."},{id:"write-sentence",text:"Write one rough sentence using the first figure, then note the next needed detail.",feedback:"This produces part of the report with materials Luis already has. It does not finish the report. He can record the sentence and identify what the next step needs."},{id:"full-outline",text:"Create the complete section outline first so the draft has a consistent structure.",feedback:"An outline can guide a complex report. Here, Luis has enough information for one opening sentence. A complete outline adds another prerequisite before the useful unit he can already write."}],bestOptionId:"write-sentence"}},carry:{takeaway:"Make the step useful enough to advance the task and clear enough to begin.",followUp:{questionId:"adhd-2-return",question:"Did you enter the task, prepare for it, or encounter missing access?",observationPrompt:"What useful work happened, and what remains?",adjustmentPrompt:"What would make the next attempt fit?"},identityExample:"If you made useful output: “I entered the task before reorganizing.”"},goDeeper:{sections:[{heading:"Small and useful are separate tests",paragraphs:["Task breakdown appears in the clinical adult ADHD protocol. The same program includes defining a problem, considering possible solutions, weighing trade-offs, and implementing a workable solution. Those procedures belong to a treatment package; their separate effects were not established by its trial. [S09] ODA's verb-and-object exercise is a shorter adaptation, not the original treatment dose.","A useful small action creates something the task needs: a completed field, a draft sentence, or a request actually sent. Preparation can also be necessary. If a form is inaccessible, asking for an accessible version is a legitimate support action. If facts are missing, finding them is preparation. Record that act under its actual name and choose the next opportunity for execution. Do not add a three-step planning requirement when one feasible unit is already available."]},{heading:"A clinical model is not a promise",paragraphs:["Barkley recommends near-term steps and quick feedback at the moment of action. His knowing-versus-doing distinction is a clinical explanation, not a claim that every adult with ADHD has the same mechanism. Music, a consenting companion, or an update to someone may be personal experiments; this source does not independently test each example. No purchase, reward, or disclosure is required. [S10]","The therapist-delivered program tested by Safren and colleagues combined organization, distractibility skills, and adaptive thinking over 12 sessions. Its results cannot be assigned to one short start or to ODA. [S03] Your record answers a narrower question: was the named step available, and what did you actually do? If the step stalled, inspect missing information, fatigue, access, or competing responsibilities before deciding how to adapt it. Starting gives an observation, not a guarantee of completion."]}],sourceIds:["S09","S10","S03"]}},{schemaVersion:2,revision:2,id:"adhd-3",courseId:"adhd",locale:"en",title:"Your calendar needs the time tasks actually take",goal:"Compare a task estimate, a chosen work block, and actual output.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Another task outgrew its slot? Measure this task before promising the same time tomorrow.",reason:{id:"adhd-3-purpose-cost",label:"What will you move so this task has room?",kind:"text",maxLength:160,optional:!0,suggestions:["Make a realistic time slot","Protect another commitment","Learn from actual task time"]},why:{id:"adhd-3-why",label:"What will you move so this task has room?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["A work block and a task's completion time are different measurements. A five-minute block can end while the task is unfinished. Record what those minutes produced. If you finish, record the total elapsed time separately. Otherwise the total is still unknown.","Reuse your chosen task. Estimate its total duration, choose a tolerable block, and note the elapsed time and output. ADHD timing studies describe group differences in laboratory tasks; they do not give every adult a correction percentage. Use this observation to reserve a provisional slot for a similar task, then check again."],example:{title:"Maya measures a call",text:"Maya guesses booking the appointment will take five minutes. She chooses a five-minute block at lunch. When it ends, she is still on hold. She chooses to continue and finishes after fourteen minutes. She records the estimate, block, total, and booked appointment. For another clinic call, she reserves more time without treating fourteen as a rule."}},move:{invitation:"Measure one attempt on your continuing task.",instructions:["Keep your task; save an optional total-time estimate before trying.","Choose a block; afterward record elapsed time, useful output, and whether it finished."],prompts:[{id:"adhd-3-time-estimate",label:"What is your estimate for the whole task?",kind:"text",maxLength:160,optional:!0,planField:"prediction"}],suggestions:{action:["Time one useful task unit","Measure one appointment call","Measure one draft paragraph"],minimum:["Work one minute and note output","Time one completed small task"],cue:["After lunch when I start the clinic call","After checking my task record"],place:["At my desk with my phone","Where I make the call"],minutes:[2,1,5],fallback:["Shorten the block and note output","Use an accessible clock instead"],observation:["Estimate, block, elapsed time, and output","Whether the task finished or remains open"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Time one useful task unit",minimum:"Work one minute and note output",minutes:2,cueHint:"After lunch when I start the clinic call",placeHint:"At my desk with my phone",obstacleHint:"The task takes longer than the available slot.",fallbackHint:"Shorten the block and note output",observationHint:"Estimate, block, elapsed time, and output"},stopRule:"Stop, rest, or respond to urgent needs when necessary.",accessibleAlternative:"Use an accessible clock, approximate notes, or assistance."},result:{question:"Did you measure time and record useful output?",observationPrompt:"What were your estimate, block, elapsed time, and output?"},judgment:{primary:{id:"adhd-3-fixed-departure-call",scenario:"Maya's clinic call took fourteen minutes, not five. Tomorrow she has twenty minutes before a fixed departure. The bus offers no privacy for medical details.",question:"Which next plan best uses that observation?",options:[{id:"larger-slot",text:"Reserve a larger provisional slot before departure, record the next call's time, and revise again.",feedback:"This uses one relevant observation without turning it into a universal rule. Maya makes room before her fixed departure and checks whether the next similar call needs that time."},{id:"five-again",text:"Keep the five-minute slot, prepare the questions carefully, and see whether the call gets shorter.",feedback:"Preparation may shorten her part of the call, but it cannot control hold time. With a fixed departure, the previous observation argues for more room or a different opportunity."},{id:"continue-on-bus",text:"Keep five minutes before departure, then continue the call on the bus using headphones if needed.",feedback:"Continuing elsewhere can fit some calls. Here headphones do not create privacy for medical details, and departure is fixed. Use the available larger slot before leaving, then record what happens."}],bestOptionId:"larger-slot"}},carry:{takeaway:"A block measures the work you observed. Completion time stays unknown until the task finishes.",followUp:{questionId:"adhd-3-return",question:"Did the block end, did the task finish, and what did the time produce?",observationPrompt:"What were your estimate, block, elapsed time, and output?",adjustmentPrompt:"What would make the next attempt fit?"},identityExample:"If you observed the task: “I recorded time and output without guessing completion.”"},goDeeper:{sections:[{heading:"Keep four measurements separate",paragraphs:["An estimate predicts the whole task. A chosen block sets how long you intend to work before checking. Actual elapsed time describes the attempt you observed. Completion and output show whether that attempt finished the task and what it produced. ODA separates these measures as a practical learning design; it is not a validated timing treatment. General progress-monitoring research supports checking goal progress, but it does not establish this exact record. [S12]","If a block ends with unfinished work, write that rather than reporting the block as total task duration. A break, a shorter next block, or stopping may fit your circumstances. If a similar task needs more time, reserve a larger provisional slot and decide what moves or gets declined. Two unlike observations cannot establish a standard one-third margin. Even repeated similar tasks may differ when access, care responsibilities, or waiting time change."]},{heading:"What timing and break studies support",paragraphs:["A time-perception review found group differences between ADHD and comparison samples across the lifespan. It studied laboratory timing tasks. The opened abstract does not establish an adult-only effect, an everyday task-duration adjustment, or that a countdown corrects those differences. No universal ideal work-block length follows. [S14]","A separate review of brief breaks found average improvements in vigor and fatigue, with no clear overall performance benefit. Its employee and student samples were not an ADHD clinical sample. [S13] A break can therefore be considered without promising more output. Here a clock or timer is optional support for observing your own task. Keep essential phone, assistive, and emergency access. Notice whether the tool is useful or distracting, and change one support at a time. An observation about task time cannot diagnose ADHD or judge your character."]}],sourceIds:["S12","S14","S13"]}},{schemaVersion:2,revision:2,id:"adhd-4",courseId:"adhd",locale:"en",title:"One errand need not steal your whole task",goal:"Park a non-urgent thought, return once, and review the note.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Remembered an errand mid-task? Keep the thought without abandoning your chosen work.",reason:{id:"adhd-4-purpose-cost",label:"Which interruption can wait, and which needs you now?",kind:"text",maxLength:160,optional:!0,suggestions:["Protect my chosen task","Keep a thought without switching","Respond to real urgency"]},why:{id:"adhd-4-why",label:"Which interruption can wait, and which needs you now?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["A “Later” note needs a closing loop. In an adult ADHD skills protocol, distracting thoughts are written down during a work unit and reviewed when it ends. Capturing a thought without that review leaves another list to lose. This is a package-derived skill, not a proven standalone app treatment.","Keep your current task and leave a return marker. If a non-urgent thought arrives, note it briefly and do one next task movement. At block end, review the note and move any real commitment into your original system. Urgent care, dependent needs, and safety take priority."],example:{title:"Maya returns to the form",text:"Maya is updating her appointment form when she remembers a birthday card. No one needs help now. She writes “card Friday,” marks the field, and enters one answer. When her block ends, she moves the card to her original task list. The form is unfinished, but she knows where to resume and where the errand lives."}},move:{invitation:"Keep your task and leave a route back.",instructions:["Keep your task and block; add its actual end cue to observation.","Park non-urgent thoughts, return once, then review and merge at that endpoint."],prompts:[{id:"adhd-4-block-end-review",label:"At which exact cue will your block end and the note review start?",help:"Edit the observation to save that endpoint with this attempt.",kind:"text",maxLength:160,optional:!0,visible:!0}],suggestions:{action:["Park, return, and review one non-urgent thought","Review parked notes after my task block"],minimum:["Park, return once, and review the note","Review one parked commitment"],cue:["When distracted during my 12:30 invoice block","When distracted during my existing work block"],place:["At my desk beside the invoice","At my accessible task workspace"],minutes:[2,1,5],fallback:["Note the thought, mark my place, return once","Use a speech note and task marker"],observation:["At 12:35, review and merge noted commitments","Return, review at block end, and merge commitments"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Park, return, and review one non-urgent thought",minimum:"Park, return once, and review the note",minutes:2,cueHint:"When distracted during my 12:30 invoice block",placeHint:"At my desk beside the invoice",obstacleHint:"A thought pulls me toward another task.",fallbackHint:"Note the thought, mark my place, return once",observationHint:"At 12:35, review and merge noted commitments"},stopRule:"Urgent care, dependent needs, safety, and essential contact come first.",accessibleAlternative:"Use speech notes, assistive markers, or assistance."},result:{question:"Did you park, return, and review, if a distraction occurred?",observationPrompt:"What happened, and where did the parked commitment go?"},judgment:{primary:{id:"adhd-4-decision",scenario:"During an invoice, Jordan remembers a gift for next week. A dependent is safely supervised. The invoice has a clear next field.",question:"Which response protects both commitments?",options:[{id:"buy-gift",text:"Buy the gift now to remove it from your mind before continuing the invoice.",feedback:"Buying now could prevent forgetting, but it interrupts the selected invoice without urgency. A brief note preserves the gift, then a return marker helps Jordan continue the available field."},{id:"park-return-review",text:"Note the gift, mark the invoice field, enter it, then review the note at block end.",feedback:"This preserves the thought and a route back. Reviewing at block end closes the loop; any actionable gift reminder then moves into Jordan's original task system."},{id:"shopping-plan",text:"Write a detailed gift-shopping plan now, then return to the invoice with that problem settled.",feedback:"Detailed planning also captures the gift, but becomes another task inside this block. Keep the note short now, return to the invoice, and decide next steps at the scheduled review."}],bestOptionId:"park-return-review"}},carry:{takeaway:"Capture the thought, leave a way back, then close the note loop.",followUp:{questionId:"adhd-4-saved-endpoint-return",question:"Did you return and review at your saved endpoint, or appropriately switch for urgency?",observationPrompt:"Where did the note go? No distraction is a valid no-occasion result.",adjustmentPrompt:"What would make the next attempt fit?"},identityExample:"If you returned and reviewed: “I closed the note loop.”"},goDeeper:{sections:[{heading:"The note is temporary",paragraphs:["The clinical distraction-delay procedure begins by observing attention on a less appealing task, choosing fitting work units, recording distracting thoughts, and dealing with those notes systematically at the end. It was described within a therapist-delivered ADHD program. The standalone effect of a note or return marker has not been established here. [S09]","ODA adds an explicit urgency check and an accessible marker showing the next task movement. A screen bookmark, spoken reminder, or marked line can serve that purpose. Review is part of the act, not an optional extra hidden behind the lesson. Move a genuine appointment into the required calendar and another task into the original list; discard a thought that needs no action. If no distraction arrives, do not manufacture one. Record no occasion for the conditional return move, or accurately name the uninterrupted task work you actually performed."]},{heading:"Companions are optional experiments",paragraphs:["A 2024 survey asked 220 self-selected respondents about body doubling, meaning working with another person present. After a definition, 75% reported using it. Of the respondents, 193 identified as neurodivergent and 139 identified ADHD; diagnosed and suspected identities were not distinguished. These reports describe use and perceived help, not a 75% treatment success rate. [S11]","If you want to test a free companion arrangement, ask a consenting person for a short, private block. No disclosure of task details is required. Their presence may help, distract, or add pressure; stop or adapt if it does not fit. Keep the task, cue, and other supports stable while testing that one change. The original therapist package provides broader evidence, but it cannot validate this companion experiment or an ideal duration. [S03] Essential contact and urgent needs remain available throughout."]}],sourceIds:["S09","S11","S03"]}},{schemaVersion:2,revision:2,id:"adhd-5",courseId:"adhd",locale:"en",title:"Missed the cue? Fix that part.",goal:"Keep your task, revise one observed support, and date its next opportunity in your actual week.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Missed a hidden reminder this morning? Change its location before making a verdict about yourself.",reason:{id:"adhd-5-purpose-cost",label:"What real constraint must next week's plan respect?",kind:"text",maxLength:160,optional:!0,suggestions:["Fit my actual mornings","Keep the support that helped","Seek help alongside the experiment"]},why:{id:"adhd-5-why",label:"What real constraint must next week's plan respect?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Review the same task experiment before adding another tool. Did the cue happen? Was the record reachable? Did you begin? What useful output appeared? A missing log leaves the outcome unknown. One observed failure point gives you a specific place to adapt.","Adult ADHD skills programs address both harsh predictions and unrealistic plans. Use your own records to keep what helped and change one constraint for the next opportunity. Consolidate capture, useful steps, time observations, and note review only where needed. Professional support can begin now alongside these tools; medication decisions belong with your prescriber."],example:{title:"Maya keeps what helped",text:"Maya's records show she completed the appointment request at lunch, but missed the breakfast cue when leaving early. She keeps the same phone list and moves its reminder to her departure check. She uses it once and records the task retrieved. Bills still cause significant trouble, so she contacts her clinician without waiting for more failed trials."}},move:{invitation:"Keep what helped. Date one real opportunity; change one observed barrier.",instructions:["Keep your saved task and support. Edit one recorded barrier, or choose support.","Set When to the next actual date; ODA books only its next-day review."],prompts:[{id:"adhd-5-dated-opportunity",label:"What is your next actual opportunity next week, and which support changes?",help:"Edit When, cue, and place. A weekly cadence is not saved automatically.",kind:"text",maxLength:160,optional:!0,visible:!0}],suggestions:{action:["Open my phone task list before departure","Repeat my recorded task with its useful support","Request ADHD assessment from my usual clinic"],minimum:["Open my list and identify the recorded task","Complete my selected useful task unit","Send the appointment request"],cue:["After checking my keys before departure","After lunch when my usual clinic opens"],place:["At my front door with my phone","At my accessible phone or computer"],minutes:[2,1,5],fallback:["Put the task reminder beside my keys","Check free local health-information or support options"],observation:["Cue reached, task retrieved, and useful output","The request sent and any reply"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"Next week",daysFromToday:7}],bundles:[{action:"Open my phone task list before departure",minimum:"Open my list and identify the recorded task",cue:"After checking my keys before departure",place:"At my front door with my phone",fallback:"Put the task reminder beside my keys",observation:"Cue reached, task retrieved, and useful output",minutes:2,kind:"practice"},{action:"Request ADHD assessment from my usual clinic",minimum:"Send the appointment request",cue:"After lunch when my usual clinic opens",place:"At my accessible phone or computer",fallback:"Check free local health-information or support options",observation:"The request sent and any reply",minutes:2,kind:"support"}]},suggested:{action:"Open my phone task list before departure",minimum:"Open my list and identify the recorded task",minutes:2,cueHint:"After checking my keys before departure",placeHint:"At my front door with my phone",obstacleHint:"The cue does not fit my actual day.",fallbackHint:"Put the task reminder beside my keys",observationHint:"Cue reached, task retrieved, and useful output"},stopRule:"Seek qualified support now if difficulties impair life. Discuss medication changes with your prescriber.",accessibleAlternative:"Choose a reachable clinic or free local support option; edit the service and route."},result:{question:"Did you use the retained support or send your chosen support request?",observationPrompt:"What task, changed support, or request happened, and what remains unknown?"},judgment:{primary:{id:"adhd-5-decision",scenario:"Hannah's list remained on her office desk. Her missed task needed to happen before leaving home. She wants an interpretable next test.",question:"Which revision addresses the observed barrier?",options:[{id:"more-alarms",text:"Add several alarms during the day while leaving the list on the office desk.",feedback:"Alarms can help some transitions, but Hannah's record identifies a location mismatch. More reminders elsewhere will not necessarily make the task available before leaving home."},{id:"new-app",text:"Move all tasks into a new app with extra categories, alerts, and a daily review dashboard.",feedback:"A new app might be useful later, but changes many supports at once. Hannah first needs the task accessible before departure; a targeted location change gives a clearer observation."},{id:"move-cue",text:"Move the task cue beside her departure items, keep other supports, and record the next opportunity.",feedback:"This addresses the observed mismatch while keeping the test simple. Hannah can check whether she meets the cue and begins. She can also seek support now if wider impairment persists."}],bestOptionId:"move-cue"}},carry:{takeaway:"Keep what your records support. Change one constraint and ask for help when needed.",followUp:{questionId:"adhd-5-retained-task-or-support-return",question:"Did your retained support make the task reachable, or did you send the support request?",observationPrompt:"What support was used or requested, and what happened?",adjustmentPrompt:"Repeat, revise one condition, get support, or pause?"},identityExample:"If you used the reminder: “I used it at my departure check.”"},goDeeper:{sections:[{heading:"Finish with a plan you can inspect",paragraphs:["The clinical program's adaptive-thinking module addresses both negative predictions and unrealistically optimistic expectations. A realistic response should fit available evidence. “The reminder was in another location” offers a different next test from “I can never use reminders.” It does not prove that thoughts caused every difficulty or that changing a thought removes impairment. [S09]","ODA's consolidation asks you to inspect dated attempts, keep useful parts, and change one support variable. There is no special evidence-based threshold of three attempts. General monitoring research found an average benefit for goal attainment across varied goals, but it did not test this course or its next-day flow. [S12] Date the next actual opportunity, including a next-week date if that fits. ODA saves that occurrence and its next-day return, not a weekly cadence. Choose any further opportunity deliberately at review. A record without a task outcome stays unknown; a completed useful unit stays narrow evidence of that unit. Recovery, support, and a deliberate pause can remain valid next choices."]},{heading:"Everyday skills and professional care can run together",paragraphs:["NIMH guidance describes assessment as considering persistent impairment across settings, childhood history, and possible alternative explanations. An appointment can begin with recent concrete examples, when and where difficulties occur, and questions about support. A perfect childhood record is not a prerequisite for asking for assessment. A timer result or a lesson quiz cannot establish a diagnosis. [S06]","Medication and psychotherapy are common adult treatments. Some people consider coaching or workplace accommodations, with different evidence and locally varying services or rights. ODA is everyday skills training and has not been tested as ADHD treatment. You do not need to complete the course, wait for three failures, or explain private medical details here before seeking help. Bring your practical records if you choose, without treating them as a clinical test. Discuss starting, stopping, dosage, or side-effect concerns with the prescribing professional."]}],sourceIds:["S09","S12","S06"]}}];function h(e,t,a){return{id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,practice:[e.move.instructions[0],e.move.instructions[1],"Record what actually happened and review this same experiment tomorrow."],reflection:e.direction.reason.label,question:e.judgment.primary.question,options:e.judgment.primary.options.map(n=>n.text),correct:t,feedback:e.judgment.primary.options[t].feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds,photo:a}}const I={id:"adhd",title:"Your plans keep disappearing? Build a system you can find",subtitle:"5 lessons. Bring one important task back, start useful work, and fit the supports to your week.",description:"Use one meaningful task to test capture, retrieval, task steps, timing, and a route back after distraction.",scope:"Skills training for adults. It is not a diagnosis or treatment and not a substitute for care. If difficulties are lasting and get in the way of daily life, talk to a health professional. Never start, stop or change medication without talking to your doctor.",outcome:"A task experiment with a retrieval cue, observed work, and a feasible next attempt.",photo:{id:"1759984782055-defe1abc0394",alt:"Young woman wearing headphones, working at a desk"},lessons:[h(o[0],2,{id:"1488190211105-8b0e65b80b4e",alt:"A hand writing a list in a notebook with a pen"}),h(o[1],1,{id:"1754548930574-6a995e5eb5a7",alt:"A hand checking off a to-do list on a tablet"}),h(o[2],0,{id:"1604344797006-2e4e8b39b79d",alt:"An hourglass on a wooden table"}),h(o[3],1,{id:"1624207616909-8bc0ca58743b",alt:"Yellow sticky notes stuck to a laptop"}),h(o[4],2,{id:"1549582100-d67ab35b3507",alt:"A planner and colorful pens on a white desk"})]},E=Object.freeze(Object.defineProperty({__proto__:null,COURSE:I,LESSONS_V2:o,SOURCES:S},Symbol.toStringTag,{value:"Module"})),C=[{id:"F01",title:"Sahih al-Bukhari 1 · Deeds and intentions",url:"https://sunnah.com/bukhari:1",type:"religious",finding:"Umar ibn al-Khattab narrates the Prophet's teaching about deeds and intentions.",limitation:"Religious source, not an empirical study. ODA's ordinary-task exercise is an interpretation, not the hadith's wording or a religious ruling. An app cannot judge sincerity or divine reward."},{id:"F02",title:"Sahih al-Bukhari 6491 · Intended and performed deeds",url:"https://sunnah.com/bukhari:6491",type:"religious",finding:"The passage narrated by Ibn Abbas describes the recording of intended and performed good and bad deeds.",limitation:"Its theological detail is not a psychological law. ODA's preparation and action records describe behavior; they cannot adjudicate religious reward."},{id:"F03",title:"The Qur'an · Al Imran 3:159",url:"https://quran.com/3/159",type:"religious",finding:"Consultation, resolve, and reliance appear together in this verse.",limitation:"ODA draws a voluntary practical reflection. It does not establish a universal chronology where trust begins only after preparation, offer exhaustive interpretation, or guarantee an outcome."},{id:"F07",title:"Sunan Abi Dawud 4811 · Thanking people",url:"https://sunnah.com/abudawud:4811",type:"religious",finding:"The teaching narrated by Abu Hurayrah links thanking people with thanking Allah. The entry displays sahih grading by al-Albani.",limitation:"Religious teaching, not psychological efficacy evidence. The specific thank-you template is ODA's adaptation; source checking is not a new authentication or a requirement for unsafe contact."},{id:"F08",title:"The Qur'an · Al-Sharh 94:5–6",url:"https://quran.com/94/5-6",type:"religious",finding:"Ease alongside hardship offers a religious source of hope.",limitation:"No guarantee that an individual difficulty ends today or by a chosen date. ODA's support step is an adaptation, not a clinical effect or exhaustive interpretation."},{id:"F11",title:"Sahih al-Bukhari 6464 · Small regular deeds and moderation",url:"https://sunnah.com/bukhari:6464",type:"religious",finding:"Aishah narrates teaching that emphasizes small regular deeds and moderation.",limitation:"The full passage also concerns deeds and salvation. An app streak measures neither faith nor salvation; the bounded kindness plan is ODA's adaptation."},{id:"F13",title:"Ano & Vasconcelles · 2005 · Religious coping and adjustment",url:"https://mhwbf.org/wp-content/uploads/2019/02/Ano-2005-Religious-coping-and-psychological-ad.pdf",type:"research",finding:"Across 49 mostly observational studies, religious coping was associated with adjustment. Table 5 pooled Fisher z values were .33 [.30, .35] for positive coping/positive adjustment and .22 [.19, .24] for negative coping/negative adjustment.",limitation:"Not raw correlations or evidence of causation. Among 8,115 participants with reported affiliation, 57% were Protestant and 28% Catholic. Confounding, self-report, and limited transfer to Islamic practice remain. Research categories are not judgments about a learner."},{id:"F14",title:"Kirca et al. · 2023 · Expressed gratitude and well-being",url:"https://doi.org/10.1007/s41042-023-00086-6",type:"research",finding:"Across 23 studies and 25 samples, expressed gratitude had a small average well-being benefit versus neutral comparisons: g = .22, 95% CI [.11, .33]. Against other well-being activities, g = .12 [−.02, .26].",limitation:"No demonstrated superiority over active comparisons or equivalence to therapy. Mostly nonclinical samples. The paper gives inconsistent participant totals, so neither total is used. No religious efficacy, compelled contact, or individual benefit guarantee."},{id:"F15",title:"Choi et al. · 2025 · Gratitude across cultures",url:"https://www.pnas.org/doi/10.1073/pnas.2425193122",type:"research",finding:"Across 145 papers and 163 samples in 28 countries, gratitude interventions had a small average effect on well-being, g = .19, 95% CI [.15, .22]. The future-study prediction interval was [−.21, .59].",limitation:"Largely nonclinical samples and varied procedures. Effects differ; the prediction interval includes zero. This does not validate one private sentence, predict one person's response, or establish Islamic gratitude as superior."},{id:"F16",title:"Curry et al. · 2018 · Kindness and the giver's well-being",url:"https://research-portal.uu.nl/ws/portalfiles/portal/247379826/1-s2.0-S0022103117303451-main.pdf",type:"research",finding:"Across 27 studies and 4,045 participants, kind acts showed a modest average benefit for the giver's well-being, δ = .28, 95% CI [.16, .41].",limitation:"Heterogeneous, mostly nonclinical studies. No guarantee for every giver or recipient, no treatment effect or measure of religious reward, and no support for unlimited self-sacrifice. Undetected bias or moderators does not prove their absence."},{id:"F18",title:"Nelson et al. · 2016 · Prosocial behavior trial",url:"https://sonjalyubomirsky.com/wp-content/uploads/2024/03/Nelson-Layous-Cole-Lyubomirsky-2016.pdf",type:"research",finding:"The other-kindness arm prescribed three kind acts on one day each week for four weeks, followed by a two-week check. The pooled prosocial-versus-control flourishing growth estimate was d = .31, p = .05.",limitation:"Abstract N differs from randomized group totals: 473 versus 472, with 464 in growth analyses. Confidence interval and preregistration were not verified. The one-act ODA version differs from the trial and does not promise universal benefit."},{id:"F19",title:"Wang et al. · 2021 · Obstacle-linked plans and goal pursuit",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"Across 21 articles and 24 independent effects involving 15,907 participants, mental contrasting with if-then planning helped goal attainment on average: g = .336, 95% CI [.229, .443].",limitation:"Varied goals and delivery; publication-bias adjustment reduced the estimate. This does not validate a sincere intention alone, prayer causing success, a faith-specific checklist, or an optimal ten-minute preparation dose."},{id:"F20",title:"NIMH · 2026 · Caring for your mental health",url:"https://www.nimh.nih.gov/health/topics/caring-for-your-mental-health",type:"guidance",finding:"Persistent distress and difficulty with usual activities warrant professional support. Crisis needs immediate assistance.",limitation:"Public guidance, not diagnosis or evidence of a spiritual cause. No requirement to wait two weeks or finish a course before seeking help. Prayer and spiritual counsel do not replace healthcare."},{id:"faith-kindness",title:"Curry et al. · 2018 · Kindness and the giver's well-being",url:"https://research-portal.uu.nl/ws/portalfiles/portal/247379826/1-s2.0-S0022103117303451-main.pdf",type:"research",finding:"Across 27 studies and 4,045 participants, kind acts showed a modest average benefit for the giver's well-being, δ = .28, 95% CI [.16, .41].",limitation:"Heterogeneous, mostly nonclinical studies. No guarantee for every giver or recipient, no treatment effect or measure of religious reward, and no support for unlimited self-sacrifice. Undetected bias or moderators does not prove their absence."}],s=[{schemaVersion:2,revision:2,id:"faith-1",courseId:"faith",locale:"en",title:"That good intention is still waiting",goal:"Carry out one useful piece of a commitment that expresses your chosen value.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"You meant to help. Give that promise one useful act today.",reason:{id:"faith-1-purpose-cost",label:"Which part would you choose without praise?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep my ordinary promise","Help within my real limits","Let my chosen value guide action"]},why:{id:"faith-1-why",label:"Which part would you choose without praise?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Bukhari's first hadith concerns deeds and intentions. Umar narrates the Prophet's teaching; this ordinary-task exercise is ODA's interpretation. Choose one commitment and let its purpose shape a useful act, rather than asking this app to judge your motives.","You may care about helping and also want recognition. You do not need to prove purity here. Choose what you want to serve, then perform one agreed piece. Preparation remains preparation when the act is unavailable. Keep spiritual reflection off ODA if you prefer. Optional answers are saved in your lesson or plan; coach sharing has separate consent controls."],example:{title:"Yusuf keeps a small promise",text:"Yusuf promised his neighbor a simple phone guide. At lunch he wants both to help and to look reliable. He chooses the helpful purpose and sends the agreed instructions for one call. The neighbor does not reply that afternoon. Yusuf records the message sent, keeps his motives private, and leaves whether it helped unknown."}},move:{invitation:"Give your promise one useful act. Edit the example to fit your actual agreement.",instructions:["Name the promised item, safe recipient, channel, and start event; private planning stays available.","Use your existing agreement; sending is the act, composing alone is preparation."],prompts:[],suggestions:{action:["Example: text Maya the agreed phone-setup link","Wash the two mugs I promised Yusuf","Send Sam the agreed appointment directions"],minimum:["Send Maya that agreed phone-setup link","Wash both agreed mugs","Send the agreed bus-stop instructions"],cue:["After I finish lunch","After our shared meal ends","When Sam's appointment reminder arrives"],place:["In our existing text thread","At our accessible kitchen sink","In our existing message thread"],minutes:[2,1],fallback:["Use our agreed email channel if texting fails","Agree another useful accessible cleanup task","Use our agreed accessible contact method"],observation:["Link sent; usefulness and reply remain unknown","Promised task performed, not only prepared","Instructions sent; no reply is still possible"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Example: text Maya the agreed phone-setup link",minimum:"Send Maya that agreed phone-setup link",cue:"After I finish lunch",place:"In our existing text thread",fallback:"Use our agreed email channel if texting fails",observation:"Link sent; usefulness and reply remain unknown",minutes:2},{action:"Wash the two mugs I promised Yusuf",minimum:"Wash both agreed mugs",cue:"After our shared meal ends",place:"At our accessible kitchen sink",fallback:"Agree another useful accessible cleanup task",observation:"Promised task performed, not only prepared",minutes:1},{action:"Send Sam the agreed appointment directions",minimum:"Send the agreed bus-stop instructions",cue:"When Sam's appointment reminder arrives",place:"In our existing message thread",fallback:"Use our agreed accessible contact method",observation:"Instructions sent; no reply is still possible",minutes:2}]},suggested:{action:"Example: text Maya the agreed phone-setup link",minimum:"Send Maya that agreed phone-setup link",minutes:2,cueHint:"After I finish lunch",placeHint:"In our existing text thread",obstacleHint:"Example: I explain my motives instead of sending",fallbackHint:"Use our agreed email channel if texting fails",observationHint:"Link sent; usefulness and reply remain unknown"},stopRule:"Choose only safe, voluntary acts within your limits.",accessibleAlternative:"Use your usual communication method; keep the plan off ODA."},result:{question:"Did you perform the useful act you chose?",observationPrompt:"What did you actually do, without sharing private motives?"},judgment:{primary:{id:"faith-1-decision",scenario:"Yusuf promised a classmate useful notes. They are ready. He wants to help and also wants recognition. Sending them is safe and welcome.",question:"Which choice serves the agreed commitment?",options:[{id:"private-reflection",text:"Reflect privately on his motives for another day before deciding whether to send the ready notes.",feedback:"Private reflection can be valuable. Here the safe, agreed resource is ready, so waiting for a cleaner motive delays the help. He can reflect without making purity a prerequisite."},{id:"send-agreed-notes",text:"Choose the helpful purpose and send the agreed notes without making praise a condition.",feedback:"This carries out the chosen commitment while allowing mixed motives. The record describes notes sent, not sincerity proven. Whether the classmate replies or benefits remains a separate observation."},{id:"explain-intention",text:"Explain his intention to the classmate first, then offer to send the notes after they respond.",feedback:"Explaining may feel honest, but asks the classmate to engage with his motives before receiving agreed help. He can keep reflection private and send the useful notes directly."}],bestOptionId:"send-agreed-notes"}},carry:{takeaway:"Give your chosen purpose a useful act. Keep the private intention yours.",followUp:{questionId:"faith-1-return",question:"Did the act serve your chosen purpose, or was it preparation?",observationPrompt:"What did you actually do, without sharing private motives?",adjustmentPrompt:"What would make the next attempt fit?"}},goDeeper:{sections:[{heading:"Religious meaning stays distinct from the record",paragraphs:["In Sahih al-Bukhari 1, Umar ibn al-Khattab narrates the Prophet's teaching about deeds and intentions. ODA's exercise asks how a chosen purpose might shape an ordinary commitment. That is a modern educational interpretation, not the hadith's wording, an exhaustive explanation, or a religious ruling. [F01] You may reflect privately without writing a motive in the app.","Bukhari 6491 describes intended and performed deeds in a theological account of their recording. A behavioral log cannot simplify that account into a completion score or determine divine reward. [F02] “Prepared instructions” and “sent the agreed instructions” are different records of behavior. Neither tells ODA how sincere you were. A plan, a quiz answer, a streak, or a pause offers no basis for judging faith. If an action is unavailable, preparation can be chosen honestly, with the next real opportunity named when useful."]},{heading:"A plan gives the purpose somewhere to act",paragraphs:["A goal-planning review combined 21 articles with 24 independent effects. Contrasting a desired goal with a real obstacle and making an obstacle-linked plan helped goal attainment on average. Publication-bias adjustment reduced the estimated benefit, and delivery and goals varied. This is psychological evidence about a planning package, not proof of religious reward, prayer efficacy, or this course's particular checklist. [F19]","ODA adapts the idea by naming a useful act, a recognizable cue, a feasible place, and a response to a likely obstacle. Choose one ordinary commitment that matters in your week and use it through the course. Later lessons refine preparation, acknowledge real help, or add support only when those needs arise. Mixed motives need not become mandatory disclosure. Keep the plan privately if preferred; then ODA can remember your return choice, but cannot retrieve action details it never received."]}],sourceIds:["F01","F02","F19"]}},{schemaVersion:2,revision:2,id:"faith-2",courseId:"faith",locale:"en",title:"Still checking? Finish your part of the promise",goal:"Execute your ready commitment, or address one specific preparation gap with an honest stopping boundary.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Ready but still checking? Another check needs a real gap.",reason:{id:"faith-2-actual-gap-cost",label:"What gap remains, or what would another check postpone?",kind:"text",maxLength:160,optional:!0,suggestions:["Ready: perform my saved promise","Missing information: check only that gap","Unconfirmed timing: ask for agreement"]},why:{id:"faith-2-why",label:"What preparation is enough for your next real step?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Consultation, resolve, and reliance appear together in Al Imran 3:159. ODA uses this as a practical reflection on effort and trust, not a rule that trust begins only after preparation. An uncertain result remains uncertain even when you take your part seriously.","Return to your commitment. If a real gap appeared, choose one useful preparation and a stopping boundary. If you already have what you need, choose execution instead of another check. Count preparation by what you completed, not by reassurance. Prayer may accompany your choice privately; it is not a required technique or promised outcome."],example:{title:"Yusuf tests once",text:"Yusuf's neighbor asks whether the phone guide works on her model. He checks one needed instruction at his kitchen table and corrects it. He stops after the planned test and offers a safe call tomorrow. She has not confirmed yet. Yusuf records preparation completed, keeps prayer private, and does not report the later call as done."}},move:{invitation:"Ready: execute your promise. Real gap: choose one bounded preparation act.",instructions:["Keep your promise; use Adapt, Preparation only for a specific reported gap.","Name its stopping boundary and next use, or mark that use unconfirmed.","Saving preparation books only preparation; confirm execution's date and cue separately in your calendar."],prompts:[{id:"faith-2-gap-next-use",label:"For preparation, what gap and stopping boundary matter, and is the next use confirmed?",kind:"text",maxLength:160,optional:!0,visible:!0,help:"Example: test Maya’s contact-setting once; next call unconfirmed. Keep its date/cue off ODA or in the action."}],suggestions:{action:["Example: text Maya the ready phone-setup link","Make my agreed phone-guide call to Maya"],minimum:["Send Maya that ready agreed link","Explain the agreed first phone contact"],cue:["After I finish lunch","When our confirmed 6 p.m. call starts"],place:["In our existing text thread","In our existing accessible call"],minutes:[2,5],fallback:["Use our agreed email if texting fails","If Maya is unavailable, ask about another date"],observation:["Link sent; repeated checks versus new information","Call attempted; another date may remain unconfirmed"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Example: text Maya the ready phone-setup link",minimum:"Send Maya that ready agreed link",cue:"After I finish lunch",place:"In our existing text thread",fallback:"Use our agreed email if texting fails",observation:"Link sent; repeated checks versus new information",minutes:2},{action:"Make my agreed phone-guide call to Maya",minimum:"Explain the agreed first phone contact",cue:"When our confirmed 6 p.m. call starts",place:"In our existing accessible call",fallback:"If Maya is unavailable, ask about another date",observation:"Call attempted; another date may remain unconfirmed",minutes:5}]},suggested:{action:"Example: text Maya the ready phone-setup link",minimum:"Send Maya that ready agreed link",minutes:2,cueHint:"After I finish lunch",placeHint:"In our existing text thread",obstacleHint:"Example: no information gap remains; I want certainty",fallbackHint:"Use our agreed email if texting fails",observationHint:"Link sent; repeated checks versus new information"},stopRule:"Stop at your boundary. Seek care now if distress disrupts life.",accessibleAlternative:"Use accessible rehearsal or consultation; prayer and writing stay optional."},result:{question:"Did you carry out the exact saved act?",observationPrompt:"What was executed, what was preparation, and is any next use still unconfirmed?"},judgment:{primary:{id:"faith-2-decision",scenario:"Yusuf has tested the instructions and confirmed the call time. He keeps checking the same steps because he still worries the call may go badly.",question:"Which choice fits the remaining need?",options:[{id:"longer-test",text:"Run another full test of the same instructions to feel more certain before the scheduled call.",feedback:"Another test can help when a specific gap remains. Here the steps are checked and the time confirmed. More repetition does not guarantee the call; keep the agreed execution opportunity."},{id:"cancel-call",text:"Replace tomorrow's call with another written guide so he can prepare without needing a live interaction.",feedback:"A written guide can be an accessible alternative if needed. Here the agreed call is ready and appropriate. Changing the format solely for certainty avoids the already feasible next step."},{id:"keep-opportunity",text:"End this preparation block, keep tomorrow's agreed call, and allow the result to remain uncertain.",feedback:"This keeps the useful preparation and its boundary without pretending certainty. Yusuf records what is ready and attempts the call at the agreed opportunity. Anxiety reduction is not the completion test."}],bestOptionId:"keep-opportunity"}},carry:{takeaway:"Finish the part you can do. Leave the outcome open and the next opportunity clear.",followUp:{questionId:"faith-2-gap-execution-return",question:"Did the saved act happen, and was any preparation tied to a real gap?",observationPrompt:"What was executed, what was preparation, and is any next use still unconfirmed?",adjustmentPrompt:"What would make the next attempt fit?"}},goDeeper:{sections:[{heading:"Effort and trust without a rigid chronology",paragraphs:["Al Imran 3:159 brings consultation, resolve, and reliance together. ODA draws a voluntary practical pattern from that verse: ask about a real gap, make a considered choice, and carry out the part available to you. This is an interpretation for everyday practice. It does not say that trust is absent until a preparation checklist has been completed or that a requested result must follow. [F03]","This exercise does not prescribe how to trust. The stopping boundary concerns your ordinary preparation; you decide whether this voluntary religious reflection helps you make that practical choice. Your useful preparation might be one question, a checked instruction, or one rehearsal. End at the boundary you chose, then confirm the execution date and start event separately in your calendar, or mark them unconfirmed. Saving preparation books that act and its next-day review; it does not schedule the later call. A planned call is not a completed call. Voluntary prayer can accompany either stage and remains private; no devotional dose or faith score is assigned."]},{heading:"Enough preparation is a practical choice",paragraphs:["Obstacle-linked planning research supports concrete plans for goal pursuit on average across varied settings. It does not test this religious framing, establish a two-minute optimum, or show that repeated reassurance checks improve the outcome. [F19] ODA's stopping boundary is an adaptation intended to keep preparation tied to a real need. If information is missing, seek it. If the next step is unsafe or inaccessible, choose another route or appropriate support.","If distress, disrupted sleep, or trouble with usual activities persists, professional support is available alongside religious reflection. NIMH guidance does not establish a spiritual cause or require a two-week wait before asking for help. Crisis needs immediate support rather than another preparation exercise. [F20] A knowledgeable religious adviser may be an optional source of spiritual counsel, but is not a replacement for healthcare. Record the preparation you actually did; leave emotional certainty and external success outside its completion conditions."]}],sourceIds:["F03","F19","F20"]}},{schemaVersion:2,revision:2,id:"faith-3",courseId:"faith",locale:"en",title:"Someone helped. Name what they actually did.",goal:"Write one truthful acknowledgment of support for your continuing commitment; sharing stays optional.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Help arrived amid disagreement? Thank them without pretending everything else is fine.",reason:{id:"faith-3-acknowledgment-tradeoff",label:"What makes thanks awkward, and which act can you honestly acknowledge?",kind:"text",maxLength:160,optional:!0,suggestions:["Name real help without settling disagreement","Keep contact safe and optional","If no help occurred, continue my promise"]},why:{id:"faith-3-why",label:"Whose safe contribution helped the commitment you chose?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Thanking people is linked to thanking Allah in the teaching narrated in Abu Dawud 4811. The short note here is ODA's adaptation. Name one real contribution that helped your chosen commitment. You do not need to describe the whole relationship as good.","Research finds a small average well-being benefit from expressed gratitude, with variable results. It does not prove therapy equivalence or require feeling better. Choose a related note; any unfinished promise remains separate. Name the act and benefit privately. Writing and voluntary sending are separate. If no help occurred, continue your promise instead."],example:{title:"Yusuf's truthful note",text:"Yusuf's sister lent him a clear phone guide. They still disagree about another family issue. He writes privately: “Your guide helped me explain the first call to our neighbor.” He keeps the note that evening because he is unsure about contact. The disagreement remains. He records only a note written, without storing its contents in ODA."}},move:{invitation:"Name real help; keep this related note separate from your promise.",instructions:["Use Plan a separate related act; any unfinished promise remains separate.","Name the observed act and benefit; share only through safe, welcome contact.","No help occurred? Continue your promise. Under pressure, acknowledge only that help or pause."],prompts:[],suggestions:{action:["Example: privately thank Maya for her guide","Privately thank Sam for Tuesday's covered shift"],minimum:["Write: Maya's guide helped explain one contact","Write: Sam's cover allowed my agreed appointment"],cue:["After I finish lunch","After agreed shift ends"],place:["In my own private notes","In a quiet accessible private space"],minutes:[2,1],fallback:["Speak only the act and benefit privately","Name only that shift; leave disagreement unresolved"],observation:["Note written or spoken; original promise remains outstanding","Acknowledgment made; original promise remains separate"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Example: privately thank Maya for her guide",minimum:"Write: Maya's guide helped explain one contact",cue:"After I finish lunch",place:"In my own private notes",fallback:"Speak only the act and benefit privately",observation:"Note written or spoken; original promise remains outstanding",minutes:2},{action:"Privately thank Sam for Tuesday's covered shift",minimum:"Write: Sam's cover allowed my agreed appointment",cue:"After agreed shift ends",place:"In a quiet accessible private space",fallback:"Name only that shift; leave disagreement unresolved",observation:"Acknowledgment made; original promise remains separate",minutes:1}]},suggested:{action:"Example: privately thank Maya for her guide",minimum:"Write: Maya's guide helped explain one contact",minutes:2,cueHint:"After I finish lunch",placeHint:"In my own private notes",obstacleHint:"Example: I feel pressure to settle our disagreement",fallbackHint:"Speak only the act and benefit privately",observationHint:"Note written or spoken; original promise remains outstanding"},stopRule:"Do not contact an unsafe person or erase harm to give thanks.",accessibleAlternative:"Speak or type privately; recipient and contents stay optional."},result:{question:"Did you make the acknowledgment you chose?",observationPrompt:"Was it written, spoken privately, or shared by choice?"},judgment:{primary:{id:"faith-3-honest-acknowledgment-decision",scenario:"Sam covered Yusuf’s Tuesday shift, allowing a care appointment. Their separate disagreement remains. Contact is safe. Sam has said they cannot cover next week and does not want another request now. Yusuf wants to acknowledge Tuesday’s help.",question:"Which acknowledgment respects the facts and Sam’s stated limit?",options:[{id:"faith-3-misstated-help",text:"Thank Sam for arranging the care appointment and covering Tuesday’s shift so Yusuf could attend.",feedback:"Sam covered the shift; the scenario does not say Sam arranged the appointment. Keep the acknowledgment to the act and benefit you observed. Accurate thanks can coexist with an unresolved disagreement."},{id:"faith-3-specific-thanks",text:"Thank Sam for Tuesday’s cover and name the care appointment it made possible, leaving the disagreement unresolved.",feedback:"This names the observed act and benefit while respecting the current boundary. Mixed feelings may remain. Yusuf can keep the note private or share voluntarily; neither his original promise nor the disagreement is settled."},{id:"faith-3-new-request",text:"Thank Sam for Tuesday’s cover and explain why another covered shift next week would also help.",feedback:"Thanks and a transparent request can coexist. Here Sam explicitly declined another request now, so adding one disregards that limit. Acknowledge Tuesday’s help and seek any future coverage elsewhere."}],bestOptionId:"faith-3-specific-thanks"}},carry:{takeaway:"Acknowledge the real help. A note does not complete your original promise or settle every hurt.",followUp:{questionId:"faith-3-related-note-return",question:"Was the related acknowledgment truthful and safe, while the original promise stayed separately recorded?",observationPrompt:"Was the note written, spoken, or shared? What original act remains outstanding?",adjustmentPrompt:"What would make the next attempt fit?"}},goDeeper:{sections:[{heading:"A specific note is an adaptation",paragraphs:["Abu Dawud 4811 links thanking people with thanking Allah. The listed entry attributes the narration to Abu Hurayrah and displays a sahih grading by al-Albani. ODA's practical note is a modern adaptation, not the wording of that source or a new religious authentication. [F07] You can acknowledge one contribution without sharing private religious reflection or turning the app into a judge of gratitude.","The template names what someone did and the benefit you observed. It is a writing aid, not a verified claim that specific thanks are scientifically superior to general thanks. A safe person's help can be real while disagreement or hurt remains real. Keep those facts separate. Writing privately and sending a message are different actions; record whichever you actually chose. A private note cannot be described as a delivered gratitude intervention, and an unanswered message does not cancel the act you performed."]},{heading:"Small average effects, no treatment equivalence",paragraphs:["The 2023 expressed-gratitude review included 23 studies and 25 samples. Compared with neutral conditions, the average well-being effect was small: g = .22, with a 95% confidence interval of .11 to .33. Against other well-being activities, the interval for the difference included zero. Those activities were not necessarily established clinical treatments, and a nonsignificant superiority test does not establish equivalence to therapy. The paper's inconsistent participant totals are withheld. [F14]","A larger 2025 gratitude review also found a small average benefit, but its prediction interval for a future study included zero. Results varied across procedures and settings. [F15] Neither review proves a religious teaching, guarantees a personal benefit, or validates this private one-sentence format. You may finish the act without feeling positive. Use the note if it serves your chosen relationship or life direction; change or stop the practice if it feels unhelpful or coercive."]}],sourceIds:["F07","F14","F15"]}},{schemaVersion:2,revision:2,id:"faith-4",courseId:"faith",locale:"en",title:"Carrying it alone? Ask for one clear thing.",goal:"Make one safe practical care request, with a fallback if support is unavailable.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Carrying it alone? Make one clear care request without judging your faith.",reason:{id:"faith-4-request-boundary-cost",label:"What makes a safe request difficult, and what boundary would make it possible?",kind:"text",maxLength:160,optional:!0,suggestions:["Ask for one defined task","Limit what private details I share","Use care without a productivity condition"]},why:{id:"faith-4-why",label:"What care would make your continuing commitment safer?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Al-Sharh's verses about ease alongside hardship offer religious hope, not a deadline for relief. Focus on the next manageable moment. Care may be the whole valued action. A related support request leaves your unfinished promise separate; asking does not perform that promise.","Religious coping research describes associations, not proof that a spiritual practice causes relief or struggle means weak faith. Make one specific request to a safe person or professional. If they cannot help, use a suitable fallback. The request is your action; their availability is an outcome. Private doubts and devotional details do not belong in a score."],example:{title:"Yusuf asks again elsewhere",text:"Yusuf is exhausted after caregiving and cannot manage the neighbor's agreed call tonight. He asks his brother to cover one household task; his brother cannot. Yusuf contacts another trusted relative and offers the neighbor a later call. Help is still unconfirmed. He records the request made and takes available rest, without judging his faith."}},move:{invitation:"For routine support, name one safe, specific request.",instructions:["Urgent need: seek immediate crisis or emergency help before scheduling any routine experiment.","Use Plan a separate related act; name help, recipient, channel, and time.","If declined, choose another available service or safe care; your unfinished promise remains separate."],prompts:[],suggestions:{action:["Example: text Maya for evening dishwashing help","Call my clinic about available appointment times"],minimum:["Ask Maya to wash dishes at 7","Ask the clinic for one suitable appointment"],cue:["After the agreed 6 p.m. care handover","When the clinic's phone line opens"],place:["In our existing text thread","At my accessible private phone space"],minutes:[2,5],fallback:["If declined, leave nonessential dishes and rest","Use the clinic's accessible booking channel"],observation:["Request sent; help received remains a separate fact","Contact made; appointment may remain unconfirmed"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Example: text Maya for evening dishwashing help",minimum:"Ask Maya to wash dishes at 7",cue:"After the agreed 6 p.m. care handover",place:"In our existing text thread",fallback:"If declined, leave nonessential dishes and rest",observation:"Request sent; help received remains a separate fact",minutes:2,kind:"support"},{action:"Call my clinic about available appointment times",minimum:"Ask the clinic for one suitable appointment",cue:"When the clinic's phone line opens",place:"At my accessible private phone space",fallback:"Use the clinic's accessible booking channel",observation:"Contact made; appointment may remain unconfirmed",minutes:5,kind:"support"}]},suggested:{kind:"support",action:"Example: text Maya for evening dishwashing help",minimum:"Ask Maya to wash dishes at 7",minutes:2,cueHint:"After the agreed 6 p.m. care handover",placeHint:"In our existing text thread",obstacleHint:"Example: the first person cannot help tonight",fallbackHint:"If declined, leave nonessential dishes and rest",observationHint:"Request sent; help received remains a separate fact"},stopRule:"Crisis or self-harm thoughts need immediate local crisis help; immediate danger needs emergency services. Seek help now, before scheduling.",accessibleAlternative:"Use an accessible contact method; prayer never replaces needed care."},result:{question:"Did you make the request or take the care step?",observationPrompt:"What care happened, and what remains unmet?"},judgment:{primary:{id:"faith-4-available-care-decision",scenario:"Leila needs help transferring her dependent tonight; doing it alone is unsafe. The dependent is safely seated now. A relative declined. The care service’s staffed line is open and can arrange a worker tonight; routine email is answered tomorrow. Leila can safely wait seated while calling.",question:"Which request addresses tonight’s need most directly?",options:[{id:"faith-4-staffed-line",text:"Call the staffed care line, request tonight’s transfer help, and keep the dependent safely seated while waiting.",feedback:"This names the immediate practical task and uses a source available tonight. Calling is the act; confirmed help is separate. If safety changes while waiting, seek appropriate immediate emergency assistance."},{id:"faith-4-general-call",text:"Call the staffed line to describe her exhausting week and ask what general caregiving support it offers.",feedback:"Describing the wider burden may help ongoing care. Tonight’s transfer need is more specific and cannot be deferred. Lead with that task, then discuss continuing support if time and safety permit."},{id:"faith-4-email-and-wait",text:"Email the exact transfer request and keep the dependent safely seated while waiting for tomorrow’s routine response.",feedback:"The email is specific and avoids an unsafe solo transfer. Its reply timing does not meet tonight’s need. Use the staffed line now; record whether suitable help is actually confirmed."}],bestOptionId:"faith-4-staffed-line"}},carry:{takeaway:"A clear request is your act. Available support is an outcome to check and follow up.",followUp:{questionId:"faith-4-related-support-return",question:"Was the care request made, was help available, and what need remains unmet?",observationPrompt:"What request or care happened? Which original promise remains separately outstanding?",adjustmentPrompt:"What would make the next attempt fit?"}},goDeeper:{sections:[{heading:"Hope can accompany practical care",paragraphs:["Al-Sharh 94:5–6 offers a religious source of hope through ease alongside hardship. It does not establish that your difficulty ends today, on a selected date, or in the way you want. ODA's support request is a practical adaptation, not a ruling or a clinical effect inferred from the verses. [F08] You may reflect privately or simply choose a care step.","A manageable moment can be much smaller than a day. Ask what immediate need can be named and what safe person or service could respond. An unavailable first contact is information about that contact, not evidence that you should carry everything alone. Rest or professional care can be the full valued action; neither needs to earn permission through productivity. A boundary may protect you better than another commitment. Do not use patience, gratitude, or forgiveness as an instruction to tolerate abuse or unsafe contact."]},{heading:"Research categories cannot judge your faith",paragraphs:["The religious-coping review combined 49 studies with 13,512 participants, largely observational and self-reported. Its familiar .33 and .22 values are pooled Fisher z values, not raw correlations. Among the 8,115 participants whose affiliation was reported, 57% were Protestant and 28% Catholic. That denominator does not describe every participant. The associations do not establish causation or the efficacy of Islamic practice. Research labels must not become a verdict about a learner's faith. [F13]","NIMH guidance supports professional help for persistent distress and impaired usual functioning; asking sooner is allowed. Prayer or optional spiritual counsel can accompany healthcare, but cannot replace needed treatment. Crisis or self-harm thoughts call for immediate crisis support: call or text 988 in the US; immediate life-threatening danger calls for emergency services. Elsewhere use local crisis or emergency services. [F20] Do not wait for a course result or a duration threshold before seeking urgent care."]}],sourceIds:["F08","F13","F20"]}},{schemaVersion:2,revision:2,id:"faith-5",courseId:"faith",locale:"en",title:"Be generous without breaking another promise",goal:"Retain your useful commitment, confirm wanted help, and date one attempt with a numeric time boundary.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"A helpful call keeps getting longer. Choose kindness your actual week can hold.",reason:{id:"faith-5-purpose-cost",label:"What will you limit so this commitment stays feasible?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep care within my capacity","Protect another existing promise","Offer useful help without requiring thanks"]},why:{id:"faith-5-why",label:"What will you limit so this commitment stays feasible?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Look back at the same commitment: what did you do, what helped, and what did it cost? Keep the useful act and any necessary support. Aishah's narration in Bukhari emphasizes regular small deeds and moderation. That teaching does not make an app streak a measure of faith.","Kindness studies find a modest average benefit for the giver, not a guarantee or permission to ignore limits. Retain your useful act, confirm it is wanted, and put its numeric boundary in Action or Minimum. Date one occurrence. Repetition is only considered here; tomorrow’s review helps choose another dated opportunity."],example:{title:"Yusuf ends on time",text:"Yusuf’s records show that helping with one phone contact is useful, but evenings conflict with care. His neighbor agrees to a two-minute text exchange after Saturday lunch. Yusuf sends the contact instructions and ends within two minutes. Another question remains. He records the useful message and limit kept. Next Saturday is considered, with no agreement yet."}},move:{invitation:"Keep your useful promise; date one wanted task with a numeric end boundary.",instructions:["Keep the original promise; change its size or timing only by deliberate agreement.","Store the boundary in Action or Minimum, or keep all details off ODA."],prompts:[],suggestions:{action:["Example: text Maya instructions within 2 minutes","Call Sam: one phone contact, 5 minutes maximum"],minimum:["Send agreed contact instructions within 2 minutes","Explain one agreed contact within 5 minutes"],cue:["After our agreed lunch ends","When Wednesday's confirmed 6 p.m. call starts"],place:["In our existing text thread","In our existing accessible call"],minutes:[2,5],fallback:["If more is needed, offer another confirmed date","If more is needed, agree a separate opportunity"],observation:["Agreed help sent, welcome, and two-minute limit kept","Contact explained, welcome, and five-minute limit kept"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Example: text Maya instructions within 2 minutes",minimum:"Send agreed contact instructions within 2 minutes",cue:"After our agreed lunch ends",place:"In our existing text thread",fallback:"If more is needed, offer another confirmed date",observation:"Agreed help sent, welcome, and two-minute limit kept",minutes:2},{action:"Call Sam: one phone contact, 5 minutes maximum",minimum:"Explain one agreed contact within 5 minutes",cue:"When Wednesday's confirmed 6 p.m. call starts",place:"In our existing accessible call",fallback:"If more is needed, agree a separate opportunity",observation:"Contact explained, welcome, and five-minute limit kept",minutes:5}]},suggested:{action:"Example: text Maya instructions within 2 minutes",minimum:"Send agreed contact instructions within 2 minutes",minutes:2,cueHint:"After our agreed lunch ends",placeHint:"In our existing text thread",obstacleHint:"Example: the request expands beyond our agreed two minutes",fallbackHint:"If more is needed, offer another confirmed date",observationHint:"Agreed help sent, welcome, and two-minute limit kept"},stopRule:"Protect health, sleep, money, and existing commitments. Unsafe help or contact is not required.",accessibleAlternative:"Use accessible help or choose rest, support, or a boundary."},result:{question:"Did you perform the bounded act you chose?",observationPrompt:"What was useful and welcome, and did your limit hold?"},judgment:{primary:{id:"faith-5-task-boundary-decision",scenario:"Nadia’s neighbor wants help using one phone contact before a Thursday appointment. Wednesday offers ten free minutes before Nadia’s fixed care duty. The neighbor welcomes a ten-minute call; texts are hard to read. Saturday offers twenty minutes, after the appointment.",question:"Which next plan fits the useful task and both people’s constraints?",options:[{id:"faith-5-saturday-call",text:"Offer Saturday’s twenty-minute call so the neighbor has more time to learn the phone steps.",feedback:"Saturday protects Nadia’s care duty and allows more practice. It misses the Thursday need. Use the agreed Wednesday window for this contact; consider Saturday separately for later questions."},{id:"faith-5-text-steps",text:"Send the contact steps by text on Wednesday, keeping her care duty and giving the neighbor written instructions.",feedback:"A text would preserve time and provide a reference. The neighbor finds texts hard to read, so this format may not meet the actual need. The agreed short call is accessible here."},{id:"faith-5-ten-minute-call",text:"Use Wednesday’s agreed ten-minute call for the one contact, state the end time, and stop before care duty.",feedback:"This meets the pre-appointment need through a welcome accessible method while protecting care. Record the contact explained and limit kept. Another question remains a separate opportunity, not an obligation to overrun."}],bestOptionId:"faith-5-ten-minute-call"}},carry:{takeaway:"Keep one welcome act that fits your week. Let usefulness and cost guide the next choice.",followUp:{questionId:"faith-5-bounded-occurrence-return",question:"Was the agreed task useful and welcome, and did its numeric boundary protect your other commitments?",observationPrompt:"What useful act happened, was the limit kept, and is another date confirmed?",adjustmentPrompt:"What would make the next attempt fit?"}},goDeeper:{sections:[{heading:"Regular does not mean unlimited",paragraphs:["Bukhari 6464 emphasizes small regular deeds and moderation in a narration attributed to Aishah. The fuller passage also concerns deeds and salvation. ODA draws a voluntary practical reflection about a sustainable act; it cannot judge either religious worth or salvation from a count. A private intention, devotional practice, skipped occasion, or app streak is not a faith score. [F11]","Review the action and support records you chose to keep. Which piece genuinely served the purpose? What time, effort, or displaced commitment did it require? Retain that useful piece rather than adding another ritual. Consider daily or weekly repetition, but date one actual occurrence. This plan books that occurrence and its next-day return, not a recurring cadence. Confirm help is wanted, state a feasible boundary, and keep it. If the need exceeds your capacity, a smaller offer, a referral, rest, or stopping may be more responsible than promising unlimited help. Thanks and warm feelings are not completion conditions."]},{heading:"What kindness research actually tested",paragraphs:["The 2018 kindness review combined 27 studies involving 4,045 participants. Kind acts produced a modest average well-being benefit for the giver, with heterogeneous samples and procedures. This does not guarantee benefit to every giver or recipient, measure religious reward, or validate unlimited self-sacrifice. Undetected moderators or publication bias do not prove none exists. [F16]","In a separate trial, the other-kindness arm prescribed three acts on one day each week for four weeks, followed by a two-week check. It did not prescribe six weeks of acts. The paper's abstract and randomized totals differed, and its main growth analyses used a smaller set. [F18] ODA's one-act, capacity-bounded plan is a different adaptation. Schedule the next real opportunity only if it still fits. Tomorrow's return checks usefulness, welcome, and cost; it does not require repeating today or keeping a religious streak."]}],sourceIds:["F11","F16","F18"]}}];function p(e,t,a){return{id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,practice:[e.move.instructions[0],e.move.instructions[1],"Record what actually happened and review this same experiment tomorrow."],reflection:e.direction.reason.label,question:e.judgment.primary.question,options:e.judgment.primary.options.map(n=>n.text),correct:t,feedback:e.judgment.primary.options[t].feedback,takeaway:e.carry.takeaway,sources:e.id==="faith-5"?[...e.goDeeper.sourceIds,"faith-kindness"]:e.goDeeper.sourceIds,photo:a}}const D={id:"faith",title:"You mean to help. Let faith shape one ordinary promise",subtitle:"5 voluntary lessons. Try one meaningful commitment, keep reflection private, and make room for care and limits.",description:"Connect voluntary Islamic reflection with one chosen ordinary act, then revise it using preparation, truthful thanks, support, and honest boundaries.",scope:"Islamic reflection and voluntary daily practices. Religious sources and psychological research are shown separately; anxiety or struggle is not treated as a lack of faith. This is not a religious ruling and not a substitute for mental health care. If you are in crisis or thinking about harming yourself, contact your local emergency number.",outcome:"A tried or paused commitment, private reflection, and a dated next step or support.",photo:{id:"1767396024869-756a346dc39d",alt:"A mosque courtyard with arched doorways and trees"},lessons:[p(s[0],1,{id:"1778616364918-34490657598f",alt:"A man holding prayer beads"}),p(s[1],2,{id:"1590682680695-43b964a3ae17",alt:"Hands planting a seedling in soil"}),p(s[2],1,{id:"1634906346143-aacbc4c02fec",alt:"A thank-you note on a table next to a pair of glasses"}),p(s[3],0,{id:"1570739260082-39a84dae80c8",alt:"A lit lantern on a wooden table"}),p(s[4],2,{id:"1710092784814-4a6f158913b8",alt:"A woman handing a plate of food to another woman"})]},z=Object.freeze(Object.defineProperty({__proto__:null,COURSE:D,LESSONS_V2:s,SOURCES:C},Symbol.toStringTag,{value:"Module"})),W=[{id:"F01",title:"Monsell · 2003 · Task switching",url:"https://psychfiles.net/experimental/Monsell_2003.pdf",type:"research",finding:"Across simple laboratory-task studies, responses after switches were slower and usually more error-prone. Preparation reduced the cost without reliably eliminating it.",limitation:"Narrative review with no pooled workplace-loss estimate. No universal recovery time, productivity percentage, or test of ODA's preparation prompts."},{id:"F02",title:"Albulescu et al. · 2022 · Micro-breaks",url:"https://doi.org/10.1371/journal.pone.0272460",type:"research",finding:"22 samples, 2,335 participants: vigor d = .36 [.16, .55], fatigue improvement .35 [.19, .50], performance .16 [-.04, .37].",limitation:"Outcome samples differ; modest heterogeneous evidence. No optimal duration or activity, reliable demanding-task performance improvement, or proof that all screen leisure fails to restore energy."},{id:"F03",title:"Harkin et al. · 2016 · Monitoring goal progress",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 randomized studies, 19,951 participants overall: monitoring interventions improved goal attainment on average, d = .40 [.32, .48].",limitation:"Varied goals and methods. Moderator associations do not validate a particular diary, require public sharing, or prove this exact focus routine causes gains."},{id:"F04",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 tests with 8,461 participants found average goal-attainment support from specific if-then planning, d = .65 [.60, .70].",limitation:"Heterogeneous older studies. No guaranteed effect for a phone-urge sentence or validation of a combined time-blocking package."},{id:"F06",title:"Kushlev, Proulx & Dunn · 2016 · Lower-interruption phone setup",url:"https://interruptions.net/literature/Kushlev-CHI16.pdf",type:"research",finding:"221 students tried two week-long setups. Paired symptom tests used 190 respondents. Alerts off plus phone out of sight reduced self-reported inattention modestly: 2.27 versus 2.38; d = .44.",limitation:"Alerts and visibility/reach changed together. Unblinded self-report; no isolated alert effect, ADHD treatment, or significant direct productivity improvement."},{id:"F07",title:"Mark, Gudith & Klocke · 2008 · Interrupted work, speed, and stress",url:"https://ics.uci.edu/~gmark/chi08-mark.pdf",type:"research",finding:"48 participants in simulated email work used less net task time under interruptions but reported higher stress. Interruption-handling time was subtracted.",limitation:"Small mostly student sample. Not faster total elapsed work, guaranteed unchanged quality, long-term stress effects, or a universal recovery time."},{id:"F08",title:"Biwer et al. · 2023 · Fixed and self-chosen study breaks",url:"https://doi.org/10.1111/bjep.12593",type:"research",finding:"110 students randomized, 87 analyzed in one two-hour session. Fixed 24/6 or 12/3 schedules showed favorable experience patterns; no significant task-completion difference.",limitation:"Attrition and exclusions; longer planned study reduced to one session. No universal best interval, long-term learning gain, or validation of the full branded Pomodoro method."},{id:"F10",title:"Leroy & Glomb · 2018 · Interrupted tasks and return plans",url:"https://ideas.repec.org/a/inm/ororsc/v29y2018i3p380-397.html",type:"research",finding:"Four studies reported that a return plan reduced attention residue and supported decisions or recall on the interrupting task. First field study was a survey.",limitation:"Accessible abstract and university summary only. Exact worksheet, dose, and pooled effects unverified. No demonstrated benefit on the original task after return."},{id:"F11",title:"Lopez et al. · 2018 · Cochrane review of CBT for adult ADHD",url:"https://www.cochrane.org/evidence/CD010840_cognitive-behavioural-therapy-attention-deficit-hyperactivity-disorder-adhd-adults",type:"research",finding:"14 randomized trials with 700 adults assessed structured cognitive-behavioral interventions. Symptom benefits depended on the comparator; certainty ranged from very low to moderate.",limitation:"Clinical programs differ from ODA settings or timers. Little long-term follow-up; this course is not assessment or treatment and gives no medication advice."},{id:"F13",title:"Ruiz Pardo & Minda · 2022 · Preregistered brain-drain replication",url:"https://pubmed.ncbi.nlm.nih.gov/36007374/",type:"research",finding:"A preregistered direct replication of the original second phone-location experiment did not reproduce location differences in the tested tasks.",limitation:"Accessible primary abstract verifies the failed replication but supplies no participant total or exact p value. No proof of exact zero effects everywhere or harmless active checking."},{id:"F14",title:"Hartanto et al. · 2024 · Mere smartphone presence synthesis",url:"https://assets.pubpub.org/mgkf17za/tmb_tmb0000123-41706626995650.pdf",type:"research",finding:"33 studies, 53 samples, 166 effects: no reliable overall impairment from mere phone presence, d = -.02 [-.06, .01]. Working-memory subgroup became nonsignificant after bias correction.",limitation:"Participant totals conflict within the paper, so no definitive total is taught. Task and synthesis differences remain; this does not study active checking or alerts."},{id:"F15",title:"Cal Newport · 2013, updated 2023 · Time-blocking account",url:"https://calnewport.com/deep-habits-the-importance-of-planning-every-minute-of-your-work-day/",type:"technique",finding:"Newport describes a personal scheduling routine with labeled blocks, reactive work, and room to redraw the plan.",limitation:"Practitioner account supplies no intervention trial or effect estimate. It does not establish whether controlled studies of this exact routine exist."},{id:"F16",title:"Parry · 2024 · Brain-drain meta-analysis",url:"https://research.vu.nl/en/publications/does-the-mere-presence-of-a-smartphone-impact-cognitive-performan/",type:"research",finding:"A competing synthesis found an adverse working-memory average while the other cognitive-function summaries were null.",limitation:"Accessible abstract only; exact pooled effects and study-count unit unverified. Heterogeneity and poor power limit conclusions. Mere presence differs from active phone use."},{id:"task-switching",title:"Monsell · 2003 · Task switching",url:"https://psychfiles.net/experimental/Monsell_2003.pdf",type:"research",finding:"Across simple laboratory-task studies, responses after switches were slower and usually more error-prone. Preparation reduced the cost without reliably eliminating it.",limitation:"Narrative review with no pooled workplace-loss estimate. No universal recovery time, productivity percentage, or test of ODA's preparation prompts."},{id:"interruptions",title:"Mark, Gudith & Klocke · 2008 · Interrupted work, speed, and stress",url:"https://ics.uci.edu/~gmark/chi08-mark.pdf",type:"research",finding:"48 participants in simulated email work used less net task time under interruptions but reported higher stress. Interruption-handling time was subtracted.",limitation:"Small mostly student sample. Not faster total elapsed work, guaranteed unchanged quality, long-term stress effects, or a universal recovery time."},{id:"notifications",title:"Kushlev, Proulx & Dunn · 2016 · Lower-interruption phone setup",url:"https://interruptions.net/literature/Kushlev-CHI16.pdf",type:"research",finding:"221 students tried two week-long setups. Paired symptom tests used 190 respondents. Alerts off plus phone out of sight reduced self-reported inattention modestly: 2.27 versus 2.38; d = .44.",limitation:"Alerts and visibility/reach changed together. Unblinded self-report; no isolated alert effect, ADHD treatment, or significant direct productivity improvement."},{id:"phone-presence",title:"Hartanto et al. · 2024 · Mere smartphone presence synthesis",url:"https://assets.pubpub.org/mgkf17za/tmb_tmb0000123-41706626995650.pdf",type:"research",finding:"33 studies, 53 samples, 166 effects: no reliable overall impairment from mere phone presence, d = -.02 [-.06, .01]. Working-memory subgroup became nonsignificant after bias correction.",limitation:"Participant totals conflict within the paper, so no definitive total is taught. Task and synthesis differences remain; this does not study active checking or alerts."},{id:"brain-drain-replication",title:"Ruiz Pardo & Minda · 2022 · Preregistered brain-drain replication",url:"https://pubmed.ncbi.nlm.nih.gov/36007374/",type:"research",finding:"A preregistered direct replication of the original second phone-location experiment did not reproduce location differences in the tested tasks.",limitation:"Accessible primary abstract verifies the failed replication but supplies no participant total or exact p value. No proof of exact zero effects everywhere or harmless active checking."},{id:"microbreaks",title:"Albulescu et al. · 2022 · Micro-breaks",url:"https://doi.org/10.1371/journal.pone.0272460",type:"research",finding:"22 samples, 2,335 participants: vigor d = .36 [.16, .55], fatigue improvement .35 [.19, .50], performance .16 [-.04, .37].",limitation:"Outcome samples differ; modest heterogeneous evidence. No optimal duration or activity, reliable demanding-task performance improvement, or proof that all screen leisure fails to restore energy."},{id:"focus-ready-to-resume",title:"Leroy & Glomb · 2018 · Interrupted tasks and return plans",url:"https://ideas.repec.org/a/inm/ororsc/v29y2018i3p380-397.html",type:"research",finding:"Four studies reported that a return plan reduced attention residue and supported decisions or recall on the interrupting task. First field study was a survey.",limitation:"Accessible abstract and university summary only. Exact worksheet, dose, and pooled effects unverified. No demonstrated benefit on the original task after return."},{id:"focus-newport-time-blocking",title:"Cal Newport · 2013, updated 2023 · Time-blocking account",url:"https://calnewport.com/deep-habits-the-importance-of-planning-every-minute-of-your-work-day/",type:"technique",finding:"Newport describes a personal scheduling routine with labeled blocks, reactive work, and room to redraw the plan.",limitation:"Practitioner account supplies no intervention trial or effect estimate. It does not establish whether controlled studies of this exact routine exist."},{id:"brain-drain",title:"Ward et al. · 2017 · Original phone-presence experiments",url:"https://www.journals.uchicago.edu/doi/full/10.1086/691462",type:"research",finding:"Original student experiments found small differences on selected working-memory measures under phone-location conditions. Sustained attention did not show the same result.",limitation:"A preregistered direct replication failed. Reviews disagree on working memory and one finds no reliable overall impairment. Do not teach the original result alone as settled fact."},{id:"focus-attention-residue",title:"Leroy · 2009 · Attention residue",url:"https://ideas.repec.org/a/eee/jobhdp/v109y2009i2p168-181.html",type:"research",finding:"Two experiments reported persistent thoughts about a prior task accompanied poorer performance on the subsequent task.",limitation:"Accessible abstract only; detailed methods, sample totals, and effects unavailable. No quantified everyday attention tax or recommendation for chronic time pressure."}],r=[{schemaVersion:2,revision:2,id:"focus-1",courseId:"focus",locale:"en",title:"Busy all day? Protect one useful move",goal:"Do a useful unit of your chosen task and leave a clear return marker.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Still have an unfinished report after an hour of tabs? Give your chosen task an actual turn.",reason:{id:"focus-1-reason",label:"What worthwhile task keeps paying for your optional switches?",kind:"text",maxLength:160,optional:!0,suggestions:["My report stays unfinished","I lose the conversation’s thread","Optional tabs replace my study time","No observed cost yet"]},why:{id:"focus-1-purpose",label:"What would this move make possible in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Choose one task that serves your life, and keep it through this course. In laboratory studies, switching simple tasks slowed the next response and usually increased mistakes. Preparing reduced that cost without reliably removing it. This is not a universal productivity percentage.","For your next small block, produce a useful unit before an optional switch. If a routine interruption needs you, leave a short marker: where you stopped and the first move on return. That marker is a practical adaptation, not proven faster recovery. Skip it when immediate safety or care requires action."],example:{title:"Leila leaves a return marker",text:"After the morning check-in, Leila works on the same budget report for ten minutes. She corrects one travel-cost line before opening email. A colleague needs a figure soon. She writes “Check row 40 next,” handles the request, and returns to that row. The report is unfinished; one correction and one return are real."}},move:{invitation:"Keep your task. New plan? Name an output and cue in this report example.",instructions:["Name the actual task and output before saving this editable example.","At a routine switch, leave a return marker if a brief pause is safe."],prompts:[],suggestions:{action:["Correct one report line; note next step","Write one proposal sentence; note next step","Complete one practice problem; note next step"],minimum:["Correct one report line","Write one usable proposal sentence","Complete one practice problem"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"In two days",daysFromToday:2}],cue:["After today’s morning check-in","After lunch, before optional email","After my first available break"],place:["At my work desk","At my kitchen table with task tools","Where my task tools are ready"],minutes:[10,2,5],fallback:["Note next report step before answering","Correct one report line after the request","Choose the next feasible opening"],observation:["My output and next return move","Which switches were necessary","Which optional switch I deferred"]},suggested:{action:"Correct one report line; note next step",minimum:"Correct one report line",minutes:10,cueHint:"After today’s morning check-in",placeHint:"At my work desk",obstacleHint:"A routine request interrupts my task",fallbackHint:"Note next report step before answering",observationHint:"My output and next return move"},accessibleAlternative:"Use dictation or an accessible reminder; a two-minute useful task unit is valid.",stopRule:"Skip the marker for emergencies or immediate care; keep required contacts reachable."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do or produce?"},judgment:{primary:{id:"focus-1-decision",scenario:"Leila is checking report costs. A colleague needs a figure shortly. There is no emergency, and she can spare a brief note.",question:"Which response balances both tasks?",options:[{id:"focus-1-answer-now",text:"Answer the colleague immediately, then rely on memory to find the unfinished report step when she returns.",feedback:"This is responsive, but it discards an available low-cost return cue. A brief marker can name the next step before Leila handles the legitimate request."},{id:"focus-1-marker-first",text:"Note “check row 40 next,” handle the needed request, then return to that named report step.",feedback:"This respects the request and preserves a usable next move. The marker is a practical aid to try, not evidence that every interruption becomes harmless or recovery will be faster."},{id:"focus-1-finish-report",text:"Tell the colleague she will send the figure once the report is complete, then keep working without switching.",feedback:"Protecting the task matters, but the request is time-bound and a brief note is feasible. Finish everything first would ignore this dependency. Leave a marker, then respond."}],bestOptionId:"focus-1-marker-first"}},carry:{takeaway:"Protect useful work and leave a way back. Necessary interruptions still deserve a response.",followUp:{questionId:"focus-1-return",question:"Did your return marker tell you the next actual move?",observationPrompt:"What happened at the saved opportunity?",adjustmentPrompt:"What one change fits your next opportunity?"}},goDeeper:{sections:[{heading:"Switch cost is a bounded finding",paragraphs:["Monsell's 2003 review describes experiments with simple cognitive tasks. Responses immediately after a switch were slower and usually more error-prone. Preparing in advance reduced the cost without reliably eliminating it. The review does not supply a pooled workplace-loss percentage or a universal recovery time. [F01] Use the distinction to choose which switches can wait, rather than declaring every interruption harmful.","Mark and colleagues' small 2008 simulated-email experiment illustrates another limit. Interrupted participants used less net task time while reporting more stress. Interruption-handling time was subtracted, so the finding does not mean faster total elapsed work. Quality measures were limited; it cannot guarantee unchanged real-world work quality. [F07] This lesson's short output-and-marker block is an ODA adaptation. Your task, role, health, and care responsibilities determine what is feasible. Count a useful line or task unit, not a timer running or a tally made while postponing the task."]},{heading:"What the return-plan evidence measured",paragraphs:["Leroy and Glomb's 2018 article reported four studies on interruptions and attention remaining with the original task. A return plan reduced that residue and supported decisions or recall on the interrupting task. The first field study was a survey of professionals, not an intervention experiment. The accessible abstract and university description do not establish a benefit on the original task after return. [F10]","The accessible abstract and university description do not supply a complete published worksheet or laboratory dose. A short note naming your stopping point and next action is therefore a source-informed ODA adaptation. Do not delay an emergency or immediate care need to complete it. At a routine pause, use words, dictation, or your usual accessible reminder. When you resume, check whether it named a usable action. An easier return is an observation, not a controlled test of the mechanism. Record what you produced and what still needs doing, even when the block ended early."]}],sourceIds:["F01","F07","F10"]}},{schemaVersion:2,revision:2,id:"focus-2",courseId:"focus",locale:"en",title:"Every ping gets a vote. Choose yours",goal:"Keep needed contacts reachable and attempt your existing task with one fewer optional interruption.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Three chat pings while you try to write a sentence? Choose what can wait for this block.",reason:{id:"focus-2-reason",label:"Who needs you now, and what can safely wait?",kind:"text",maxLength:160,optional:!0,suggestions:["Care calls now; group chat later","Client deadline now; newsletters later","No required contact during this opening","Required work calls cannot wait"]},why:{id:"focus-2-purpose",label:"What would this move make possible in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Keep the same task and check who must reach you. One phone experiment changed alerts and visibility together. Students reported fewer attention-related symptoms in the lower-interruption week. It did not isolate notifications alone or show that the setup treats ADHD.","Use that boundary to design your own test. Preserve required contact channels first. Then change one optional interruption setting for a feasible block, keeping your previous phone placement. The work is the task unit you produce. Silencing an app is setup. Choose a message-check opportunity that fits your care and work responsibilities."],example:{title:"Leila chooses availability",text:"Leila keeps her report and ten-minute opening. Her father may need to call, so she checks that his channel stays available. She silences only the nonurgent group chat and keeps the phone where it was. She corrects another budget line. A work request still interrupts her; she records it and leaves a return marker."}},move:{invitation:"Keep your output. New plan? Edit this report example; preserve required contacts.",instructions:["Check required contact access before changing one optional interruption setting.","Name the output and real opening; settings alone are preparation."],prompts:[],suggestions:{action:["Correct one report line with chat paused","Write one proposal sentence with chat paused","Solve one practice problem between required checks"],minimum:["Correct one report line; keep calls reachable","Write one proposal sentence; keep calls reachable","Complete one problem between required checks"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"In two days",daysFromToday:2}],cue:["After today’s required message check","After lunch, before optional email","After my scheduled message check"],place:["At my work desk","At my kitchen table with phone reachable","At my usual work desk"],minutes:[10,2,5],fallback:["Keep care calls; pause only group chat","Restore access and choose another setting","Write one report sentence between required checks"],observation:["My output and required interruptions","Whether needed contacts could reach me","Which optional setting I changed"]},suggested:{action:"Correct one report line with chat paused",minimum:"Correct one report line; keep calls reachable",minutes:10,cueHint:"After today’s required message check",placeHint:"At my work desk",obstacleHint:"I am unsure whether a needed contact can reach me",fallbackHint:"Keep care calls; pause only group chat",observationHint:"My output and required interruptions"},accessibleAlternative:"Use a visible task card or accessible reminder; keep required calendars and communication tools.",stopRule:"Keep emergency, care, and required work channels available; do not trust untested exceptions."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do or produce?"},judgment:{primary:{id:"focus-2-decision",scenario:"Leila has a ten-minute report opening, a parent who may call, and repeated nonurgent group-chat pings. Contact exceptions are untested.",question:"What should she do first?",options:[{id:"focus-2-silence-all",text:"Use the phone’s default focus mode to reduce pings, keeping the device visible in case her parent calls.",feedback:"This reduces interruptions, but a visible phone does not verify its default focus-mode exceptions. Check that the needed care channel remains reachable before enabling settings that could block it."},{id:"focus-2-rely-on-restraint",text:"Leave every alert active and decide each time whether the message deserves an immediate reply.",feedback:"This preserves contact access, but leaves the repeated optional interruption in place. Leila can protect the group-chat boundary while keeping the care channel reachable."},{id:"focus-2-preserve-access",text:"Verify the care channel stays reachable, silence the nonurgent chat, then attempt the report and check messages afterward.",feedback:"This protects the task while respecting the actual care need. The setup is preparation. Record the report work separately, and revise any exception that did not work as intended."}],bestOptionId:"focus-2-preserve-access"}},carry:{takeaway:"Availability is a choice with responsibilities. Change optional interruptions while keeping needed access.",followUp:{questionId:"focus-2-return",question:"Did your setting protect the task while keeping needed contacts reachable?",observationPrompt:"What happened at the saved opportunity?",adjustmentPrompt:"What one change fits your next opportunity?"}},goDeeper:{sections:[{heading:"The experiment changed a bundle",paragraphs:["Kushlev and colleagues' 2016 counterbalanced experiment involved 221 university students. The high-interruption week combined enabled alerts with a phone within sight and reach. The lower-interruption week combined disabled auditory, vibration, and visual alerts with a phone kept out of sight. These changes happened together. Paired symptom comparisons used 190 respondents. [F06]","Average self-reported inattention was 2.38 versus 2.27 on a one-to-four scale, with reported d = .44. Hyperactivity ratings also differed modestly. Participants knew their settings, and this was one short student experiment. It did not isolate an alerts-only effect, establish ADHD causation or treatment, or demonstrate a significant direct productivity improvement. This lesson changes one optional setting while retaining your prior placement. That narrower personal trial is an ODA adaptation, not a reproduction of the week-long protocol. The reason to record output is to find out what actually happened to your chosen task."]},{heading:"A boundary has to fit the role",paragraphs:["Start with the real availability requirement. A care call, on-call channel, or time-bound work tool may need an immediate response. Do not assume that a named exception works without checking the setting. If you cannot confirm access, keep the channel available and adjust a different source of optional interruption. This is the course's safety and feasibility rule, not a promise from the phone study. [F06]","Use an external reminder or a visible next-step note if that makes the block accessible. Check messages afterward only when your role allows the delay. A blocked necessary message is a result that calls for correction, even if output improved. Persistent attention difficulties affecting daily functioning deserve professional assessment; settings are not treatment. The Cochrane review concerns structured cognitive-behavioral interventions for adults with ADHD, not this short routine. [F11] You can seek support now without proving that you failed enough phone experiments first. Keep the task, care, and record honest."]}],sourceIds:["F06","F11"]}},{schemaVersion:2,revision:2,id:"focus-3",courseId:"focus",locale:"en",title:"Phone within reach? Make checking a choice",goal:"Test one workable phone placement during your task and record urges and pickups separately.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Your phone on the desk is not a verdict on your discipline. Watch what you actually do.",reason:{id:"focus-3-reason",label:"What happens just before you reach for the phone?",kind:"text",maxLength:160,optional:!0,suggestions:["A sentence gets difficult","I expect a needed message","I check without noticing","No recent pickup to recall"]},why:{id:"focus-3-purpose",label:"What would this move make possible in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A phone nearby and a phone you keep checking are different questions. Research reviews disagree about some memory tasks; one found no reliable overall impairment from mere presence. Neither conclusion settles what happens when you use the phone.","Keep your task, duration, and alerts similar across attempts. No record yet? Make this your first placement test. Change placement; preserve required access. Note both urges and actual pickups in this session and any comparison. Different workloads or fatigue limit the comparison. Use the record to choose a workable arrangement, not to prove your phone caused a result."],example:{title:"Leila compares matching observations",text:"Leila keeps her report, ten-minute block, and safe alert settings. She moves the phone from the desk to an accessible shelf. She records four urges, one pickup, and two corrected lines. Yesterday she recorded five urges and three pickups. Today was quieter, so she treats the shelf as worth trying again, not proven better."}},move:{invitation:"Keep your output. New plan? Edit this report example; preserve phone access.",instructions:["Change only placement; keep task, duration, alerts, and required access comparable.","Note urges and pickups separately after work if tallying distracts; mark uncertainty."],prompts:[],suggestions:{action:["Correct one report line, phone on shelf","Correct one report line, phone on desk","Write one proposal sentence, phone safely reachable"],minimum:["Correct one report line","Write one usable report sentence","Complete one practice problem"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"In two days",daysFromToday:2}],cue:["After today’s required message check","After confirming required phone access","After lunch, before optional email"],place:["At my desk, phone on reachable shelf","At my desk, phone safely accessible","At my kitchen table with phone reachable"],minutes:[10,2,5],fallback:["Stop tallying; note urges/pickups afterward, marking uncertainty","Use a reachable but less tempting spot","Stop counting and protect the task"],observation:["Urges, pickups, and actual task output","Task differences between the two blocks","Whether required access was preserved"]},suggested:{action:"Correct one report line, phone on shelf",minimum:"Correct one report line",minutes:10,cueHint:"After today’s required message check",placeHint:"At my desk, phone on reachable shelf",obstacleHint:"Counting events competes with doing the task",fallbackHint:"Stop live tallying; note remembered urges and pickups afterward. Mark uncertain counts as uncertain, not zero.",observationHint:"Urges, pickups, and actual task output"},accessibleAlternative:"Use an end-of-block note. Uncertain counts stay uncertain, not zero; missing counts do not erase actual task work.",stopRule:"Preserve required call and calendar access; choose another placement if access would be blocked."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do or produce?"},judgment:{primary:{id:"focus-3-decision",scenario:"Leila had fewer pickups on a quieter shelf day. She needs the phone for tomorrow’s task. Another ten-minute report opening allows the same measures.",question:"Which next plan answers tomorrow’s placement question?",options:[{id:"focus-3-provisional-placement",text:"Repeat the report and measures with the phone safely reachable, then choose a placement that fits this task.",feedback:"Tomorrow’s task needs phone access, so another comparable attempt addresses that constraint. The quieter shelf day supports a preference, not proof of what caused the pickup difference."},{id:"focus-3-settled-placement",text:"Keep the shelf for the week without further counting, using the quieter session as a practical preference.",feedback:"That can be a workable preference when access fits. Tomorrow’s task needs the phone, so retaining the shelf unchanged misses the new constraint. Fewer pickups also do not establish causation."},{id:"focus-3-ignore-observations",text:"Keep the phone on the desk because a review found no overall penalty from merely having it nearby.",feedback:"The desk may fit tomorrow’s phone need. But a pooled presence result does not answer Leila’s actual checking question. Try the reachable arrangement and comparable measures rather than discarding her observations."}],bestOptionId:"focus-3-provisional-placement"}},carry:{takeaway:"Compare the same events. Let observations guide a preference without turning them into a verdict.",followUp:{questionId:"focus-3-return",question:"Were your task, settings, urges, and pickups comparable enough to guide the next placement?",observationPrompt:"What happened at the saved opportunity?",adjustmentPrompt:"What one change fits your next opportunity?"}},goDeeper:{sections:[{heading:"Why the headline is unsettled",paragraphs:["Hartanto and colleagues' 2024 synthesis pooled 33 studies, 53 samples, and 166 effects. It found no reliable overall impairment from a smartphone's mere presence: d = -.02, with a 95% confidence interval from -.06 to .01. A working-memory subgroup became nonsignificant after bias correction. The paper gives conflicting participant totals, so this course withholds a definitive total. [F14]","Parry's competing 2024 synthesis reported an adverse working-memory average while other cognitive summaries were null. Its accessible abstract identifies methodological differences and generally poor statistical power; the accessible abstract does not give the exact pooled effect. [F16] These reviews warrant uncertainty, not “phones never matter” or “a nearby phone always drains you.” Both examine presence rather than active checking. A desk can be a workable place for one task and an unhelpful temptation for another. Choose from role requirements and observations rather than guilt about the location alone."]},{heading:"A personal comparison can still be useful",paragraphs:["Ruiz Pardo and Minda’s 2022 preregistered direct replication did not reproduce the original location effect. The accessible primary abstract verifies that result without supplying a participant total or exact p value. A failed replication does not prove exact zero effects for every person, and it does not test active scrolling or alerts. [F13]","Your short trial answers a more practical question: where can you keep the phone while doing this task and preserving needed access? Count urges and pickups as different events, and record both in each session. Keep task, duration, and alert settings similar when feasible. Note unmatched demands rather than pretending life supplied laboratory controls. A new comparison scheduled for tomorrow is planned, not already tried. This one-variable approach is an ODA design choice, not a validated diagnostic test. Stop tallying if it displaces useful work. You can retain a workable preference while remaining unsure why it helped."]}],sourceIds:["F14","F16","F13"]}},{schemaVersion:2,revision:2,id:"focus-4",courseId:"focus",locale:"en",title:"Rereading again? Take a pause you can return from",goal:"Take feasible rest, then return to one useful move in your existing task.",minutes:{learning:6,suggestedAction:3,review:2},direction:{hook:"Rereading the same line again? Your next move can include rest.",reason:{id:"focus-4-reason",label:"What does refusing a pause cost the rest of your day?",kind:"text",maxLength:160,optional:!0,suggestions:["I reread instead of deciding","I am less patient afterward","No observed cost yet","A pause is not currently feasible"]},why:{id:"focus-4-purpose",label:"What would this move make possible in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Short breaks improved average energy and fatigue in a research review, while the overall performance effect was unclear. Rest does not need to make you faster to matter. The review did not identify one best break length or activity.","Keep your task. If fatigue appeared, test rest; otherwise retain your workable plan. Choose a feasible pause and name the first useful move on return. Seated rest is valid. Keep required care access. Observe fatigue and whether you resumed; unchanged feelings are allowed. If you need more rest or support, change the plan instead of forcing the return."],example:{title:"Leila rests and resumes",text:"Leila has corrected budget rows for ten minutes and keeps rereading a note. She names her return move: explain the travel-cost change. She rests seated for two minutes, keeping care calls available, then writes one explanation sentence. She still feels tired. Her record says she paused and resumed, with no claim of faster work."}},move:{invitation:"Keep your return move. Need rest? Edit this seated-rest and report example.",instructions:["Name your actual return output before saving the editable example.","Rest, then try that move if it fits; record both honestly."],prompts:[],suggestions:{action:["Rest seated, then explain one report change","Pause seated, then correct one budget line"],minimum:["Rest and write one report explanation","Rest and correct one budget line"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"In two days",daysFromToday:2}],cue:["After my report-writing block","When I reread without making progress","At my agreed short pause"],place:["Seated at my work desk","In a nearby accessible rest place","Where required calls stay reachable"],minutes:[3,2,5],fallback:["Take needed rest and reschedule return","Use a shorter accessible pause","Request coverage for recovery time"],observation:["Whether I rested and resumed my move","Fatigue before and after the pause","The useful line on return"]},suggested:{action:"Rest seated, then explain one report change",minimum:"Rest and write one report explanation",minutes:3,cueHint:"After my report-writing block",placeHint:"Seated at my work desk",obstacleHint:"The planned return exceeds my available energy",fallbackHint:"Take needed rest and reschedule return",observationHint:"Whether I rested and resumed my move"},accessibleAlternative:"Use seated or nonmovement rest. Need rest alone? Choose Adapt this, then Rest.",stopRule:"Keep care access; if return is unsuitable, choose needed rest, support, or another opening."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do or produce?"},judgment:{primary:{id:"focus-4-decision",scenario:"Leila is drained after report work and has five minutes before a needed call. One explanation sentence remains manageable after seated rest.",question:"Which pause best fits this opening?",options:[{id:"focus-4-messages-break",text:"Use the five minutes to catch up on work messages, then return to whichever task feels most urgent.",feedback:"Messages may be necessary work, but they add new demands and leave the return undefined. This opening allows brief rest and a named report sentence before the call."},{id:"focus-4-rest-return",text:"Rest seated for two minutes, keep required calls available, then write the named explanation sentence if energy permits.",feedback:"This tests recovery while preserving a useful return and the needed call. An unchanged fatigue rating is valid. If energy does not permit the sentence, record that and revise."},{id:"focus-4-finish-before-rest",text:"Finish the explanation before the call so she can take a longer break afterward with nothing left open.",feedback:"Finishing first can be workable when energy permits. Here, Leila is already drained and brief rest fits. Try the pause before the manageable sentence rather than postponing recovery automatically."}],bestOptionId:"focus-4-rest-return"}},carry:{takeaway:"Rest is useful care. A return cue makes the next attempt clear without guaranteeing renewed energy.",followUp:{questionId:"focus-4-return",question:"Did the pause fit your needs, and was the named return move still feasible?",observationPrompt:"What happened at the saved opportunity?",adjustmentPrompt:"What one change fits your next opportunity?"}},goDeeper:{sections:[{heading:"Recovery and output are different outcomes",paragraphs:["Albulescu and colleagues' 2022 review combined 22 samples and 2,335 participants, including students and workers. Breaks up to ten minutes improved vigor on average, d = .36 with a 95% confidence interval from .16 to .55, and fatigue, d = .35 from .19 to .50. Overall performance was uncertain, d = .16 from -.04 to .37. Outcome sample sizes differed. [F02]","The small and varied corpus does not establish an ideal duration, activity, or reliable performance benefit on demanding cognitive tasks. This lesson's two-minute seated pause and one useful line are accessible course choices, not the studied optimal dose. Screen-free rest may suit you; the review does not show that every screen-based leisure activity fails to restore energy. Record what you chose and noticed. Rest can serve patience, recovery, or presence in the life you want, even when output does not change. Do not make it conditional on finishing all work."]},{heading:"A schedule to try, not an interval to obey",paragraphs:["Biwer and colleagues compared fixed study-break schedules with self-chosen breaks in a two-hour student study session. The fixed schedules were 24 minutes of study with six minutes of rest, or 12 with three. There were 110 randomized students and 87 analyzed after missingness and exclusions. Some fatigue and concentration patterns favored fixed breaks, without a significant task-completion difference. The planned longer study was reduced to one session. [F08]","This does not prove a universal interval or long-term learning benefit. Use a cue that fits your role and an accessible form of rest. Name one return action, but change it when health, care, or energy requires more recovery. A timer is optional; an event cue can work as your plan. Fatigue ratings and the exact output-and-return record are ODA adaptations. They help you decide what to test next, without converting an unchanged feeling into failure or a required longer break into lost progress."]}],sourceIds:["F02","F08"]}},{schemaVersion:2,revision:2,id:"focus-5",courseId:"focus",locale:"en",title:"Your real Tuesday needs a workable plan",goal:"Use your actual task records to choose next week's support and attempt one feasible block.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"A beautiful schedule is still a plan. Keep what helped you make actual progress this week.",reason:{id:"focus-5-reason",label:"What will you defer to protect a feasible block?",kind:"text",maxLength:160,optional:!0,suggestions:["Nonurgent group chat","Extra formatting","An optional meeting follow-up","No safe deferral; choose another opening"]},why:{id:"focus-5-purpose",label:"What would this move make possible in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Look back at what you actually did on this task. Check output, required interruptions, and one support. Increasing progress monitoring improved goal attainment on average across experiments. It did not validate this exact routine. Your records guide a decision, not a causal verdict.","Keep supports that were workable. Change one condition your records question, and choose next week's realistic openings. Then do one useful task unit with the current plan. If no attempt exists, call this the first test. A future block stays planned. Neither a timer nor a course finish proves work happened."],example:{title:"Leila redraws the week",text:"Leila reads four report attempts. The chat boundary preserved care access, and she returned after two pauses. Mornings had fewer required work requests. She chooses two short morning openings next week. Today a necessary call leaves only five minutes, so she writes one useful explanation and records the smaller block. Her report still needs checking."}},move:{invitation:"Keep the act and opening. New plan? Edit this report example.",instructions:["Keep action, minimum, cue, and place; change one support only if needed.","Name the actual output and opening before saving this editable example.","Choose next week’s openings around obligations and recovery, then attempt the current move."],prompts:[],suggestions:{action:["Write one report explanation with chat paused","Correct one budget line with calls reachable","Write one proposal sentence after a pause"],minimum:["Write one usable report explanation","Correct one budget line","Write one usable proposal sentence"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"In two days",daysFromToday:2}],cue:["After today’s required morning check-in","After my required check-in","After lunch, before optional email"],place:["At my work desk","At my kitchen table with task tools","Where needed contacts stay reachable"],minutes:[10,2,5],fallback:["Write one report sentence before the call","Leave marker and handle required request","Take needed rest and choose another opening"],observation:["Actual output and one plan adjustment","Which support I kept or changed","Whether my plan fit my obligations"]},suggested:{action:"Write one report explanation with chat paused",minimum:"Write one usable report explanation",minutes:10,cueHint:"After today’s required morning check-in",placeHint:"At my work desk",obstacleHint:"A necessary obligation shortens my block",fallbackHint:"Write one report sentence before the call",observationHint:"Actual output and one plan adjustment"},accessibleAlternative:"Use accessible tools, assistance, or a shorter useful unit; external reminders remain valid.",stopRule:"Preserve required contacts and recovery; seek support for persistent impairment without waiting for course completion."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do or produce?"},judgment:{primary:{id:"focus-5-decision",scenario:"Leila planned ten minutes, but a needed call leaves five. One explanation sentence is feasible and her care access is intact.",question:"What adjustment uses her records well?",options:[{id:"focus-5-wait-full-block",text:"Save the report work for a full ten-minute opening tomorrow and use the remaining minutes for scheduling.",feedback:"Scheduling can protect another opening, but it is preparation. A useful sentence fits now. Attempt it, record the actual shorter block, and preserve the future plan as planned."},{id:"focus-5-extend-evening",text:"Move the full ten-minute block into already-short evening recovery so the original schedule remains complete today.",feedback:"A later block can sometimes fit, but this option sacrifices needed recovery to preserve the original duration. Use the feasible smaller unit instead and review the remaining work."},{id:"focus-5-smaller-output",text:"Write the feasible explanation sentence, record the shorter block, and redraw the next opportunity around actual obligations.",feedback:"This preserves useful output and respects the call and recovery. Record what actually happened rather than claiming ten minutes. Use that evidence to plan another feasible opening."}],bestOptionId:"focus-5-smaller-output"}},carry:{takeaway:"Keep the useful output, needed access, and recovery. Let your records redraw the next block.",followUp:{questionId:"focus-5-return",question:"What did your adjusted block produce?",observationPrompt:"What happened at the saved opportunity?",adjustmentPrompt:"What one change fits your next opportunity?"}},goDeeper:{sections:[{heading:"What your record can support",paragraphs:["Harkin and colleagues' 2016 review pooled 138 randomized studies with 19,951 participants overall. Interventions that increased monitoring improved goal attainment on average, d = .40 with a 95% confidence interval from .32 to .48. Goals and methods varied substantially. Associations with written or public reporting do not prove the superiority of this private focus record. [F03]","Use the record to distinguish a committed block, an actual attempt, its useful output, and a later review. A timer alone measures elapsed time. An unfinished report may still contain real completed lines; an attractive calendar contains no evidence of writing. Keep necessary and optional interruptions distinct. If the apparent best arrangement occurred on a quieter day, treat it as a preference to try again. Choose one change that responds to an observed problem rather than replacing every support at once. That sequence is an ODA design choice, not a tested treatment or causal analysis."]},{heading:"A schedule serves the task and the life",paragraphs:["Cal Newport describes time blocking as a personal scheduling framework, with room to redraw the day and blocks for reactive work. His reports of greater output are practitioner impressions, not measured intervention results. This author account supplies no trial of the routine. [F15] You do not need to schedule every working minute. Keep the cue, safe contact access, useful minimum, and recovery choices that served your week.","Choose a next-week review point and realistic opportunities, then test the next unit. If persistent attention difficulties impair daily life, seek professional assessment without waiting for course completion. That is a safety recommendation, not a finding from the monitoring studies. The Cochrane review concerns structured treatment for diagnosed adult ADHD; it supplies no diagnostic cutoff for this app. [F11] An honest pause or support request can finish learning. Only a reported actual task unit supplies evidence that task work happened."]}],sourceIds:["F03","F15","F11"]}}],H={id:"focus",title:"Busy all day? Give what matters your attention",subtitle:"Five lessons. Protect one useful task, keep needed contacts reachable, and test supports and recovery around real obligations.",description:"Choose a meaningful task and test interruption settings, phone placement, return markers, and rest around your actual life.",scope:"Suggestions for everyday working habits; this is not a diagnosis or treatment for attention disorders. If attention difficulties persist and affect your daily life, talk to a health professional. Do not silence calls you need for emergencies, caregiving or work.",outcome:"A feasible task experiment with useful output records, safe contact access, and a next-week work-and-rest plan.",photo:{id:"1505330622279-bf7d7fc918f4",alt:"A bright, tidy work desk"},lessons:[{id:"focus-1",v2:r[0],photo:{id:"1745474633597-be94033b16d6",alt:"A person working at a laptop, glancing at a phone"},schemaVersion:2,title:"Busy all day? Protect one useful move",minutes:6,goal:"Do a useful unit of your chosen task and leave a clear return marker.",reading:["Choose one task that serves your life, and keep it through this course. In laboratory studies, switching simple tasks slowed the next response and usually increased mistakes. Preparing reduced that cost without reliably removing it. This is not a universal productivity percentage.","For your next small block, produce a useful unit before an optional switch. If a routine interruption needs you, leave a short marker: where you stopped and the first move on return. That marker is a practical adaptation, not proven faster recovery. Skip it when immediate safety or care requires action."],practice:["For the next hour, make a tally mark every time you switch to another task or app.","Sort the switches: how many were your own choice, and how many came from a notification or another person?","Before your next switch, try a short preparation sentence: “Now I am moving on to …”"],reflection:"How did the switches feel to you?",question:"According to this lesson, what can working with interruptions cost you?",options:["It always makes you finish much more slowly.","Interruptions have no cost at all.","Even if your speed holds up, you may feel more stress and pressure."],correct:2,feedback:"In a small simulated-email experiment, interrupted participants used less net task time but reported more stress. Interruption-handling time was subtracted; this was not faster total elapsed work.",takeaway:"Protect useful work and leave a way back. Necessary interruptions still deserve a response.",sources:["F01","F07","F10"],deeper:[{heading:"Switch cost is a bounded finding",paragraphs:["Monsell's 2003 review describes experiments with simple cognitive tasks. Responses immediately after a switch were slower and usually more error-prone. Preparing in advance reduced the cost without reliably eliminating it. The review does not supply a pooled workplace-loss percentage or a universal recovery time. [F01] Use the distinction to choose which switches can wait, rather than declaring every interruption harmful.","Mark and colleagues' small 2008 simulated-email experiment illustrates another limit. Interrupted participants used less net task time while reporting more stress. Interruption-handling time was subtracted, so the finding does not mean faster total elapsed work. Quality measures were limited; it cannot guarantee unchanged real-world work quality. [F07] This lesson's short output-and-marker block is an ODA adaptation. Your task, role, health, and care responsibilities determine what is feasible. Count a useful line or task unit, not a timer running or a tally made while postponing the task."]},{heading:"What the return-plan evidence measured",paragraphs:["Leroy and Glomb's 2018 article reported four studies on interruptions and attention remaining with the original task. A return plan reduced that residue and supported decisions or recall on the interrupting task. The first field study was a survey of professionals, not an intervention experiment. The accessible abstract and university description do not establish a benefit on the original task after return. [F10]","The accessible abstract and university description do not supply a complete published worksheet or laboratory dose. A short note naming your stopping point and next action is therefore a source-informed ODA adaptation. Do not delay an emergency or immediate care need to complete it. At a routine pause, use words, dictation, or your usual accessible reminder. When you resume, check whether it named a usable action. An easier return is an observation, not a controlled test of the mechanism. Record what you produced and what still needs doing, even when the block ended early."]}],example:{title:"Leila leaves a return marker",text:"After the morning check-in, Leila works on the same budget report for ten minutes. She corrects one travel-cost line before opening email. A colleague needs a figure soon. She writes “Check row 40 next,” handles the request, and returns to that row. The report is unfinished; one correction and one return are real."}},{id:"focus-2",v2:r[1],photo:{id:"1526045612212-70caf35c14df",alt:"A person holding a smartphone"},schemaVersion:2,title:"Every ping gets a vote. Choose yours",minutes:6,goal:"Keep needed contacts reachable and attempt your existing task with one fewer optional interruption.",reading:["Keep the same task and check who must reach you. One phone experiment changed alerts and visibility together. Students reported fewer attention-related symptoms in the lower-interruption week. It did not isolate notifications alone or show that the setup treats ADHD.","Use that boundary to design your own test. Preserve required contact channels first. Then change one optional interruption setting for a feasible block, keeping your previous phone placement. The work is the task unit you produce. Silencing an app is setup. Choose a message-check opportunity that fits your care and work responsibilities."],practice:["Look at which apps have sent you notifications in the last hour.","Turn off or silence notifications for at least two apps that can safely wait.","Turn on “Do Not Disturb” for one work session and add exceptions for people who may need you urgently."],reflection:"Which notification was easy to turn off, and which was hard?",question:"Which is the most honest summary of this study’s result?",options:["The lower-interruption setup made a modest self-reported difference.","Notifications cause ADHD.","Turning notifications off solves all attention problems."],correct:0,feedback:"The study changed alerts and visibility together. Self-reported symptom ratings differed modestly; it did not isolate alerts alone or establish treatment or direct productivity gains.",takeaway:"Availability is a choice with responsibilities. Change optional interruptions while keeping needed access.",sources:["F06","F11"],deeper:[{heading:"The experiment changed a bundle",paragraphs:["Kushlev and colleagues' 2016 counterbalanced experiment involved 221 university students. The high-interruption week combined enabled alerts with a phone within sight and reach. The lower-interruption week combined disabled auditory, vibration, and visual alerts with a phone kept out of sight. These changes happened together. Paired symptom comparisons used 190 respondents. [F06]","Average self-reported inattention was 2.38 versus 2.27 on a one-to-four scale, with reported d = .44. Hyperactivity ratings also differed modestly. Participants knew their settings, and this was one short student experiment. It did not isolate an alerts-only effect, establish ADHD causation or treatment, or demonstrate a significant direct productivity improvement. This lesson changes one optional setting while retaining your prior placement. That narrower personal trial is an ODA adaptation, not a reproduction of the week-long protocol. The reason to record output is to find out what actually happened to your chosen task."]},{heading:"A boundary has to fit the role",paragraphs:["Start with the real availability requirement. A care call, on-call channel, or time-bound work tool may need an immediate response. Do not assume that a named exception works without checking the setting. If you cannot confirm access, keep the channel available and adjust a different source of optional interruption. This is the course's safety and feasibility rule, not a promise from the phone study. [F06]","Use an external reminder or a visible next-step note if that makes the block accessible. Check messages afterward only when your role allows the delay. A blocked necessary message is a result that calls for correction, even if output improved. Persistent attention difficulties affecting daily functioning deserve professional assessment; settings are not treatment. The Cochrane review concerns structured cognitive-behavioral interventions for adults with ADHD, not this short routine. [F11] You can seek support now without proving that you failed enough phone experiments first. Keep the task, care, and record honest."]}],example:{title:"Leila chooses availability",text:"Leila keeps her report and ten-minute opening. Her father may need to call, so she checks that his channel stays available. She silences only the nonurgent group chat and keeps the phone where it was. She corrects another budget line. A work request still interrupts her; she records it and leaves a return marker."}},{id:"focus-3",v2:r[2],photo:{id:"1635398235411-2c41ca32ffbc",alt:"A phone lying on a wooden table"},schemaVersion:2,title:"Phone within reach? Make checking a choice",minutes:6,goal:"Test one workable phone placement during your task and record urges and pickups separately.",reading:["A phone nearby and a phone you keep checking are different questions. Research reviews disagree about some memory tasks; one found no reliable overall impairment from mere presence. Neither conclusion settles what happens when you use the phone.","Keep your task, duration, and alerts similar across attempts. No record yet? Make this your first placement test. Change placement; preserve required access. Note both urges and actual pickups in this session and any comparison. Different workloads or fatigue limit the comparison. Use the record to choose a workable arrangement, not to prove your phone caused a result."],practice:["Notice where you usually keep your phone while you work and how many times you pick it up.","For one work session, put your phone somewhere you cannot reach, and note each time you feel the urge to pick it up.","On another day, try keeping the phone on the desk but silenced; compare the two days using your own observations."],reflection:"What is really hard for you: the phone being there, or the urge to pick it up?",question:"What does current evidence say about a phone simply sitting on the desk?",options:["It definitely drains your mind.","One review found no reliable overall impairment; memory summaries differ, and active use is separate.","Putting your phone in another room is pointless."],correct:1,feedback:"Mere-presence evidence is mixed across memory summaries. One synthesis found no reliable overall impairment. This does not settle active checking or individual preferences.",takeaway:"Compare the same events. Let observations guide a preference without turning them into a verdict.",sources:["F14","F16","F13"],deeper:[{heading:"Why the headline is unsettled",paragraphs:["Hartanto and colleagues' 2024 synthesis pooled 33 studies, 53 samples, and 166 effects. It found no reliable overall impairment from a smartphone's mere presence: d = -.02, with a 95% confidence interval from -.06 to .01. A working-memory subgroup became nonsignificant after bias correction. The paper gives conflicting participant totals, so this course withholds a definitive total. [F14]","Parry's competing 2024 synthesis reported an adverse working-memory average while other cognitive summaries were null. Its accessible abstract identifies methodological differences and generally poor statistical power; the accessible abstract does not give the exact pooled effect. [F16] These reviews warrant uncertainty, not “phones never matter” or “a nearby phone always drains you.” Both examine presence rather than active checking. A desk can be a workable place for one task and an unhelpful temptation for another. Choose from role requirements and observations rather than guilt about the location alone."]},{heading:"A personal comparison can still be useful",paragraphs:["Ruiz Pardo and Minda’s 2022 preregistered direct replication did not reproduce the original location effect. The accessible primary abstract verifies that result without supplying a participant total or exact p value. A failed replication does not prove exact zero effects for every person, and it does not test active scrolling or alerts. [F13]","Your short trial answers a more practical question: where can you keep the phone while doing this task and preserving needed access? Count urges and pickups as different events, and record both in each session. Keep task, duration, and alert settings similar when feasible. Note unmatched demands rather than pretending life supplied laboratory controls. A new comparison scheduled for tomorrow is planned, not already tried. This one-variable approach is an ODA design choice, not a validated diagnostic test. Stop tallying if it displaces useful work. You can retain a workable preference while remaining unsure why it helped."]}],example:{title:"Leila compares matching observations",text:"Leila keeps her report, ten-minute block, and safe alert settings. She moves the phone from the desk to an accessible shelf. She records four urges, one pickup, and two corrected lines. Yesterday she recorded five urges and three pickups. Today was quieter, so she treats the shelf as worth trying again, not proven better."}},{id:"focus-4",v2:r[3],photo:{id:"1556833232-52da3e4bd5d8",alt:"A woman walking along a path"},schemaVersion:2,title:"Rereading again? Take a pause you can return from",minutes:6,goal:"Take feasible rest, then return to one useful move in your existing task.",reading:["Short breaks improved average energy and fatigue in a research review, while the overall performance effect was unclear. Rest does not need to make you faster to matter. The review did not identify one best break length or activity.","Keep your task. If fatigue appeared, test rest; otherwise retain your workable plan. Choose a feasible pause and name the first useful move on return. Seated rest is valid. Keep required care access. Observe fatigue and whether you resumed; unchanged feelings are allowed. If you need more rest or support, change the plan instead of forcing the return."],practice:["Put a five- to ten-minute break at the end of one work session.","For the break, choose something that takes you away from the screen: getting up for a glass of water, looking out of the window or a short walk.","Before and after the break, rate how tired you feel from 1 to 5 and write it down."],reflection:"What did your break change for you, and what did it not change?",question:"Which statement about short breaks fits the evidence better?",options:["They definitely improve performance in every kind of work.","Taking a break is just a waste of time.","Promising for vigor and fatigue; the effect on performance is unclear."],correct:2,feedback:"The evidence is more consistent for feeling better than for performance. You can think of a break not as a tool for speeding up your work, but as part of looking after yourself.",takeaway:"Rest is useful care. A return cue makes the next attempt clear without guaranteeing renewed energy.",sources:["F02","F08"],deeper:[{heading:"Recovery and output are different outcomes",paragraphs:["Albulescu and colleagues' 2022 review combined 22 samples and 2,335 participants, including students and workers. Breaks up to ten minutes improved vigor on average, d = .36 with a 95% confidence interval from .16 to .55, and fatigue, d = .35 from .19 to .50. Overall performance was uncertain, d = .16 from -.04 to .37. Outcome sample sizes differed. [F02]","The small and varied corpus does not establish an ideal duration, activity, or reliable performance benefit on demanding cognitive tasks. This lesson's two-minute seated pause and one useful line are accessible course choices, not the studied optimal dose. Screen-free rest may suit you; the review does not show that every screen-based leisure activity fails to restore energy. Record what you chose and noticed. Rest can serve patience, recovery, or presence in the life you want, even when output does not change. Do not make it conditional on finishing all work."]},{heading:"A schedule to try, not an interval to obey",paragraphs:["Biwer and colleagues compared fixed study-break schedules with self-chosen breaks in a two-hour student study session. The fixed schedules were 24 minutes of study with six minutes of rest, or 12 with three. There were 110 randomized students and 87 analyzed after missingness and exclusions. Some fatigue and concentration patterns favored fixed breaks, without a significant task-completion difference. The planned longer study was reduced to one session. [F08]","This does not prove a universal interval or long-term learning benefit. Use a cue that fits your role and an accessible form of rest. Name one return action, but change it when health, care, or energy requires more recovery. A timer is optional; an event cue can work as your plan. Fatigue ratings and the exact output-and-return record are ODA adaptations. They help you decide what to test next, without converting an unchanged feeling into failure or a required longer break into lost progress."]}],example:{title:"Leila rests and resumes",text:"Leila has corrected budget rows for ten minutes and keeps rereading a note. She names her return move: explain the travel-cost change. She rests seated for two minutes, keeping care calls available, then writes one explanation sentence. She still feels tired. Her record says she paused and resumed, with no claim of faster work."}},{id:"focus-5",v2:r[4],photo:{id:"1632772998001-cc9bf6f7c852",alt:"A planner with two pens lying on it"},schemaVersion:2,title:"Your real Tuesday needs a workable plan",minutes:6,goal:"Use your actual task records to choose next week's support and attempt one feasible block.",reading:["Look back at what you actually did on this task. Check output, required interruptions, and one support. Increasing progress monitoring improved goal attainment on average across experiments. It did not validate this exact routine. Your records guide a decision, not a causal verdict.","Keep supports that were workable. Change one condition your records question, and choose next week's realistic openings. Then do one useful task unit with the current plan. If no attempt exists, call this the first test. A future block stays planned. Neither a timer nor a course finish proves work happened."],practice:["Choose one task for tomorrow and a block length that suits you; starting short is fine.","Complete the sentence “If my attention drifts, then I will …” and set up your notifications before the block starts.","After the block and the break, briefly note what worked and what you would change."],reflection:"Which part of your focus plan supports you the most?",question:"What is the most honest way to approach time blocking?",options:["It is the best method for everyone, and it is proven.","A reasonable personal experiment; you look at the result and adjust.","If a block falls apart, the whole day is wasted."],correct:1,feedback:"Time blocking is a scheduling option to test. The author account supplies no intervention trial of this specific routine. Future planning is not an attempted block, and persistent impairment deserves professional support.",takeaway:"Keep the useful output, needed access, and recovery. Let your records redraw the next block.",sources:["F03","F15","F11"],deeper:[{heading:"What your record can support",paragraphs:["Harkin and colleagues' 2016 review pooled 138 randomized studies with 19,951 participants overall. Interventions that increased monitoring improved goal attainment on average, d = .40 with a 95% confidence interval from .32 to .48. Goals and methods varied substantially. Associations with written or public reporting do not prove the superiority of this private focus record. [F03]","Use the record to distinguish a committed block, an actual attempt, its useful output, and a later review. A timer alone measures elapsed time. An unfinished report may still contain real completed lines; an attractive calendar contains no evidence of writing. Keep necessary and optional interruptions distinct. If the apparent best arrangement occurred on a quieter day, treat it as a preference to try again. Choose one change that responds to an observed problem rather than replacing every support at once. That sequence is an ODA design choice, not a tested treatment or causal analysis."]},{heading:"A schedule serves the task and the life",paragraphs:["Cal Newport describes time blocking as a personal scheduling framework, with room to redraw the day and blocks for reactive work. His reports of greater output are practitioner impressions, not measured intervention results. This author account supplies no trial of the routine. [F15] You do not need to schedule every working minute. Keep the cue, safe contact access, useful minimum, and recovery choices that served your week.","Choose a next-week review point and realistic opportunities, then test the next unit. If persistent attention difficulties impair daily life, seek professional assessment without waiting for course completion. That is a safety recommendation, not a finding from the monitoring studies. The Cochrane review concerns structured treatment for diagnosed adult ADHD; it supplies no diagnostic cutoff for this app. [F11] An honest pause or support request can finish learning. Only a reported actual task unit supplies evidence that task work happened."]}],example:{title:"Leila redraws the week",text:"Leila reads four report attempts. The chat boundary preserved care access, and she returned after two pauses. Mornings had fewer required work requests. She chooses two short morning openings next week. Today a necessary call leaves only five minutes, so she writes one useful explanation and records the smaller block. Her report still needs checking."}}]},Y=Object.freeze(Object.defineProperty({__proto__:null,COURSE:H,FOCUS_LESSONS_V2:r,SOURCES:W},Symbol.toStringTag,{value:"Module"})),F=[{id:"C01",title:"WHO · Stress: questions and answers",url:"https://www.who.int/news-room/questions-and-answers/item/stress",type:"guidance",finding:"Describes stress as worry or mental tension in difficult situations. Suggests routine, rest, suitable activity, trusted connections, and managing news exposure.",limitation:"Public guidance, not a measured ODA effect. Suggestions need individual fit; they do not remove every stressor or replace care."},{id:"C02",title:"NHS · Get help with stress",url:"https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/feelings-and-symptoms/stress/",type:"guidance",finding:"Stress can accompany physical, cognitive, emotional, and behavioral signs. Seek professional help when coping is difficult or self-help is not working.",limitation:"Signs such as tension, headaches, or poor concentration do not establish their cause. New or concerning symptoms may need assessment; naming is not diagnosis."},{id:"C03",title:"NHS Every Mind Matters · Anxiety",url:"https://www.nhs.uk/every-mind-matters/mental-health-issues/anxiety/",type:"guidance",finding:"Suggests gradual facing of safe feared situations, recording triggers, and care when anxiety affects daily life. Breathlessness may have another cause.",limitation:"Public guidance does not establish every feared situation as safe or validate ODA as exposure treatment. Leaving abuse or genuine danger is protective."},{id:"C04",title:"NHS · Panic disorder",url:"https://www.nhs.uk/mental-health/conditions/panic-disorder/",type:"guidance",finding:"Repeated panic attacks need professional assessment. Similar physical symptoms can occur in other conditions; treatment can include CBT and prescribed medication.",limitation:"New chest pain, faintness, or breathlessness is not automatically harmless panic. Breathing alone is not panic-disorder treatment; medication decisions belong with a prescriber."},{id:"C05",title:"NHS · 2026 · Breathing exercises for stress",url:"https://www.nhs.uk/mental-health/self-help/guides-tools-and-activities/breathing-exercises-for-stress/",type:"guidance",finding:"Offers supported, comfortable, gentle breathing without force, with regular practice. Counting is optional and should not cause strain.",limitation:"Public guidance gives no isolated trial effect, optimal ratio, or guarantee. Gentle breathing differs from the tested double-inhale protocol; shorter ODA pauses are adaptations."},{id:"C06",title:"NHS · 10 stressbusters",url:"https://www.nhs.uk/mental-health/self-help/guides-tools-and-activities/tips-to-reduce-stress/",type:"guidance",finding:"Suitable activity and trusted connection are coping options. Reduced emotional intensity does not mean the stressful circumstance has disappeared.",limitation:"Guidance, not standalone numerical evidence. Helping others may not fit an overextended person; listing contacts without asking is not evidence of support received."},{id:"C07",title:"Singh et al. · 2023 · Physical activity umbrella review",url:"https://www.newswise.com/pdf_docs/167719499939215_Singh%20et%20al%202023.pdf",type:"research",finding:"97 reviews covered 1,039 unique component trials. Depression median SMD was −0.43 (IQR −0.66 to −0.27); anxiety −0.42 (−0.66 to −0.26). Distress SMD −0.60 (95% CI −0.78 to −0.42) came from one six-trial review.",limitation:"77 reviews were critically low quality. Review-reported participant counts overlap. Medians and IQRs are not pooled effects and confidence intervals. Intensity/duration subgroup associations do not prescribe a personal dose or predict one walk."},{id:"C08",title:"Fincham et al. · 2023 · Breathwork trial meta-analysis",url:"https://doi.org/10.1038/s41598-022-27247-y",type:"research",finding:"The primary stress analysis combined 12 randomized trials with 785 adults: Hedges’ g −0.35 (95% CI −0.55 to −0.14). Techniques and populations varied.",limitation:"Moderate bias risk and limited follow-up constrain confidence. Subgroup results do not establish slow-breathing superiority, an optimal protocol, treatment equivalence, or equal safety across rapid and slow techniques."},{id:"C09",title:"Webb, Miles & Sheeran · 2012 · Emotion regulation meta-analysis",url:"https://pubmed.ncbi.nlm.nih.gov/22582737/",type:"research",finding:"306 experimental comparisons found perspective change d+ 0.45, stimulus reappraisal 0.36, and thought suppression −0.12 on average.",limitation:"Abstract access; mainly induced short-term laboratory emotions. Thought and expression suppression differ. This does not show suppression always fails, a comforting interpretation is true, or lasting benefit from ODA prompts."},{id:"C10",title:"NHS Every Mind Matters · Reframing unhelpful thoughts",url:"https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/reframing-unhelpful-thoughts/",type:"guidance",finding:"Offers a structure of noticing a thought, checking evidence, and considering a balanced alternative. Real difficulties can need problem solving, acceptance, or support.",limitation:"Guidance, not a trial of ODA’s abbreviated worksheet. Balance can include uncertainty; positive interpretations need evidence and should not minimize mistreatment."},{id:"C11",title:"Balban et al. · 2023 · Structured respiration trial",url:"https://doi.org/10.1016/j.xcrm.2022.100895",type:"research",finding:"108 adults were randomized to five daily minutes of breathing or mindfulness for 28 days. Combined breathing positive-affect change averaged 1.91 points versus 1.22; cyclic sighing favored mindfulness in the model. Anxiety improved without significant group differences.",limitation:"Small groups, medical/psychiatric exclusions, retrospective registration, and no verified between-group confidence interval. Not evidence for two breaths, a universal technique ranking, or a proven causal mechanism. Significant sleep/HRV improvement was not established; durable anxiety benefit from this ODA pause is untested."},{id:"C13",title:"Torre & Lieberman · 2018 · Affect labeling review",url:"https://journals.sagepub.com/doi/abs/10.1177/1754073917742706",type:"research",finding:"Narrative review discusses how putting feelings into words relates to several emotion-response measures. Naming is a plausible experiment.",limitation:"Abstract and references accessed. No pooled N or efficacy estimate verified. One word does not guarantee subjective relief or solve a stressor; the ODA situation-plus-label exercise is an adaptation."},{id:"C14",title:"Kross et al. · 2014 · Distanced self-talk",url:"https://doi.org/10.1037/a0035173",type:"research",finding:"Seven studies involved 585 participants. In one structured social-interaction study, non-first-person reflection improved observer-rated performance without differentially reducing anxiety beforehand.",limitation:"Laboratory social stress, not anxiety-disorder treatment or proof of instant calm. Exact independent replication and preregistration were not verified. ODA’s workplace action additions were not tested."},{id:"C17",title:"Edwards & Loprinzi · 2018 · Brief walking and meditation trial",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC6064756/",type:"research",finding:"66 young adults were randomized to ten minutes of treadmill walking, guided meditation, or quiet sitting. Fatigue and composite-mood interactions involved all three groups; walking’s within-group composite change had p=.10.",limitation:"Small acute trial; no verified effect confidence intervals or exact independent replication. Results do not clearly establish walking’s overall mood improvement or benefit for any accessible movement alternative."},{id:"C12",title:"Zaccaro et al. · 2018 · Slow-breathing physiology review",url:"https://www.frontiersin.org/journals/human-neuroscience/articles/10.3389/fnhum.2018.00353/full",type:"research",finding:"Qualitative synthesis of 15 healthy-participant studies associated slow breathing with physiological and psychological measures. There was no pooled effect estimate.",limitation:"Small heterogeneous within-person or pre/post studies, not randomized longitudinal evidence. Physiological associations do not prove a vagal mental-health mechanism, an optimal rate, or treatment of anxiety disorders."},{id:"cyclic-sighing",title:"Balban et al. · 2023 · Structured respiration trial",url:"https://doi.org/10.1016/j.xcrm.2022.100895",type:"research",finding:"108 adults were randomized to five daily minutes of breathing or mindfulness for 28 days. Combined breathing positive-affect change averaged 1.91 points versus 1.22; cyclic sighing favored mindfulness in the model. Anxiety improved without significant group differences.",limitation:"Small groups, medical/psychiatric exclusions, retrospective registration, and no verified between-group confidence interval. Not evidence for two breaths, a universal technique ranking, or a proven causal mechanism. Significant sleep/HRV improvement was not established; durable anxiety benefit from this ODA pause is untested."},{id:"slow-breathing",title:"Zaccaro et al. · 2018 · Slow-breathing physiology review",url:"https://www.frontiersin.org/journals/human-neuroscience/articles/10.3389/fnhum.2018.00353/full",type:"research",finding:"Qualitative synthesis of 15 healthy-participant studies associated slow breathing with physiological and psychological measures. There was no pooled effect estimate.",limitation:"Small heterogeneous within-person or pre/post studies, not randomized longitudinal evidence. Physiological associations do not prove a vagal mental-health mechanism, an optimal rate, or treatment of anxiety disorders."},{id:"activity-mood",title:"Singh et al. · 2023 · Physical activity umbrella review",url:"https://www.newswise.com/pdf_docs/167719499939215_Singh%20et%20al%202023.pdf",type:"research",finding:"97 reviews covered 1,039 unique component trials. Depression median SMD was −0.43 (IQR −0.66 to −0.27); anxiety −0.42 (−0.66 to −0.26). Distress SMD −0.60 (95% CI −0.78 to −0.42) came from one six-trial review.",limitation:"77 reviews were critically low quality. Review-reported participant counts overlap. Medians and IQRs are not pooled effects and confidence intervals. Intensity/duration subgroup associations do not prescribe a personal dose or predict one walk."},{id:"emotion-regulation",title:"Webb, Miles & Sheeran · 2012 · Emotion regulation meta-analysis",url:"https://pubmed.ncbi.nlm.nih.gov/22582737/",type:"research",finding:"306 experimental comparisons found perspective change d+ 0.45, stimulus reappraisal 0.36, and thought suppression −0.12 on average.",limitation:"Abstract access; mainly induced short-term laboratory emotions. Thought and expression suppression differ. This does not show suppression always fails, a comforting interpretation is true, or lasting benefit from ODA prompts."},{id:"affect-labeling",title:"Torre & Lieberman · 2018 · Affect labeling review",url:"https://journals.sagepub.com/doi/abs/10.1177/1754073917742706",type:"research",finding:"Narrative review discusses how putting feelings into words relates to several emotion-response measures. Naming is a plausible experiment.",limitation:"Abstract and references accessed. No pooled N or efficacy estimate verified. One word does not guarantee subjective relief or solve a stressor; the ODA situation-plus-label exercise is an adaptation."},{id:"who-stress",title:"WHO · Stress: questions and answers",url:"https://www.who.int/news-room/questions-and-answers/item/stress",type:"guidance",finding:"Describes stress as worry or mental tension in difficult situations. Suggests routine, rest, suitable activity, trusted connections, and managing news exposure.",limitation:"Public guidance, not a measured ODA effect. Suggestions need individual fit; they do not remove every stressor or replace care."},{id:"nhs-stress",title:"NHS · Get help with stress",url:"https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/feelings-and-symptoms/stress/",type:"guidance",finding:"Stress can accompany physical, cognitive, emotional, and behavioral signs. Seek professional help when coping is difficult or self-help is not working.",limitation:"Signs such as tension, headaches, or poor concentration do not establish their cause. New or concerning symptoms may need assessment; naming is not diagnosis."},{id:"nhs-stress-tips",title:"NHS · 10 stressbusters",url:"https://www.nhs.uk/mental-health/self-help/guides-tools-and-activities/tips-to-reduce-stress/",type:"guidance",finding:"Suitable activity and trusted connection are coping options. Reduced emotional intensity does not mean the stressful circumstance has disappeared.",limitation:"Guidance, not standalone numerical evidence. Helping others may not fit an overextended person; listing contacts without asking is not evidence of support received."},{id:"calm-nhs-anxiety",title:"NHS Every Mind Matters · Anxiety",url:"https://www.nhs.uk/every-mind-matters/mental-health-issues/anxiety/",type:"guidance",finding:"Suggests gradual facing of safe feared situations, recording triggers, and care when anxiety affects daily life. Breathlessness may have another cause.",limitation:"Public guidance does not establish every feared situation as safe or validate ODA as exposure treatment. Leaving abuse or genuine danger is protective."}],y=[{schemaVersion:2,revision:2,id:"calm-1",courseId:"calm",locale:"en",title:"Catch the reply you might regret",goal:"Name one familiar stress moment and make one safe useful response before sending or reacting.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Your jaw is tight and the reply is ready. Choose the next move before you press send.",reason:{id:"calm-1-reason",label:"What does your usual stress response cost you?",kind:"text",maxLength:160,optional:!0,suggestions:["Send replies I regret","Leave priorities unclear","Carry work tension into home","No previous occasion"]},why:{id:"calm-1-why",label:"What would this move protect in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Tension, headaches, and poor concentration can accompany stress, but they do not identify the cause. Treat a familiar signal as a cue to choose a response, rather than a diagnosis. New or worrying physical symptoms need assessment.","Name a feeling and the situation: “Worried about this deadline.” Naming is a reasonable experiment, not a guarantee of relief. Then do something useful: postpone an impulsive reply, ask which task takes priority, set a safe boundary, or seek support. Keep this cue and response as your experiment through the course. Feeling calmer is not the required result."],example:{title:"Priya changes the reply",text:"Priya sees another deadline change at her desk. Her familiar jaw tension appears and she wants to send a sharp reply. She names “worried about the workload,” then asks which task should take priority. Her manager has not replied by lunch. Priya records her question and the silence. She is still worried."}},move:{invitation:"Keep your response; edit the deadline example.",instructions:["Name the moment without diagnosing its cause.","Use one safe question, pause, boundary, or support request."],prompts:[],suggestions:{action:["Ask which of two deadlines comes first","Delay one impulsive reply","Send workload facts without a sharp comment"],minimum:["Send one question naming both deadlines","Keep one reply unsent for a minute","Send one factual sentence about the workload"],cue:["When a deadline-change email arrives","When I notice my familiar signal","Before I send a sharp reply"],place:["At my desk, in the email thread","A private safe pause space","My accessible communication space"],minutes:[2,1,5],fallback:["Leave draft unsent; send only the priority question","Choose a protective boundary","Ask an available person for support"],observation:["Question sent; reply or no reply","Whether the impulse became a send","Which signal and response occurred"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Ask which of two deadlines comes first",minimum:"Send one question naming both deadlines",minutes:2,cueHint:"When a deadline-change email arrives",placeHint:"At my desk, in the email thread",obstacleHint:"I start composing a sharp reply",fallbackHint:"Leave draft unsent; send only the priority question",observationHint:"Question sent; reply or no reply"},stopRule:"New or worrying symptoms need assessment. Use protection or support if the situation is unsafe.",accessibleAlternative:"Use outward cues, typing, or supported communication. For a support request, choose Adapt and Support; name its own minimum."},result:{question:"Did you use the response you chose?",observationPrompt:"What did you do after the signal, and what actually followed?"},judgment:{primary:{id:"calm-1-decision",scenario:"Priya receives a deadline change. She is safe, but wants to send a sharp reply before clarifying priorities.",question:"Which response uses the signal well?",options:[{id:"calm-1-full-explanation",text:"Send a detailed explanation of the workload immediately, then take a break before reading the reply.",feedback:"Explaining the workload can be useful, but an impulsive detailed message may miss the priority decision Priya needs. She can first ask one clear question without claiming the deadline is settled."},{id:"calm-1-name-only",text:"Name the worry privately and leave the workload unchanged until she feels ready to discuss it.",feedback:"Naming describes the moment but does not decide priorities or make a request. Priya can remain worried while using one safe question that addresses the actual work problem."},{id:"calm-1-priority-question",text:"Name the deadline worry, hold the sharp reply, and ask which task should take priority.",feedback:"This connects noticing to a useful act. The manager may not answer promptly, so Priya records what she asked and chooses a fallback without treating silence as agreement."}],bestOptionId:"calm-1-priority-question"}},carry:{takeaway:"Name the moment, then choose a response you can actually observe.",followUp:{questionId:"calm-1-return",question:"Did the familiar signal lead to your chosen response?",observationPrompt:"What happened when your chosen cue arrived?",adjustmentPrompt:"What should you repeat, change, or get help with?"}},goDeeper:{sections:[{heading:"Signals are useful without becoming diagnoses",paragraphs:["NHS guidance lists physical, cognitive, emotional, and behavioral signs that can accompany stress [C02]. A familiar tight jaw, irritability, or scattered attention can be useful information to notice. Those signs still do not establish stress as their cause. They can have other explanations, and new or concerning symptoms should not be brushed aside as ordinary tension. Naming a familiar moment is a cue for a choice, not a diagnosis.","This lesson asks you to choose one recognizable cue, not search your body until you find a problem. You can use an outward cue, such as opening a difficult email, with your eyes open and your usual communication method. The cue creates an opportunity to choose a safe question, pause, boundary, or support request. That is an ODA planning adaptation. It does not show that everyone has a stable symptom pattern or that noticing alone changes health."]},{heading:"A label is not the whole response",paragraphs:["Torre and Lieberman’s narrative review discusses affect labeling, putting feelings into words, across several emotion-response measures [C13]. The accessed abstract and references supplied no pooled participant count or numerical efficacy estimate. Subjective relief is not guaranteed. A one-word label followed by a situation is an ODA adaptation, rather than a precisely reproduced treatment or brain-reset procedure.","NHS thought-checking guidance supports separating a reaction from an evidence-based next choice [C10]. “I am worried about the workload” can coexist with a real workload problem. You might need clearer priorities, practical help, or protection rather than a nicer story. The continuing experiment records what followed the cue, including a question without a reply. Later lessons offer a tool only when an observed barrier makes it relevant. You can choose support immediately, without waiting to master all the tools."]}],sourceIds:["C02","C13","C10"]}},{schemaVersion:2,revision:2,id:"calm-2",courseId:"calm",locale:"en",title:"You do not have to perform calm",goal:"Try a comfortable seated pause, then return to your chosen safe response.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Waiting to feel calm can delay the conversation again. Choose a comfortable pause that leaves you free to act.",reason:{id:"calm-2-reason",label:"What useful response are you waiting to feel ready for?",kind:"text",maxLength:160,optional:!0,suggestions:["Asking which deadline comes first","Saying I cannot cover another shift","Requesting help arranging care","No response I am delaying"]},why:{id:"calm-2-why",label:"What would this move protect in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A study of 108 adults tested five minutes daily for 28 days, not two breaths. Anxiety improved in the breathing and mindfulness groups without a significant difference between them. That does not identify one quick breathing method as the answer for everyone.","If a pause might help your saved response, sit safely with eyes open. Gentle unforced breathing is optional. You can instead notice an ordinary object while breathing normally. Stop if unwell. Then choose your safe next move; calm is not an entry requirement. A shorter pause does not inherit the study’s effect."],example:{title:"Priya stops the exercise",text:"Priya tries gentle breathing in a chair at home before asking about tomorrow’s workload. She feels light-headed, stops immediately, and breathes normally while staying seated. Once well, she sends the priority question. She records the stop and the question separately. The pause was not comfortable enough to repeat, so she chooses an outward anchor next time."}},move:{invitation:"Keep your response; edit the deadline example.",instructions:["Sit safely; try ordinary breathing with an outward anchor or gentle unforced breathing.","Stop if unwell. When suitable, use your chosen safe response."],prompts:[],suggestions:{action:["Pause; ask which deadline comes first","Notice object; ask which deadline comes first","Send the priority question without a pause"],minimum:["Send one question naming both deadlines","Send one clear boundary sentence","Send the deadline priority question without breathing"],cue:["Before replying to a deadline change","When a deadline-change email arrives","Before replying about an extra shift"],place:["Supported chair at home, with my phone","At my desk, in the email thread","A seated space with eyes open"],minutes:[2,1,5],fallback:["End pause; send the deadline priority question","Skip breathing; request help with the workload","Stop; stay seated until symptoms pass"],observation:["Pause comfort; question and reply or silence","Whether I used the chosen response","Any discomfort and actual action"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Pause; ask which deadline comes first",minimum:"Send one question naming both deadlines",minutes:2,cueHint:"Before replying to a deadline change",placeHint:"Supported chair at home, with my phone",obstacleHint:"I keep checking for calm after a comfortable pause",fallbackHint:"End pause; send the deadline priority question",observationHint:"Pause comfort; question and reply or silence"},stopRule:"Stop if dizzy or unwell; sit and breathe normally. New or concerning symptoms need assessment; severe chest pain or breathlessness needs urgent care.",accessibleAlternative:"Eyes open and outward anchor are valid. No breath holds, forced breathing, or driving while symptomatic."},result:{question:"Did you make your chosen response safely?",observationPrompt:"What pause or stop happened, and did your next response happen?"},judgment:{primary:{id:"calm-2-decision",scenario:"Priya feels light-headed during breathing at home. She wants to finish before sending her prepared question.",question:"What fits the stop rule?",options:[{id:"calm-2-restart-later",text:"Pause until the sensation passes, then restart the planned exercise before sending the question.",feedback:"Restarting treats the planned dose as an obligation despite discomfort. Priya should stop the exercise, use ordinary breathing safely, and assess symptoms rather than earn permission to ask."},{id:"calm-2-stop-normal",text:"Stop, breathe normally while safely seated, and seek assessment if symptoms persist or are concerning.",feedback:"Safety comes before completing an exercise. Priya can choose an outward anchor or skip practice later; new or concerning symptoms should not be assumed to be merely stress."},{id:"calm-2-gentler-finish",text:"Reduce the effort and finish with softer breaths, then decide whether to use a different method tomorrow.",feedback:"Softer breathing can sound like an adaptation, but continuing after light-headedness contradicts the stop rule. Stop now, remain safely seated, and use ordinary breathing instead of finishing."}],bestOptionId:"calm-2-stop-normal"}},carry:{takeaway:"A useful tool respects your limits and leaves the next response yours to choose.",followUp:{questionId:"calm-2-return",question:"Was the pause comfortable, and did it support or delay your chosen response?",observationPrompt:"What happened when your chosen cue arrived?",adjustmentPrompt:"What should you repeat, change, or get help with?"}},goDeeper:{sections:[{heading:"The trial does not establish a quick reset",paragraphs:["Balban and colleagues randomized 108 adults into small groups for five daily minutes over 28 days [C11]. Combined breathing groups had a mean daily positive-affect change of 1.91 points versus 1.22 for mindfulness. Cyclic sighing favored mindfulness in a statistical model. Those combined raw means do not identify a cyclic-sighing-only mean or prove a universal ranking. Anxiety improved without a significant between-group difference.","The exploratory trial had medical and psychiatric exclusions and was registered retrospectively. It did not establish significant improvements in sleep or heart-rate variability. Nor did it prove a vagal mechanism or a benefit from two breaths. These results do not establish durable anxiety benefit from this shorter pause. This lesson chooses a comfortable voluntary pause rather than prescribing the study’s double-inhale routine. That shorter adaptation has not been tested as equivalent to the original protocol."]},{heading:"Comfort is part of the choice",paragraphs:["NHS breathing guidance emphasizes supported comfort and gentle breaths without force [C05]. Counting is optional; a precise inhale-to-exhale ratio is not required. This public instruction is practical guidance, not an isolated randomized dose. Fuller, faster, or more effortful breathing is not an instruction to pursue here. Keeping eyes open, breathing normally, and noticing a familiar object are available alternatives.","NHS panic information cautions that similar physical sensations can occur in other conditions [C04]. Stop an exercise if dizzy or unwell and remain safely seated with normal breathing. Do not drive while symptomatic. Persistent or concerning symptoms need assessment; severe or urgent symptoms need local emergency care. Recurrent panic or impairment also deserves professional help. Your record can show a safe stop, an uncomfortable practice, and a later priority question. Those are distinct facts, not a failed demand to feel calm."]}],sourceIds:["C04","C05","C11"]}},{schemaVersion:2,revision:2,id:"calm-3",courseId:"calm",locale:"en",title:"A break does not need a workout",goal:"Use suitable brief movement only if it helps your continuing cue-and-response experiment fit your day.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"The full workout cannot happen today. Is a smaller break useful before the response you still need to make?",reason:{id:"calm-3-reason",label:"What did your last skipped break cost? No recent occasion is valid.",kind:"text",maxLength:160,optional:!0,suggestions:["Kept rushing through replies","Carried tension into the next task","No recent skipped break"]},why:{id:"calm-3-why",label:"What would this move protect in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Exercise programs can reduce distress on average, but their results do not predict one short walk. In a small ten-minute trial, walking’s overall mood change was not statistically clear. A useful break does not need to produce a better mood to count as an attempt.","If movement fits before your saved response, try a comfortable accessible version. Keep the cue, then return to that response. Seated movement or a nonmovement pause can fit your needs, without inheriting the walking study’s effect. Record the version and actual duration. Keep your original move if it already works."],example:{title:"Priya keeps the small version",text:"Priya planned a short walk before her afternoon priority check. Rain and a delivery leave her only two minutes. She uses comfortable seated movement instead, then sends her prepared question. Her tension feels unchanged. She records the version, duration, and sent question. Tomorrow she can repeat that workable arrangement without adding minutes as a debt."}},move:{invitation:"Keep your response; edit the seated-break example.",instructions:["Add movement only when it addresses a barrier in your saved experiment.","For a first plan, try one seated minute before sending the prepared priority question.","If movement is unsuitable, edit the action and minimum to the question alone."],prompts:[],suggestions:{action:["Move seated; ask which deadline comes first","Walk briefly; send the priority question","Send the priority question without movement"],minimum:["One seated minute; send the priority question","One walking minute; send the priority question","Send one question naming both deadlines"],cue:["After lunch, before the afternoon priority check","After my usual lunch break","When a deadline-change email arrives"],place:["Supported chair at my desk","My supported chair","A familiar safe walking route"],minutes:[2,5,10],fallback:["Skip movement; send the deadline priority question","Keep the response; skip unsuitable movement","Ask for suitable movement guidance"],observation:["Actual movement minutes; question and reply or silence","Any discomfort during the break","Unchanged feelings are valid observations"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Move seated; ask which deadline comes first",minimum:"One seated minute; send the priority question",minutes:2,cueHint:"After lunch, before the afternoon priority check",placeHint:"Supported chair at my desk",obstacleHint:"Pain, access, or time makes movement unsuitable",fallbackHint:"Skip movement; send the deadline priority question",observationHint:"Actual movement minutes; question and reply or silence"},stopRule:"Stop movement for pain, dizziness, or feeling unwell; seek suitable advice. Do not use movement as punishment.",accessibleAlternative:"Use seated movement or a nonmovement pause. If skipping movement, save the question alone as action and minimum."},result:{question:"Did you use your chosen break and response?",observationPrompt:"What version and duration happened, and what did you do next?"},judgment:{primary:{id:"calm-3-decision",scenario:"Priya notices she rushes replies after skipping breaks. She has two minutes, a prepared priority question, and suitable seated movement; rain blocks her walk.",question:"Which plan best tests her observed rushing problem?",options:[{id:"calm-3-larger-tomorrow",text:"Send the question now and reserve a walk for a later break when the weather allows.",feedback:"Sending now handles priorities promptly, and a later walk remains possible. It leaves her observed rushing barrier untested; a suitable minute still fits before the prepared question."},{id:"calm-3-research-first",text:"Use the two minutes to compare movement routines, then choose a route before asking for priorities.",feedback:"Research can help when a suitable option is missing. Here Priya already has one. Another comparison replaces the actual break and question with preparation that does not resolve today’s constraint."},{id:"calm-3-suitable-small",text:"Use her suitable seated minute, send the prepared question, and record the version without requiring relief.",feedback:"This fits the available time and keeps the useful response. Seated movement is an adaptation, not the tested walking protocol, and unchanged tension is an honest observation."}],bestOptionId:"calm-3-suitable-small"}},carry:{takeaway:"Use the version that fits. Do not turn a missed break into tomorrow’s debt.",followUp:{questionId:"calm-3-return",question:"Did the break fit your body and leave time for the chosen response?",observationPrompt:"What happened when your chosen cue arrived?",adjustmentPrompt:"What should you repeat, change, or get help with?"}},goDeeper:{sections:[{heading:"Program averages are not one-break predictions",paragraphs:["Singh and colleagues synthesized 97 reviews covering 1,039 unique component randomized trials [C07]. Depression and anxiety results were median standardized effects across reviews, not one pooled participant-level estimate. Depression was −0.43 with an interquartile range of −0.66 to −0.27; anxiety was −0.42 with a range of −0.66 to −0.26. These ranges are not confidence intervals. The review-reported participant counts contain overlap.","The distress estimate of −0.60, with a 95% confidence interval from −0.78 to −0.42, came from one review of six trials. Seventy-seven reviews were rated critically low quality. Associations with intensity or program duration do not show that harder or shorter is best for a particular person. The broad evidence supports considering suitable activity alongside other support. It does not justify escalating a two-minute break or promising that today’s tension will fall."]},{heading:"What a brief walking experiment can tell you",paragraphs:["Edwards and Loprinzi randomized 66 young adults to ten minutes of treadmill walking, guided meditation, or quiet sitting [C17]. The fatigue and composite-mood interactions compared all three groups. They were not walking-only effect estimates. Walking’s within-group composite-mood change had p=.10, so the detailed results do not clearly establish an overall mood benefit from that walk. Effect confidence intervals and independent exact replication were not verified.","An indoor route, comfortable pace, seated movement, or nonmovement pause is an ODA adaptation, not that laboratory procedure. NHS guidance treats movement as one coping option while noting it does not remove the stressor [C06]. Use the record to assess suitability, access, and whether your planned next response happened. One before-and-after feeling change cannot prove what caused it. A health condition, pain, or eating concern may call for qualified advice rather than a bigger activity target."]}],sourceIds:["C06","C07","C17"]}},{schemaVersion:2,revision:2,id:"calm-4",courseId:"calm",locale:"en",title:"“Can we talk?” Check your story",goal:"Separate observation from prediction, then use one safe practical response.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"One vague message, a whole ending in your head. Check what you know before your next move.",reason:{id:"calm-4-reason",label:"What are you postponing because a prediction feels settled?",kind:"text",maxLength:160,optional:!0,suggestions:["Asking what to prepare","Sending a correction I can already make","Requesting help with an unsafe situation","No action I am postponing"]},why:{id:"calm-4-why",label:"What would this move protect in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A balanced thought is not necessarily a positive thought. NHS guidance asks you to check evidence and consider a fuller view. “I do not know yet” can be more accurate than either “I am in trouble” or “They must value me.” Neither imagined motive is a fact.","Return to the same cue and response. If a prediction blocked it, name what was said or done, then choose a safe clarification, repair, boundary, or support step. Reframing does not remove a real workload problem or mistreatment. Test the action and evidence that follow, even if uncertainty remains."],example:{title:"Priya asks what to prepare",text:"Priya receives “Can we talk tomorrow?” and predicts she caused a problem. She records the actual message, then asks what to prepare for their safe check-in. Her manager replies, “The client’s revised schedule.” That gives her a useful task, not certainty about the whole meeting. She prepares the schedule and records the exchange while still nervous."}},move:{invitation:"Keep your response; edit the preparation-question example.",instructions:["Separate the observation from your prediction.","Ask, repair, protect, or seek support; do not invent another person’s motive."],prompts:[],suggestions:{action:["Ask what to prepare for the meeting","Clarify one ambiguous request","Make one safe repair or boundary"],minimum:["Send one preparation question","Ask one clarification question","Take one chosen protective step"],cue:["When a meeting message omits the topic","When a difficult work email arrives","Before I act on a prediction"],place:["At my desk, in the supervisor’s email","A private supported communication space","My accessible note-and-contact space"],minutes:[2,1,5],fallback:["Bring the current schedule; ask at the meeting","Choose protection or support","Wait for a safer clarification opening"],observation:["Question sent; topic learned or still unknown","Facts learned, including continued uncertainty","What safe step I actually took"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Ask what to prepare for the meeting",minimum:"Send one preparation question",minutes:2,cueHint:"When a meeting message omits the topic",placeHint:"At my desk, in the supervisor’s email",obstacleHint:"The safe supervisor cannot answer before the meeting",fallbackHint:"Bring the current schedule; ask at the meeting",observationHint:"Question sent; topic learned or still unknown"},stopRule:"Do not reframe mistreatment into acceptance. Use safety, boundaries, or support when needed.",accessibleAlternative:"Use writing, assistive communication, or a trusted supporter; no body focus is needed."},result:{question:"Did you take the fact-based step you chose?",observationPrompt:"What did you ask or do, and what evidence actually followed?"},judgment:{primary:{id:"calm-4-decision",scenario:"Priya gets “Can we talk tomorrow?” from a safe supervisor who can answer a short question today. She has ten minutes and the current deliverable, but no topic.",question:"Which response checks the prediction?",options:[{id:"calm-4-positive-story",text:"List the reasons her supervisor might appreciate her work, then prepare for a positive conversation tomorrow.",feedback:"A positive explanation can be possible, but it is still a guessed motive. Priya can leave the outcome uncertain and ask what to prepare instead of settling a reassuring story."},{id:"calm-4-clarify",text:"Note the exact message, ask what to prepare, and use the reply to choose a practical step.",feedback:"This separates known facts from prediction and gathers relevant information. The reply may leave uncertainty; Priya still gains a clearer action without needing to feel reassured or assume a motive."},{id:"calm-4-review-everything",text:"Check the current deliverable for ten minutes and bring it tomorrow, without asking about the topic.",feedback:"A bounded check may improve the deliverable. It may prepare the wrong material here, because the topic is unknown and the supervisor can clarify now. Worry is not evidence of an error."}],bestOptionId:"calm-4-clarify"}},carry:{takeaway:"A fuller view can say “I do not know yet” and still choose a useful action.",followUp:{questionId:"calm-4-return",question:"Did the action add evidence, or did you replace one guess with another?",observationPrompt:"What happened when your chosen cue arrived?",adjustmentPrompt:"What should you repeat, change, or get help with?"}},goDeeper:{sections:[{heading:"Balance does not require a nicer certainty",paragraphs:["NHS guidance on reframing uses noticing, checking evidence, and considering a balanced alternative [C10]. A real observation might be “The message asks to talk tomorrow.” A prediction might be “I will lose my role.” A possible alternative is “There may be a schedule issue.” The alternative remains a possibility until evidence arrives. You do not need to believe the best explanation to ask a safe practical question.","The fact-and-prediction pair plus clarification is an ODA adaptation, not a validated stand-alone CBT treatment. A known mistake can call for repair. A documented unreasonable demand can call for negotiation or support. Abuse and coercion call for protection, not a more generous interpretation of the other person. NHS anxiety guidance distinguishes gradual work with safe feared situations from the need for care when anxiety disrupts life [C03]. This lesson is not exposure therapy."]},{heading:"Different emotion is not different external evidence",paragraphs:["Webb and colleagues summarized 306 experimental comparisons [C09]. Perspective change and stimulus reappraisal had average effects on emotion in predominantly short laboratory tasks. Thought suppression’s pooled estimate was −0.12. That does not establish that every attempt to put a thought aside fails, or that expression suppression is the same thing. Nor does feeling less anxious establish that a new interpretation is true.","The opened abstract did not provide confidence intervals or verify a total participant count. Lasting effects of this brief ODA worksheet remain untested. The practical purpose is to stop using a prediction as if it were already an observation, then choose a safe act relevant to your continuing experiment. Keep the response and its actual result together in the record. A question without a reply leaves uncertainty, which is still valid information for the next attempt or a support decision."]}],sourceIds:["C03","C09","C10"]}},{schemaVersion:2,revision:2,id:"calm-5",courseId:"calm",locale:"en",title:"Stop carrying the week alone",goal:"Review the same experiment and repeat one useful response or make a specific needed support request.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Still carrying the week alone? Use any records to choose one next response or ask for actual support.",reason:{id:"calm-5-reason",label:"What do you need help carrying instead of another technique?",kind:"text",maxLength:160,optional:!0,suggestions:["Arranging a care appointment","Handling appointments while sleep is disrupted","A workload I cannot carry alone"]},why:{id:"calm-5-why",label:"What would this move protect in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Professional help fits when coping is difficult or self-help is not working. You do not need a crisis, a perfect explanation, or a finished course. A support list is preparation; asking for specific help is the contact step.","Review any records from your cue-and-response experiment. Keep a feasible response or ask for help. If you have not tried, choose a first safe opportunity. “Could you help me arrange an appointment?” is concrete. No reply is still a contact attempt. Recurrent panic or daily impairment warrants assessment; support need not wait for practice."],example:{title:"Priya asks for help with the load",text:"Priya’s records show three clear priority requests, but she is still struggling to sleep and manage care appointments. She asks her sister, “Could you help me call the clinic today?” and makes an assessment request. Her sister can only help tomorrow. Priya records both contacts and keeps one workload question for next week, without adding another exercise."}},move:{invitation:"Keep your plan; edit the clinic-contact example.",instructions:["Review records; repeat what fit or request needed support.","Before saving, name the actual recipient, ask, available cue, and fallback contact."],prompts:[],suggestions:{action:["Call the public clinic’s appointment desk","Ask sister to help arrange an appointment","Ask a friend for ten minutes together"],minimum:["Request assessment for sleep and appointment difficulties","Send sister an appointment support request","Send one request for a ten-minute conversation"],cue:["After lunch, during the desk’s opening hours","After lunch today","When the public clinic’s desk opens"],place:["At home with my phone","Kitchen table, using accessible messaging","A private room with accessible contact tools"],minutes:[2,5,10],fallback:["Use the clinic’s accessible appointment request form","Ask sister to help contact the clinic","Call the public clinic’s next opening"],observation:["Contact attempted; response and next access step","Whether practical support happened","Next access step, including no reply"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Call the public clinic’s appointment desk",minimum:"Request assessment for sleep and appointment difficulties",minutes:2,cueHint:"After lunch, during the desk’s opening hours",placeHint:"At home with my phone",obstacleHint:"The clinic’s appointment desk does not answer",fallbackHint:"Use the clinic’s accessible appointment request form",observationHint:"Contact attempted; response and next access step",kind:"support"},stopRule:"Self-harm thoughts need prompt professional or crisis help. If you cannot stay safe or face immediate danger, use local emergency help.",accessibleAlternative:"Choose Adapt this, then Support for a contact plan. Use public-service, assisted, text, or phone contact. Name the recipient, ask, opening, and available fallback before saving."},result:{question:"Did you make the request or response you chose?",observationPrompt:"What did you ask or do, and what support actually followed?"},judgment:{primary:{id:"calm-5-decision",scenario:"Priya’s anxiety repeatedly disrupts sleep and appointments. She can stay safe. Her public clinic’s appointment desk is open now and accessible; a support line offers referrals. Her sister can help tomorrow.",question:"Which next plan fits the record?",options:[{id:"calm-5-support-and-care",text:"Contact the clinic today with a brief impact summary, then ask for any practical help needed.",feedback:"This uses an accessible assessment route without waiting for crisis or perfect certainty. Her sister can help later. If immediate safety changes, the urgent route becomes necessary."},{id:"calm-5-friends-first",text:"Ask her sister to help book an appointment tomorrow, while noting how the difficulties affect daily life.",feedback:"Assisted booking can make access easier. Here Priya can reach her known clinic herself today; waiting for tomorrow’s help delays available assessment. Her sister can still assist later."},{id:"calm-5-complete-explanation",text:"Call the public support line today to locate a clinician, then decide which appointment desk to contact.",feedback:"Referral advice helps when an accessible clinician is missing. Her own clinic is reachable now, so searching adds a step without answering her immediate access need. Both routes remain legitimate options."}],bestOptionId:"calm-5-support-and-care"}},carry:{takeaway:"Keep what fit. Ask for the help the remaining problem actually needs.",followUp:{questionId:"calm-5-return",question:"What happened with your request or response, and which reply or access step is still pending?",observationPrompt:"What happened when your chosen cue arrived?",adjustmentPrompt:"What should you repeat, change, or get help with?"}},goDeeper:{sections:[{heading:"A request has a recipient and a specific ask",paragraphs:["WHO and NHS guidance include trusted connections and practical coping options [C01, C02]. This course turns that advice into an optional specific request: a conversation, help with a task, or assistance contacting care. The script and fallback are ODA design, not a validated isolated intervention. Sending a request is an observable act. Receiving support, feeling better, and solving the stressor are separate outcomes.","Review any plans and attempts from your experiment instead of collecting another routine. Identify which response was usable, what interfered, and what remains beyond your capacity. An untried plan has no known outcome; choose a first safe opportunity or needed support. A person may be unavailable or decline; that is information for another contact or public service. You do not need a trusted personal network to ask for professional help. Keep sensitive details private if you prefer, while making a concrete next access step."]},{heading:"Assessment can begin before an emergency",paragraphs:["NHS stress guidance recommends professional help when coping is difficult or self-help is not working [C02]. Recurrent panic needs assessment because symptoms can have other causes and treatment choices may require clinical support [C04]. A new physical symptom should not automatically be labeled stress. This course does not prescribe medication changes, a fixed CBT session count, or a treatment bundle of sleep, movement, and breathing.","Self-harm thoughts without immediate danger still call for prompt professional or crisis support. If you cannot stay safe or face immediate danger, use local emergency help now and ask a trusted person to stay if safe. These are safety routes, not a diagnosis or validated triage algorithm. The final learning step can be keeping one workable response, resting, pausing the experiment, or making a care request. None requires completing a full set of techniques first."]}],sourceIds:["C01","C02","C04"]}}],O=[{practice:["Notice a familiar body signal or outward situation cue; a physical symptom does not establish its cause.","Give the feeling a one-word name; it does not have to be the perfect word.","Describe the situation behind it in one sentence: “In this situation, I feel …”."],reflection:"Which sign most often tells you that you are stressed?",question:"Which view of stress fits this lesson?",options:["If I feel stressed, something must be badly wrong, and I need to get rid of it right away.","Stress is an ordinary response to difficult situations; noticing and naming it can be a first step.","Naming my feeling will only make it bigger, so I should ignore it."],correct:1,feedback:"Stress can accompany difficult situations. Noticing and naming may help you choose a useful response, but do not guarantee relief. New symptoms or difficulty coping can require assessment or support."},{practice:["If suitable, sit safely and try the studied five-minute routine voluntarily; ordinary breathing and an outward anchor are alternatives.","For cyclic sighing, inhale slowly, add a shorter inhale without forcing fullness, then exhale slowly. Stop if dizzy or unwell.","Note comfort, actual practice, or a stop separately from mood. New or concerning symptoms need assessment; do not drive while symptomatic."],reflection:"What did you notice in your body when you lengthened your exhale?",question:"What is the emphasis in cyclic sighing?",options:["Holding your breath for as long as possible.","Taking fast, deep breaths one after another.","Keeping the exhale slow and long."],correct:2,feedback:"Cyclic sighing uses two inhales followed by a slow exhale. Five daily minutes for 28 days was studied, not a quick reset. Stop if dizzy or unwell and return to ordinary breathing."},{practice:["Choose suitable movement today, including an accessible seated version, or keep a nonmovement pause if movement is unsuitable.","Link it to a moment that already happens in your day, such as a short walk after lunch.","If useful, record tension before and after moving; unchanged feelings are valid, and a change does not prove causation."],reflection:"Which kind of movement feels like a break to you, rather than a punishment?",question:"How should the 2023 umbrella review by Singh and colleagues be read?",options:["Movement is linked with fewer symptoms, but most of the reviews were of low quality.","Everyone who exercises will definitely lose their anxiety.","If I exercise, I no longer need medication or therapy."],correct:0,feedback:"Activity programs reduced symptoms on average, but most included reviews were critically low quality. Their median results do not predict one short break or replace needed care."},{practice:["Write down, in one sentence, a situation that has been stressing you lately.","Consider plausible alternatives without inventing motives; an uncertain explanation may be more accurate than a positive one.","Imagine how the situation would look to a neutral observer, then say to yourself the sentence you would say to a friend going through the same thing."],reflection:"When you read the situation from another angle, what changed and what stayed the same?",question:"In the 2012 meta-analysis by Webb and colleagues, which stood out as a more effective strategy?",options:["Trying not to think about the event at all.","Trying to see the situation through the eyes of an outside observer.","Getting stuck on the negative feeling and dwelling on it."],correct:1,feedback:"Perspective change and reappraisal affected short laboratory emotions on average. The pooled thought-suppression estimate was negative, not proof that suppression always fails. Use evidence and a safe next action."},{practice:["Name available trusted or public-service contacts; a personal support network is not required to request care.","Choose a moment this week to tell someone how you are doing, or to ask for a small bit of support.","Using the help table, write down in your own notes whom you will turn to in which situation."],reflection:"On a hard day, who is the first person you would want to reach?",question:"If you cannot stay safe or are in immediate danger, what should you do?",options:["Finish the rest of the course exercises and wait.","Handle it on my own so I don’t burden anyone.","Call my local emergency number and, if possible, ask someone to be with me."],correct:2,feedback:"Use local emergency help if you cannot stay safe or face immediate danger. Self-harm thoughts without immediate danger still require prompt professional or crisis support; do not wait to finish the course."}],N=[{id:"1758876019128-e76eebf402bd",alt:"Tired person resting their head on one hand at a table"},{id:"1717691526463-975c4119505c",alt:"Woman standing with her eyes closed in front of a tree"},{id:"1758272421829-7028296dee8f",alt:"Woman stretching on the floor of a living room"},{id:"1658279366796-e0c28623cd27",alt:"Woman sitting on a windowsill looking outside"},{id:"1747764925585-6c2df83b3fd2",alt:"Two women talking over coffee"}],P={id:"calm",title:"Stress is choosing your replies? Take the next move back",subtitle:"Five lessons to catch one stress cue, try a safe response, and choose a useful next act while feelings vary.",description:"Build one cue-and-response experiment around your real week. Use a comfortable pause, suitable movement, fact checking, or support only when it helps your chosen act.",scope:"Everyday stress-management education for adults, not diagnosis or treatment. Stop breathing or movement exercises if dizzy, uncomfortable, or unwell; sit safely and return to ordinary breathing. New or concerning physical symptoms need medical assessment, urgently when severe. Do not assume panic explains them. Seek professional care for recurrent panic, impaired daily life, difficulty coping, or unsuccessful self-help. Do not change treatment or medication independently. Self-harm thoughts need prompt professional or crisis support; inability to stay safe or immediate danger needs local emergency help. Abuse calls for safety and specialist support, not tolerance practice.",outcome:"One safe response you can use at your stress cue, honest attempt records, and a workable next-week or support step.",photo:{id:"1557316655-8715fdecd2d1",alt:"Still lake at the foot of a mountain"},lessons:y.map((e,t)=>({id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,...O[t],takeaway:e.carry.takeaway,sources:t===0?[...e.goDeeper.sourceIds,"C01"]:e.goDeeper.sourceIds,deeper:e.goDeeper.sections,example:{title:`Invented example: ${e.idea.example.title}`,text:e.idea.example.text},photo:N[t]}))},B=Object.freeze(Object.defineProperty({__proto__:null,COURSE:P,LESSONS_V2:y,SOURCES:F},Symbol.toStringTag,{value:"Module"})),R="compassion",M=[{id:"compassion-neff-definition",title:"Neff · What is self-compassion? · Dossier C11",url:"https://self-compassion.org/what-is-self-compassion/",type:"guidance",finding:"Framework combines self-kindness, common humanity, and mindful acknowledgment of difficulty. Tender and fierce compassion are practitioner descriptions of comfort, protection, and action.",limitation:"Definition page, not isolated mechanism or treatment evidence. Self-esteem can become performance-contingent; that does not define all self-esteem. No requirement to feel warmth."},{id:"compassion-mindful-self-compassion-rct",title:"Neff & Germer · 2013 · Mindful Self-Compassion trial · Dossier C05",url:"https://doi.org/10.1002/jclp.21923",type:"research",finding:"52 adults were randomized to an eight-week program or waitlist. Controlled posttest outcomes favored the program on several measures. Sessions and retreat required substantial practice.",limitation:"Small developer-led bundle trial, not a break or letter test. One-year follow-up had 15 respondents and no concurrent control. It cannot establish retained controlled effects for all participants."},{id:"compassion-gilbert-cft",title:"Gilbert · 2014 · Compassion-focused therapy · Dossier C07",url:"https://doi.org/10.1111/bjc.12043",type:"research",finding:"Clinical and theoretical review describes threat, drive, and affiliative soothing as a functional framework, with compassion-focused practices.",limitation:"Not three anatomical switches or proof of an isolated exhale or imagery effect. Practical safety, resources, and material needs can matter. Safeness practices may be uncomfortable."},{id:"compassion-tangney-moral-emotions",title:"Tangney, Stuewig & Mashek · 2007 · Moral emotions · Dossier C08",url:"https://doi.org/10.1146/annurev.psych.56.091103.070145",type:"research",finding:"Whole-self shame commonly relates to withdrawal or defensiveness; behavior-focused guilt can relate to empathy and repair.",limitation:"Narrative, primarily observational review. These are tendencies, not absolute laws. Excessive guilt can harm. Shame after victimization does not establish wrongdoing or an obligation to apologize."},{id:"compassion-brown-shame-resilience",title:"Brown · 2006 · Shame resilience theory · Dossier C09",url:"https://doi.org/10.1606/1044-3894.3483",type:"research",finding:"Interviews with 215 women developed a framework involving recognizing shame, reality-checking expectations, safe connection, and naming shame.",limitation:"Qualitative theory-building, not a controlled test of four-step treatment. Disclosure is optional and only to a safe willing person. No forced body focus or traumatic recall."},{id:"compassion-improvement-motivation",title:"Breines & Chen · 2012 · Improvement motivation · Dossier C06",url:"https://doi.org/10.1177/0146167212445599",type:"research",finding:"Four experiments found short-term improvement motivation. After failed testing, compassion participants studied longer than no-reminder participants: 306.5 versus 203.2 seconds.",limitation:"Second-test scores did not improve significantly. The self-esteem comparison was inconclusive. Amends motivation is not actual repair; no lasting change or independent preregistered replication was verified."},{id:"compassion-journal-guidance",title:"Neff · Self-compassion journal · Dossier C18",url:"https://self-compassion.org/exercises/exercise-6-self-compassion-journal/",type:"technique",finding:"Developer guidance asks for acknowledgment of a difficulty, its human context, and kind words, with daily journaling for a week or longer.",limitation:"Not isolated efficacy evidence or a tested ODA rendering. Earlier timing or shorter reflection are adaptations. Writing can be skipped or stopped if it fuels distress."},{id:"compassion-break-guidance",title:"Neff · Self-compassion break · Dossier C16",url:"https://self-compassion.org/exercises/exercise-2-self-compassion-break/",type:"technique",finding:"Developer procedure acknowledges hurt, recognizes shared humanity, and offers kind words or a wish, with supportive touch in the original guidance.",limitation:"Not an isolated efficacy test or proven two-minute dose. ODA provides optional touch, mild examples, ordinary breathing, outward anchors, and stopping choices."},{id:"compassion-touch-trial",title:"Dreisoerner et al. · 2021 · Self-soothing touch trial · Dossier C14",url:"https://doi.org/10.1016/j.cpnec.2021.100091",type:"research",finding:"159 healthy young adults formed the final sample. Self-touch changed cortisol responses to a laboratory stressor, while reported stress and heart rate did not differ.",limitation:"Single preregistered trial with changed missingness analysis. No oxytocin measurement, guaranteed emotional relief, or clinical efficacy. Ordinary-breathing and no-touch options are ODA adaptations."},{id:"compassion-kindness-review",title:"Zeng et al. · 2015 · Kindness meditation review · Dossier C10",url:"https://doi.org/10.3389/fpsyg.2015.01693",type:"research",finding:"24 empirical studies with 1,759 participants mixed designs. Relevant loving-kindness and compassion subgroup estimates were 0.424 and 0.286; the subgroup difference was not significant.",limitation:"Not 24 randomized trials or evidence of a winning practice. Varied methods, early studies, and often waitlist controls. Does not estimate ODA soothing exercises."},{id:"compassion-practice-safety",title:"Neff · Self-compassion practice guidance · Dossier C12",url:"https://self-compassion.org/self-compassion-practices/",type:"guidance",finding:"Developer guidance distinguishes kind intention from producing pleasant feelings and advises pulling back when practice overwhelms.",limitation:"Practitioner advice, not a new diagnosis or established physiological backdraft mechanism. Outward attention, ordinary support, or stopping can replace uncomfortable inward focus."},{id:"compassion-letter-guidance",title:"Neff · Friend-letter guidance · Dossier C17",url:"https://self-compassion.org/exercises/exercise-3-exploring-self-compassion-through-writing/",type:"technique",finding:"Developer guidance describes a caring friend perspective, kind suggestions for change, and putting the letter aside to reread later.",limitation:"Not an isolated efficacy test or validated fifteen-minute dose. The program trial did not isolate the letter. No forced suffering story, warmth, guilt, or disclosure."}];function d(e){const t=e.suggestions;return{schemaVersion:2,revision:2,id:e.id,courseId:R,locale:"en",title:e.title,goal:e.goal,minutes:{learning:6,suggestedAction:t.minutes[0],review:2},direction:{hook:e.hook,reason:{id:`${e.id}-reason`,label:e.reason,kind:"text",maxLength:160,optional:!0,suggestions:e.reasons},why:{id:`${e.id}-why`,label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:`${e.id}-cost`,label:"What does the current pattern cost you?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:e.paragraphs,example:e.example},move:{invitation:e.invitation,instructions:e.instructions,prompts:[],suggestions:t,suggested:{action:t.action[0],minimum:t.minimum[0],minutes:t.minutes[0],cueHint:t.cue[0],placeHint:t.place[0],obstacleHint:e.obstacle,fallbackHint:t.fallback[0],observationHint:t.observation[0]},stopRule:e.stop,accessibleAlternative:e.accessible},result:{question:e.result,observationPrompt:e.observation},judgment:{primary:e.scenario},carry:{takeaway:e.takeaway,followUp:{questionId:`${e.id}-return`,question:e.follow,observationPrompt:e.followObservation,adjustmentPrompt:"What would make the next attempt fit your life?"}},goDeeper:{sections:e.depth,sourceIds:e.sources}}}const l=[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],w=d({id:"compassion-1",title:"Missed again? Correct the mistake without the insult",goal:"Choose one manageable setback, describe it fairly, and take a useful repair, task, or support step.",hook:"Your inner critic claims it keeps standards high. What useful action did its last insult produce?",reason:"What useful response has self-criticism delayed?",reasons:["Correct a real mistake","Return to useful work","Ask for support sooner"],paragraphs:["Care and effort can coexist. In one test-failure experiment, students given a compassionate prompt studied longer than students given no reminder. Their next scores did not improve significantly. This concerns short-term effort, not guaranteed results.","Carry one ordinary setback through this course. Keep the fact, drop the insult: “My estimate was short,” not “I am useless.” Then correct, return to a task, or request support. Consider repair for harm you caused, protection for harm done to you. Feeling kinder is optional. The action, cue, and outcome form your continuing experiment."],example:{title:"Daniel's revised date",text:"At 5 p.m., Daniel notices that his report estimate was too short. He replaces “sloppy idiot” with the factual miss. From his desk, he sends a realistic revised date and adds a buffer to the next estimate. His manager is disappointed. Daniel records the update and correction. He still regrets the delay, but the repair has begun."},invitation:"Pick one manageable setback. Keep the fact, then do one useful response instead of another insult.",instructions:["Name the fact without a verdict about your worth.","Take one appropriate repair, task, or support step."],suggestions:{action:["Send one realistic revised date","Correct one actual work mistake","Request one practical support step"],minimum:["Send one factual update sentence","Correct one actual item","Name one support need"],when:l,cue:["After checking the missed estimate","At my next manageable setback"],place:["At my work desk","In a safe message thread"],minutes:[3,2,5],fallback:["Ask for help estimating the work","Choose a safer support route"],observation:["The update or correction I made","What response came back"]},obstacle:"I insult myself instead of addressing the miss",stop:"Choose an ordinary setback. Stop if distressed; seek support for persistent or overwhelming distress.",accessible:"Use neutral words, your usual communication method, or assistance. No warmth, body focus, or disclosure required.",result:"Did you take your chosen useful step?",observation:"What did you correct, request, or actually do?",scenario:{id:"compassion-1-missed-estimate",scenario:"Daniel missed a deadline because he underestimated the work. He can now give a realistic date and adjust his estimate.",question:"Which response combines care and accountability?",bestOptionId:"update-and-adjust",options:[{id:"update-and-adjust",text:"Name the missed estimate without an insult, send the realistic date, and change the next estimating step.",feedback:"This keeps the actual impact visible and begins repair. Daniel can regret the miss while giving useful information and improving his plan. Kindness does not require excusing the delay."},{id:"wait-for-shame",text:"Take the evening off and prepare a team update once the shame feels manageable enough to discuss.",feedback:"Rest can be appropriate, but the update is available and needed now. Waiting for shame to ease leaves others without information. Send the realistic date, then choose needed recovery."},{id:"explain-regret",text:"Explain how bad he feels about the delay and promise an updated date after the work becomes clearer.",feedback:"Honest regret can belong in an apology, but it does not replace information Daniel already has. Give the realistic date and address the estimate rather than emphasizing self-punishment."}]},takeaway:"Keep the standard and the facts. Let the next useful action show your care.",follow:"Did fair words support a useful step, remain words only, or reveal a need for support or pause?",followObservation:"Name the actual update, correction, or request; note if it remained unavailable.",depth:[{heading:"More effort did not mean better scores",paragraphs:["Breines and Chen ran four experiments on self-compassion and improvement motivation. In the test-failure experiment, the compassion condition studied for an average 306.5 seconds, compared with 203.2 seconds in the no-reminder condition. The comparison with self-esteem reassurance was inconclusive, and second-test scores did not significantly differ. The transgression experiment measured motivation to make amends, not completed repair. [C06: compassion-improvement-motivation]","These short experiments mostly involved students, with an online adult sample in the paper. They do not establish lasting change or the effect of this lesson's script. Care can accompany effort, but a fair sentence does not guarantee motivation, performance, or repair. This lesson adds an actual next step as an ODA adaptation. Report that behavior directly, including an unhelpful response, an unfinished correction, or the absence of an opportunity. Sending a revised date is evidence of an update, not proof that the delayed work is finished."]},{heading:"One setback, one continuing response",paragraphs:["Neff describes self-compassion as kindness, shared humanity, and mindful acknowledgment of difficulty. It does not require forgetting a mistake or approving harmful conduct. This is a definition and practitioner framework, not three separately established mechanisms. [C11: compassion-neff-definition] Here, neutral respect is enough: say what happened and choose what would help address it.","Keep the same manageable setback or recurring pattern as you progress. Later lessons refine the support for your action, not your obligation to feel good. A correction belongs where you actually made an error. A support or protective step belongs where you were harmed or the task exceeds your resources. Do not invent an apology to make the exercise fit. Your record can contain a repair attempted, a task resumed, a support request made, or an appropriate pause. A plan remains a plan until you report an act, and another person's response remains outside your control."]}],sources:["compassion-improvement-motivation","compassion-neff-definition"]}),b=d({id:"compassion-2",title:"Everyone struggles. Your disappointment still deserves a response",goal:"Add the missing support to your response to the same setback, then do its useful minimum.",hook:"“Everyone makes mistakes” can become another way to dismiss yourself. What did your response leave out?",reason:"What does dismissing disappointment stop you from addressing?",reasons:["Acknowledge what hurt","Stop treating myself as uniquely broken","Return without self-dismissal"],paragraphs:["Neff's framework combines acknowledging difficulty, recognizing shared struggle, and responding helpfully. “Everyone fails, so stop making a fuss” includes shared humanity but dismisses pain. Naming pain without support leaves another part missing.","At your same setback, add a neutral sentence for the missing part. “I am disappointed, and I can review one question” can be enough. Self-esteem can become tied to performance; that does not define all self-esteem. You need no ranking for this practice. Then do your existing useful minimum, or choose appropriate support."],example:{title:"Inez's review question",text:"After dinner, Inez reviews the exam mistake she chose yesterday. “Everyone fails” had helped her avoid admitting disappointment. At her kitchen desk, she adds, “This hurts, and I can help myself understand one question.” She reviews that question for two minutes. She still dislikes the result and needs more practice. She records the review rather than a confidence rating."},invitation:"Add the support your last response missed. Use it beside your same useful action.",instructions:["Acknowledge difficulty without exaggerating or dismissing it.","Do the existing useful minimum, or choose appropriate support."],suggestions:{action:["Review one missed practice question","Correct my chosen work item","Send my planned support request"],minimum:["Work through one practice question","Correct one actual item","Make one support request"],when:l,cue:["After dinner at my review time","At my existing setback cue"],place:["At my kitchen desk","In my safe study space"],minutes:[2,1,5],fallback:["Ask for help with the question","Use neutral words and a smaller step"],observation:["The support sentence and act used","Where I still need help"]},obstacle:"I dismiss the difficulty instead of supporting the response",stop:"Skip painful recall and seek support if the practice becomes overwhelming.",accessible:"Use neutral language silently, type, sign, or ask for assistance. No warm feeling or comparison required.",result:"Did you do your useful minimum with the added support?",observation:"Which support did you add, and what did you actually do?",scenario:{id:"compassion-2-dismissed-disappointment",scenario:"Inez dismisses her exam disappointment with “Everyone fails.” She is rested, has five free minutes, and one marked question ready. Her evening shift leaves no study slot later.",question:"Which response supports the available review?",bestOptionId:"acknowledge-and-review",options:[{id:"break-and-review-later",text:"Acknowledge disappointment, take a short study break now, and reserve the ready question for after her shift.",feedback:"A break can protect capacity when she needs one. Here she is rested and has no later study slot. Use the available question now; schedule recovery around the shift."},{id:"organize-review-topics",text:"Acknowledge disappointment and use the five minutes to organize an overview of topics needing more practice.",feedback:"An overview helps when priorities are unclear. This question is already identified and ready. Work through it now; use what remains difficult to guide a later overview."},{id:"acknowledge-and-review",text:"Acknowledge disappointment, recognize shared struggle, and offer a fair response while reviewing the prepared question.",feedback:"Shared humanity does not erase Inez's disappointment. This response keeps the feeling in view and supplies support for a useful act. No ranking or immediate relief is necessary."}]},takeaway:"Shared struggle can reduce isolation. It does not cancel what you need now.",follow:"Which support was missing, and did adding it change your next useful act?",followObservation:"Name the missing support and its effect, or note skipped support or an unknown effect.",depth:[{heading:"A definition is not three proven ingredients",paragraphs:["Neff's definition combines self-kindness, common humanity, and mindful acknowledgment of suffering. Those names describe a framework. The developer page does not establish that each isolated component independently causes clinical improvement. It also does not define all self-esteem as competition. Self-worth can become contingent on performance or comparison, but that is one pattern rather than the whole construct. [C11: compassion-neff-definition]","Use the three directions to inspect your response, not score your humanity. Did you acknowledge what was difficult? Did you avoid treating the experience as proof that you alone are defective? Did you offer a useful response? A sentence can be neutral and respectful if warm language feels false. Keep the chosen action from the previous lesson. This is a brief ODA application, and the thing you can report is the action taken with that support, not a diagnosis or a validated component score."]},{heading:"A journal may support action without becoming the action",paragraphs:["The developer's self-compassion journal asks for acknowledgment of a difficulty, its human context, and kind words. It suggests daily writing for a week or longer, usually in the evening. That guidance documents how the practice is taught; it does not establish an isolated clinical effect or an optimal writing duration. [C18: compassion-journal-guidance] This lesson uses a shorter optional check around your continuing experiment.","Write only if it helps. You may answer silently, use assistive communication, or keep details elsewhere. If reflection fuels rumination, choose another time or drop the writing. A journal entry is preparation when the purpose is reviewing a question, making a correction, or requesting support. It can have its own preparation record, but it is not evidence that the downstream act happened. Record the question worked through, correction made, or request sent. Urgent reporting and established safety procedures should never wait for a personal reflection exercise."]}],sources:["compassion-neff-definition","compassion-journal-guidance"]}),v=d({id:"compassion-3",title:"Still upset after the pause? Choose care next",goal:"Use an optional supportive pause before your same useful action, without making relief a completion condition.",hook:"The pause did not erase the sting. What manageable response would care choose now?",reason:"What does waiting for calm leave unfinished?",reasons:["Respond to useful feedback","Choose support when overwhelmed","Return without waiting for calm"],paragraphs:["A self-compassion break acknowledges difficulty, shared humanity, and a helpful response. It is developer guidance. The trial studied an eight-week program, not a two-minute break. Its incomplete one-year follow-up had no comparison group.","At your same everyday setback, try “This is hard; what would help?” Touch, eyes closed, body focus, and warmth are optional. Keep ordinary breathing and look outward if preferable. Do your useful minimum, adapt, or request support. Stop if distress rises. The pause prepares a choice; record the actual action."],example:{title:"Sam's feedback response",text:"At 3 p.m., Sam receives difficult feedback on the draft he has been improving. He uses a words-only pause: “This is hard; what would help next?” Touch feels uncomfortable, so he skips it. Still upset, he corrects one cited error at his desk. He records the correction. The draft needs another pass, and the feeling has not disappeared."},invitation:"Try a brief supportive pause if useful. Then choose the same manageable action, adaptation, or support.",instructions:["Use a mild everyday difficulty, without forced recall.","Do one useful next step if the setting fits."],suggestions:{action:["Correct one useful draft error","Send my chosen factual update","Make my planned support request"],minimum:["Correct one cited error","Send one update sentence","Name one support need"],when:l,cue:["After difficult everyday feedback","At my existing setback cue"],place:["At my safe work desk","In a quiet familiar space"],minutes:[2,1,5],fallback:["Look outward and use neutral words","Stop and request useful support"],observation:["The next caring action actually taken","Whether I stopped when uncomfortable"]},obstacle:"I wait for the pause to remove the feeling",stop:"Skip touch or recall. Stop if distressed and seek support when needed.",accessible:"Keep eyes open, ordinary breathing, and attention on the room. No body focus or warmth required.",result:"Did you take the next caring action you chose?",observation:"Did you act, adapt, stop, or ask for support?",scenario:{id:"compassion-3-upset-after-pause",scenario:"Sam uses a comfortable pause after feedback. He remains upset but can safely correct one clear draft error in two minutes. Four minutes remain before the draft check-in.",question:"What fits the purpose of the pause?",bestOptionId:"manageable-correction",options:[{id:"pause-and-correct-later",text:"Take another two-minute pause, then plan the correction after the check-in to avoid rushing the draft.",feedback:"More time can help when the task exceeds capacity. This safe correction fits before the check-in. Try the available minimum while upset, with permission to stop if overwhelmed."},{id:"manageable-correction",text:"Correct the clear error while upset, and choose support instead if the response becomes overwhelming.",feedback:"Relief is not the required result. The pause supports a feasible choice, including support when needed. Sam can record the actual correction without claiming the emotion changed."},{id:"review-broader-priorities",text:"Review the feedback's broader priorities first, then schedule the clear correction for the next draft session.",feedback:"A broader review can reveal what matters most. Here one necessary correction is already clear and fits the check-in. Make it now, then review the wider priorities separately."}]},takeaway:"A caring pause supports a choice. It does not have to produce a pleasant feeling.",follow:"After the pause, did you act, adapt, seek support, or need to stop?",followObservation:"Name the actual next step, and whether you used or skipped the pause.",depth:[{heading:"The break and the program are different",paragraphs:["Neff's developer instructions for a self-compassion break acknowledge hurt, recognize that struggle is part of human life, and offer kind words or a wish. Supportive touch is included in the original guidance. The instructions do not establish isolated efficacy or a proven two-minute dose. [C16: compassion-break-guidance] This lesson makes touch and recollection optional and adds a practical response as an ODA adaptation.","The Mindful Self-Compassion trial randomized 52 community adults to an eight-week program or waitlist. The program included weekly two-hour sessions and a four-hour retreat, with substantial daily practice encouraged. Controlled posttest results favored the program on several outcomes. Only 15 intervention participants responded at one year, without a concurrent control group. That follow-up cannot prove maintained controlled benefits for everyone, and the trial did not isolate the break. [C05: compassion-mindful-self-compassion-rct] Do not borrow a program effect to judge this small personal pause."]},{heading:"Touch and relief are separate choices",paragraphs:["Dreisoerner and colleagues studied optional self-soothing touch before a laboratory stressor in healthy young adults. Cortisol responses differed, while reported stress and heart rate did not. The trial did not measure oxytocin or establish lasting clinical improvement. A physiological result does not promise that you will feel better. [C14: compassion-touch-trial] The eyes-open, no-touch, ordinary-breathing options here are access and safety choices, not the exact studied touch protocol.","You can keep the whole practice verbal, use neutral words, or notice something outside yourself. No contact with another person is required. If a remembered event, touch, or inward focus increases discomfort, stop rather than pushing for warmth. Choose a simple supportive activity or human help. The next act might be a correction, a support request, or recovery. Record that actual act under its own minimum. A stopped pause is information; it does not require proving that you tried hard enough."]}],sources:["compassion-break-guidance","compassion-mindful-self-compassion-rct","compassion-touch-trial"]}),k=d({id:"compassion-4",title:"One more hour? Protect what work is costing",goal:"Check real risks, then take one practical boundary or support step within your continuing experiment.",hook:"Work keeps stretching into tonight. What real risk needs attention, and what keeps asking for more?",reason:"What is the extra work costing, and what real risk remains?",reasons:["Protect recovery after work","Keep time for people I care about","Address a real safety need"],paragraphs:["Gilbert's threat, drive, and soothing model is a clinical framework, not three brain switches. Ask whether more achievement addresses a real need or extends a loop. Practical protection and resources can affect safety; reassurance cannot replace them.","Use your same setback or pattern. If overwork keeps appearing, check actual deadlines and consequences before choosing a shutdown boundary. Real danger calls for practical help. Breathing and imagery are optional; an outward pause can suffice. Carry out the boundary or request without requiring calm, a clear inbox, or approval."],example:{title:"Mei's shutdown boundary",text:"At 9 p.m., Mei notices another late-work loop in her records. There is no urgent deadline. Seated at her desk, she looks at the lamp, names tomorrow's first priority, and closes the work apps. Worry remains. She leaves the desk for her planned recovery time and records the boundary. One unfinished email waits until morning."},invitation:"Check the real risk in your same pattern. Take one workable boundary or practical support step.",instructions:["Check deadlines, safety, and responsibilities before choosing a limit.","Carry out one boundary or support request."],suggestions:{action:["Close work apps at shutdown","Make one practical safety request","Communicate one workable task limit"],minimum:["Close work apps and step away","Make one support request","State one feasible task limit"],when:l,cue:["At my chosen shutdown time","When my existing pattern repeats"],place:["At my work desk","In a safe support channel"],minutes:[2,1,5],fallback:["Clarify an actual urgent responsibility","Ask for help making the boundary safe"],observation:["Whether I carried out the boundary","What real risk actually appeared"]},obstacle:"I keep working until worry disappears",stop:"Stop breath focus or imagery if uncomfortable. Actual danger needs practical protection and support.",accessible:"Stay seated, eyes open, and notice the room with ordinary breathing. No imagery or warmth required.",result:"Did you carry out your chosen boundary or request?",observation:"What limit did you use, and what actual consequence followed?",scenario:{id:"compassion-4-no-urgent-deadline",scenario:"Mei keeps working because she fears criticism. She has checked deadlines; nothing urgent remains. She has chosen a shutdown time to protect recovery.",question:"Which move tests that boundary?",bestOptionId:"priority-and-close",options:[{id:"priority-and-close",text:"Note tomorrow's first priority and close the work apps at the chosen time, with worry allowed to remain.",feedback:"This addresses the recurring behavior and preserves tomorrow's task. Mei can test a feasible boundary without clearing every email or forcing calm. A real urgent risk would need a different response."},{id:"finish-tomorrow-task",text:"Finish tomorrow's first priority tonight so she can stop with evidence that the important work is covered.",feedback:"Finishing may feel safer, but no urgent deadline requires it. It extends the same loop the chosen boundary addresses. Keep the priority note and test stopping at the agreed time."},{id:"scan-before-closing",text:"Close the apps after a five-minute email scan to check that no deadline was overlooked.",feedback:"A last check can be useful when urgency is unknown. Mei already checked deadlines. Another scan delays her chosen boundary; note tomorrow's priority and close the apps."}]},takeaway:"Check the real risk. Let care become a practical limit, resource, or support request.",follow:"Was the boundary tested, and did a new risk appear, remain absent, or stay unclear?",followObservation:"What time or resource did you protect, and what actual consequence appeared?",depth:[{heading:"A clinical map, not three brain switches",paragraphs:["Gilbert's clinical review uses threat, pursuit or drive, and affiliative soothing as a simplified functional framework. It describes compassion-focused therapy and practitioner exercises. It is not an experiment demonstrating three discrete brain circuits, an isolated exhale effect, or a literal threat-system off switch. [C07: compassion-gilbert-cft] Comfortable breathing and compassionate imagery can be optional practices, with immediate permission to stop.","The model also cannot decide whether a danger is real. A housing problem, insufficient income, health need, or unsafe relationship may require resources and practical changes. Practical resources and protection can affect safety. Check what additional work would actually accomplish in this situation. Where no urgent responsibility remains, a boundary may be a useful experiment. Where risk remains, protection or support can be the caring act. Your continuing record distinguishes those cases. A priority note prepares a shutdown; closing the work apps and stepping away carries it out."]},{heading:"No meditation winner and no required warm feeling",paragraphs:["Zeng and colleagues reviewed 24 empirical studies involving 1,759 participants, mixing designs. In a relevant subgroup analysis, the loving-kindness estimate was 0.424 and the compassion estimate 0.286. The subgroup difference was not significant, so these estimates do not establish a better practice. They also do not show compassion has no effect or estimate an ODA soothing exercise. [C10: compassion-kindness-review]","The developer's practice guidance distinguishes a kind intention from producing pleasant feelings and advises pulling back when practice overwhelms. [C12: compassion-practice-safety] Use an outward anchor, ordinary activity, or support instead of imagery if that fits. Do not label discomfort as a physiological backdraft mechanism or a new diagnosis. The measure here is the boundary or practical request actually made. Worry may remain after shutdown, and another person may disagree. Those observations can inform the next version without turning the exercise into a demand for warmth."]}],sources:["compassion-gilbert-cft","compassion-kindness-review","compassion-practice-safety"]}),x=d({id:"compassion-5",title:"Feeling ashamed? Check whose responsibility it is",goal:"Check actual responsibility in your same setback, then take one appropriate repair, protection, or support step.",hook:"Are you avoiding a repair you owe, or accepting blame that belongs elsewhere? Start with the facts.",reason:"What would misplaced blame make you overlook or accept?",reasons:["Repair harm I actually caused","Reject unfair blame","Ask for safe support"],paragraphs:["Whole-self shame commonly relates to hiding or defensiveness. Behavior-focused guilt can relate to empathy and repair. These are tendencies: excessive guilt can harm, and shame after victimization does not prove wrongdoing.","At your same setback, check what you did and whether it caused harm. Choose proportionate repair for actual harm, protection or support for mistreatment. You may name the feeling privately and check the expectation. Disclosure is optional, only to someone safe and willing. Take one fitting step; rewritten words alone do not complete repair."],example:{title:"Jonas's responsibility check",text:"At lunch, Jonas revisits a harsh remark he made to a coworker. He identifies the words and their impact without calling himself a bad person. In a private message, he apologizes for that specific remark and corrects the information he gave. The coworker does not reply that day. Jonas records the repair, without asking for reassurance or forgiveness."},invitation:"Check the facts in your same setback. Choose repair for actual harm, otherwise protection or support.",instructions:["Identify actual responsibility before choosing an apology.","Take one safe repair, protection, or support step."],suggestions:{action:["Make one appropriate factual repair","Make one safe support request","Carry out one protective boundary"],minimum:["Correct one harm I caused","Make one support request","State one safe boundary"],when:l,cue:["After checking my actual responsibility","At my existing setback cue"],place:["In a safe private message","In my trusted support space"],minutes:[2,1,5],fallback:["Seek support before unsafe contact","Use a safe correction without disclosure"],observation:["The facts and path I chose","The repair or protection actually done"]},obstacle:"I treat shame as proof that I caused harm",stop:"No apology, forgiveness, or unsafe contact is owed because you feel ashamed. Seek protection for danger.",accessible:"Keep reflection private. Use neutral words, type, sign, or request assistance. Disclosure and body focus are optional.",result:"Did you take the fitting step you chose?",observation:"What responsibility did the facts show, and what did you actually do?",scenario:{id:"compassion-5-imposed-shame",scenario:"A colleague mocks Inez publicly after she makes a correct point. She feels ashamed. The facts show no mistake or harm she caused.",question:"Which next step fits?",bestOptionId:"support-not-blame",options:[{id:"apologize-tension",text:"Apologize for contributing to the tension so the colleague has a chance to respond more constructively.",feedback:"Repair follows actual responsibility. The scenario supplies none for Inez. An apology would invent blame and obscure the mocking. Consider support or a safe boundary instead."},{id:"normalize-and-ignore",text:"Remind herself that everyone has difficult days and leave the incident alone to preserve the working relationship.",feedback:"Shared humanity does not excuse harmful treatment or settle the safety decision. Inez can keep context in mind while seeking appropriate support. She need not confront the colleague directly."},{id:"support-not-blame",text:"Recognize the shame, keep the facts clear, and choose safe support or a boundary without inventing wrongdoing.",feedback:"Shame does not establish culpability. Inez can address the mocking through a safe route without apologizing for a nonexistent mistake or proving that she deserves respectful treatment."}]},takeaway:"Feelings deserve care. Responsibility needs facts. Choose repair, protection, or support accordingly.",follow:"Did the facts call for repair, protection, practical support, or further clarification?",followObservation:"Name your chosen path and actual step, without disclosing details you prefer to keep private.",depth:[{heading:"Shame and guilt describe tendencies",paragraphs:["Tangney and colleagues reviewed moral emotions and behavior, primarily through observational research. Whole-self shame commonly related to withdrawal or defensive responses; behavior-focused guilt could relate to empathy and repair. Context and measurement matter, and the review does not establish that shame is always destructive or guilt always useful. Excessive or ruminative guilt can also be harmful. [C08: compassion-tangney-moral-emotions]","Shame can follow abuse, exclusion, discrimination, or illness without misconduct by the person who feels it. Do not convert that feeling into a wrongdoing sentence just to fit a repair exercise. First identify an actual behavior and its consequences. A proportionate apology may fit harm you caused, with no demand that the other person reassure or forgive you. Where blame is imposed, support and protection can fit better. Changing a sentence alone does not establish a causal transition from shame to useful guilt or prove that repair happened."]},{heading:"A framework with optional safe disclosure",paragraphs:["Brown developed shame resilience theory through interviews with 215 women. Recognizing shame and its triggers, reality-checking expectations, finding safe connection, and naming shame belong to this qualitative and practitioner framework. The source does not verify a controlled treatment trial of the four-step sequence or demonstrate that required disclosure improves outcomes. [C09: compassion-brown-shame-resilience]","Use any element that serves your next choice, with no need to recall trauma, scan the body, or tell a story. A safe willing person can be helpful, but one may not be available. Private reflection, a professional support request, a factual correction, or a protective boundary are alternatives. Do not disclose to an abuser or someone likely to use the information against you. Persistent or overwhelming shame deserves qualified support. Your continuing experiment asks what fitting action happened and what its response showed, not whether you named every feeling or completed a prescribed sequence."]}],sources:["compassion-tangney-moral-emotions","compassion-brown-shame-resilience"]}),A=d({id:"compassion-6",title:"Another kind note? Make the next change real",goal:"Consolidate your same experiment from actual attempts and take one feasible repair, protection, or support step.",hook:"A kind note can help. What useful change would its advice ask you to make today?",reason:"What useful change would another note postpone?",reasons:["Follow through on a real repair","Protect a workable boundary","Use support instead of self-attack"],paragraphs:["The friend letter is developer guidance: offer care and suggestions for change. Fifteen minutes is not a verified optimal dose. The program trial did not isolate the letter or retain a comparison group at one year.","Review your same pattern's records. Which response led to repair, protection, work, or support? Keep what helped; change one obstacle. An optional note can name truth, context, care, and a fitting step. Do the step if appropriate; schedule the next realistic opening. No warmth, forgiveness, or perfect streak is needed."],example:{title:"Rosa's next workable version",text:"On Sunday at 7 p.m., Rosa reviews her records of avoiding administrative letters. A short factual note helped; a long self-criticism replay did not. At her kitchen table, she writes four caring sentences, corrects one filing error, and asks for help with an unclear notice. The larger pile remains. She keeps the useful minimum for Wednesday, without promising instant relief."},invitation:"Review your same experiment. Keep what helped, change one obstacle, and do one fitting next step.",instructions:["Use actual attempts; leave missing results unknown.","Make one repair, protection, task, or support step real."],suggestions:{action:["Correct my next practical item","Use my tested protective boundary","Send my specific support request"],minimum:["Correct one actual item","State one workable boundary","Make one specific request"],when:l,cue:["After reviewing my actual attempts","At my next tested useful cue"],place:["At my kitchen table","In my safe support channel"],minutes:[3,2,5],fallback:["Ask for help with the obstacle","Shrink the step or pause deliberately"],observation:["The step and support actually used","What I kept or changed"]},obstacle:"Writing comfort replaces the useful change",stop:"Stop painful recall or writing if distressed. Repair requires actual responsibility; protection may fit instead.",accessible:"The letter is optional. Use four neutral sentences silently, type, sign, or request help. No warmth required.",result:"Did you take the practical step you chose?",observation:"What did you keep, change, or request, and what actually happened?",scenario:{id:"compassion-6-boundary-after-review",scenario:"Rosa checked her budget: lending would use money needed for this week's essentials. No request is pending. She can set those funds aside today without contacting anyone.",question:"What should the review lead to?",bestOptionId:"reserve-essential-funds",options:[{id:"draft-future-refusal",text:"Draft a kind but clear refusal for the next request, keeping today's funds available until that opening.",feedback:"Drafting a refusal is useful preparation for a later boundary. It leaves the essential funds available for lending today. Set them aside now; record any later communication as a separate act."},{id:"reserve-essential-funds",text:"Set aside the amount needed for essentials today and prepare a safe limit for any later request.",feedback:"Setting funds aside changes what is available for lending today. Writing the limit or rehearsing its message alone is preparation. No immediate contact or promise of improved feelings is needed."},{id:"budget-and-support",text:"Review the budget with a trusted support person before deciding what lending limit to put in place.",feedback:"Support can help when affordability or safety is unclear. Rosa already knows essentials would be affected and can reserve them safely today. Ask for help with future requests afterward."}]},takeaway:"Let care tell the truth, then use your records to make the next step fit.",follow:"Which practical path did your next version take, and which condition deserves repeating?",followObservation:"Name what you carried out; leave a written limit as preparation until it is used.",depth:[{heading:"The optional letter supports a real choice",paragraphs:["Neff's friend-letter guidance invites a caring perspective from someone who knows your strengths, weaknesses, and circumstances. It includes kind suggestions for change and setting the letter aside to reread later. The page documents an exercise, not an isolated efficacy test or validated fifteen-minute dose. [C17: compassion-letter-guidance] This lesson's four-sentence option and practical follow-through are ODA adaptations.","Choose an ordinary manageable setback if you write. You do not need an insecurity inventory, a suffering story, unconditional warm feelings, or an available friend. Neutral respect can do the job: state the truth, relevant context, useful care, and the fitting next act. Repair belongs to actual responsibility; protection belongs where a limit or safety response is needed. A completed letter can be recorded as preparation, while the practical correction or support request has its own minimum. A written lending limit remains preparation until resources are actually reserved or the boundary is used at a safe opportunity."]},{heading:"Your records choose the next week",paragraphs:["Neff's tender and fierce language describes practitioner forms of care: comfort and acceptance, alongside protection, boundaries, and goal pursuit. They are not independently proven brain systems. [C11: compassion-neff-definition] Use the language only if it helps inspect your actual pattern. A comforting note that postpones a needed change and a harsh plan that ignores capacity can each need revision.","The Mindful Self-Compassion study tested an eight-week bundle against a waitlist. Its incomplete one-year follow-up had no concurrent control; it does not establish a lasting letter effect. [C05: compassion-mindful-self-compassion-rct] Your capstone therefore uses the attempts you actually reported. Keep one useful response, change one obstacle, and choose the next dated opportunity. There is no need to add a ritual or compensate for a pause. If the pattern still needs resources, assistance, or professional support, name that need honestly. Course completion does not prove repair, relief, or practice. Let the next record show what happened."]}],sources:["compassion-letter-guidance","compassion-neff-definition","compassion-mindful-self-compassion-rct"]}),U=[{id:"compassion-1",practiceCount:3,correct:0,photo:{id:"1474418397713-7ede21d49118",alt:"A person sitting on a rock, watching the sun rise over the mountains"}},{id:"compassion-2",practiceCount:3,correct:0,photo:{id:"1529156069898-49953e39b3ac",alt:"Friends sitting arm in arm, seen from behind"}},{id:"compassion-3",practiceCount:3,correct:0,photo:{id:"1499209974431-9dddcece7f88",alt:"A person opening their arms toward the setting sun"}},{id:"compassion-4",practiceCount:3,correct:0,photo:{id:"1441974231531-c6227db76b6e",alt:"Sunlight falling through a calm forest"}},{id:"compassion-5",practiceCount:3,correct:0,photo:{id:"1544027993-37dbfe43562a",alt:"Two hands reaching toward each other"}},{id:"compassion-6",practiceCount:3,correct:0,photo:{id:"1455390582262-044cdead277a",alt:"A hand writing in a notebook with a pen"}}];function L(e,t){const a=U[t],n=e.judgment.primary.options.find(c=>c.id===e.judgment.primary.bestOptionId),i=e.judgment.primary.options.filter(c=>c.id!==n.id).map(c=>c.text);return i.splice(a.correct,0,n.text),{id:a.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,practice:[e.move.instructions[0],e.move.suggested.action,"Record the actual outcome and choose the next appropriate attempt."].slice(0,a.practiceCount),reflection:e.direction.reason.label,question:`${e.judgment.primary.scenario} ${e.judgment.primary.question}`,options:i,correct:a.correct,feedback:n.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds,photo:a.photo}}const j={id:"compassion",title:"Another mistake? Get specific without tearing yourself down",subtitle:"6 lessons. Carry one setback toward repair, protection, or support, without demanding a warmer feeling.",description:"Keep standards and facts while dropping contempt. Use one continuing experiment to choose useful care, check responsibility, and make the next appropriate step real.",scope:"For adults who are hard on themselves after mistakes, setbacks or painful moments. It is education and self-practice, not therapy. If you live with trauma, abuse, or shame that is persistent or overwhelming, please work with a qualified professional; self-compassion exercises can sometimes stir up old pain. If you are in crisis or thinking about harming yourself, contact your local emergency number now.",outcome:"One fair response to a recurring setback, an appropriate repair or protective action, and a workable next attempt.",photo:{id:"1470252649378-9c29740c9fa8",alt:"A quiet field in warm evening light"},lessons:[w,b,v,k,x,A].map(L)},_=Object.freeze(Object.defineProperty({__proto__:null,COMPASSION_1_V2:w,COMPASSION_2_V2:b,COMPASSION_3_V2:v,COMPASSION_4_V2:k,COMPASSION_5_V2:x,COMPASSION_6_V2:A,COURSE:j,SOURCES:M},Symbol.toStringTag,{value:"Module"}));export{E as a,Y as b,K as c,B as d,_ as e,z as f};
